                                        let mut peer_mlp_up_max_abs = 0.0f32;
                                        let mut peer_mlp_swiglu_max_abs = 0.0f32;
                                        let mut peer_mlp_down_max_rel = 0.0f32;
                                        let mut peer_mlp_down_max_abs = 0.0f32;
                                        let mut peer_mlp_down_max_rank = 0usize;
                                        let mut peer_mlp_down_max_dim = 0usize;
