                max_mismatch += count_byte_mismatches(got_v_row, &expected_v.packed)?;
                max_mismatch += count_byte_mismatches(got_ks, &expected_k.scale)?;
                max_mismatch += count_byte_mismatches(got_vs, &expected_v.scale)?;
