                    unsafe { vc.as_mut_slice_of::<u8>()[..cache_plan.cache_bytes()].to_vec() };
                let got_layer11_attn_v_scale =
                    unsafe { sv.as_mut_slice_of::<u8>()[..cache_plan.scale_bytes()].to_vec() };
                let expected_attn_v =
                    decode_fp4_row_from_cache(&got_layer11_attn_v_cache[..64], &got_layer11_attn_v_scale[..4])?;
                let mut max_abs = 0.0f32;
                let mut max_head = 0usize;
                let mut max_dim = 0usize;
                let mut min_l = f32::INFINITY;
                let mut max_l = 0.0f32;
                for head in 0..attn_plan.real_q_heads as usize {
                    let base = head * attn_plan.partial_stride();
                    let l = partials[base + 1];
                    if !(l > 0.0) {
                        anyhow::bail!(
                            "layer11 single-row attention softmax L must be positive: head={head} l={l}"
                        );
                    }
                    min_l = min_l.min(l);
                    max_l = max_l.max(l);
                    for dim in 0..attn_plan.head_dim as usize {
                        let got = partials[base + 2 + dim] / l;
                        let diff = (got - expected_attn_v[dim]).abs();
                        if diff > max_abs {
                            max_abs = diff;
                            max_head = head;
                            max_dim = dim;
                        }
                    }
                }
