                println!("    kernel_q_heads: {}", attn_plan.kernel_q_heads);
                println!("    kv_heads_local: {}", cache_plan.kv_heads);
                println!("    q_heads_per_kv_kernel: {}", attn_plan.kernel_q_heads_per_kv);
                println!("    head_dim: {}", attn_plan.head_dim);
                println!("    block_size: {}", cache_plan.block_size);
                println!("    attention_tokens: {}", cache_plan.physical_blocks * cache_plan.block_size);
                println!("    block_table_first: 0");
                println!("    softmax_l_head0: {:.6}", head0_l);
                println!("    softmax_l_min: {:.6}", min_l);
                println!("    softmax_l_max: {:.6}", max_l);
                println!(
                    "    normalized_output_max_abs: {:.6} at head {} dim {} l {:.6}",
                    max_abs,
                    max_head,
                    max_dim,
                    max_head_l
                );
                println!("    attn_f16_first: 0x{attn_first:04x} expected 0x{attn_first_expected:04x}");
                println!("    attn_f16_last: 0x{attn_last:04x} expected 0x{attn_last_expected:04x}");
                println!(
                    "    attn_f16_max_abs: {:.6} at dim {}",
                    attn_cmp.max_abs,
                    attn_cmp.max_dim
                );
                println!("    partial_f32s: {}", attn_plan.partial_f32s());
                println!(
                    "    attention_append_gpu_wait_us: {:.3}",
                    layer11_attn_append_wait.as_secs_f64() * 1e6
                );
                println!(
                    "    attention_append_wall_us: {:.3}",
                    layer11_attn_append_wall.as_secs_f64() * 1e6
                );
                println!(
                    "    attention_gpu_wait_us: {:.3}",
                    layer11_attn_wait.as_secs_f64() * 1e6
                );
                println!(
                    "    attention_wall_us: {:.3}",
                    layer11_attn_wall.as_secs_f64() * 1e6
                );
