                                                                                                                                    layer16_peer_mlp_gate_max_rel =
                                                                                                                                        layer16_peer_mlp_gate_max_rel.max(proof.gate_max_rel);
                                                                                                                                    layer16_peer_mlp_gate_max_abs =
                                                                                                                                        layer16_peer_mlp_gate_max_abs.max(proof.gate_max_abs);
                                                                                                                                    layer16_peer_mlp_up_max_rel =
                                                                                                                                        layer16_peer_mlp_up_max_rel.max(proof.up_max_rel);
                                                                                                                                    layer16_peer_mlp_up_max_abs =
                                                                                                                                        layer16_peer_mlp_up_max_abs.max(proof.up_max_abs);
                                                                                                                                    layer16_peer_mlp_swiglu_max_abs =
                                                                                                                                        layer16_peer_mlp_swiglu_max_abs.max(proof.swiglu_max_abs);
