                                                                                                                                                                        peer_workspace.gate_w.as_mut_slice_of::<u8>()
                                                                                                                                                                            [..peer_workspace.gate_weight_bytes.len()]
                                                                                                                                                                            .copy_from_slice(&peer_workspace.gate_weight_bytes);
                                                                                                                                                                        peer_workspace.up_w.as_mut_slice_of::<u8>()
                                                                                                                                                                            [..peer_workspace.up_weight_bytes.len()]
                                                                                                                                                                            .copy_from_slice(&peer_workspace.up_weight_bytes);
                                                                                                                                                                        peer_workspace.down_w.as_mut_slice_of::<u8>()
                                                                                                                                                                            [..peer_workspace.down_weight_bytes.len()]
                                                                                                                                                                            .copy_from_slice(&peer_workspace.down_weight_bytes);
