#[derive(Clone, Copy)]
struct QwenResidentLayerRunnerDagSchedulerContext<'a> {
    descriptor_va: u64,
    descriptor_bytes: usize,
    dag_rows: &'a [QwenResidentLayerRunnerDagEdgeRow],
}

fn qwen_resident_layer_runner_mlp_dag_completion_edge_index(
    dag_rows: &[QwenResidentLayerRunnerDagEdgeRow],
    layer_idx: Option<u32>,
) -> Result<Option<u32>> {
    let Some(layer_idx) = layer_idx else {
        return Ok(None);
    };
    let mut matches = dag_rows.iter().filter(|row| {
        row.layer_idx == layer_idx && row.kind == QwenResidentLayerRunnerDispatchKind::Mlp
    });
    let Some(row) = matches.next() else {
        return Ok(None);
    };
    if let Some(duplicate) = matches.next() {
        anyhow::bail!(
            "resident MLP DAG edge lookup found duplicate MLP rows for layer {}: edges {} and {}",
            layer_idx,
            row.edge_index,
            duplicate.edge_index
        );
    }
    Ok(Some(row.edge_index))
}

fn qwen_resident_layer_runner_attention_dag_edge_index(
    dag_rows: &[QwenResidentLayerRunnerDagEdgeRow],
    layer_idx: Option<u32>,
) -> Result<Option<u32>> {
    let Some(layer_idx) = layer_idx else {
        return Ok(None);
    };
    let mut matches = dag_rows.iter().filter(|row| {
        row.layer_idx == layer_idx
            && row.kind == QwenResidentLayerRunnerDispatchKind::DecodeAttention
    });
    let Some(row) = matches.next() else {
        return Ok(None);
    };
    if let Some(duplicate) = matches.next() {
        anyhow::bail!(
            "resident attention DAG edge lookup found duplicate attention rows for layer {}: edges {} and {}",
            layer_idx,
            row.edge_index,
            duplicate.edge_index
        );
    }
    Ok(Some(row.edge_index))
}
