const QWEN_MLP_SEQUENTIAL_GPU_TICK_END_SENTINEL: u64 = 0x514D_4C50_5351_5442;

#[derive(Clone, Copy)]
struct QwenMlpReplayBenchStats {
    p50_us: f64,
    p90_us: f64,
    p99_us: f64,
    avg_us: f64,
    min_us: f64,
    max_us: f64,
}

fn qwen_mlp_replay_bench_stats(samples: &[f64]) -> Result<QwenMlpReplayBenchStats> {
    if samples.is_empty() {
        anyhow::bail!("Qwen MLP replay benchmark needs at least one sample");
    }
    let mut sorted = samples.to_vec();
    sorted.sort_by(|a, b| a.total_cmp(b));
    let percentile = |p: f64| -> f64 {
        let idx = ((sorted.len() - 1) as f64 * p).round() as usize;
        sorted[idx.min(sorted.len() - 1)]
    };
    let sum: f64 = sorted.iter().sum();
    Ok(QwenMlpReplayBenchStats {
        p50_us: percentile(0.50),
        p90_us: percentile(0.90),
        p99_us: percentile(0.99),
        avg_us: sum / sorted.len() as f64,
        min_us: sorted[0],
        max_us: sorted[sorted.len() - 1],
    })
}

fn qwen_print_next_decode_mlp_kernel_chain() {
    println!("    kernels: {QWEN_NEXT_DECODE_MLP_KERNEL_CHAIN}");
}

fn qwen_next_decode_mlp_env_flag(name: &str, default: bool) -> bool {
    match std::env::var(name) {
        Ok(value) => {
            let value = value.trim();
            !(value.is_empty()
                || value == "0"
                || value.eq_ignore_ascii_case("false")
                || value.eq_ignore_ascii_case("off"))
        }
        Err(_) => default,
    }
}

fn qwen_next_decode_mlp_env_enabled(name: &str) -> bool {
    qwen_next_decode_mlp_env_flag(name, false)
}

