fn qwen_resident_layer_runner_stage_mask(entry: &QwenResidentLayerRunnerEntry) -> u64 {
    let mut mask = 0u64;
    if entry.input_norm {
        mask |= 1 << 0;
    }
    if entry.qkv {
        mask |= 1 << 1;
    }
    if entry.qk_norm_rope {
        mask |= 1 << 2;
    }
    if entry.fp4_kv_cache {
        mask |= 1 << 3;
    }
    if entry.fp4_attention {
        mask |= 1 << 4;
    }
    if entry.o_proj {
        mask |= 1 << 5;
    }
    if entry.post_attn_norm {
        mask |= 1 << 6;
    }
    if entry.tp_o_proj_peer {
        mask |= 1 << 7;
    }
    if entry.mlp {
        mask |= 1 << 8;
    }
    if entry.tp_mlp_peer {
        mask |= 1 << 9;
    }
    mask
}

fn qwen_resident_layer_runner_dispatch_mask(entry: &QwenResidentLayerRunnerEntry) -> u64 {
    let mut mask = 0u64;
    if entry.decode_attention_ready() {
        mask |= 1 << 0;
    }
    if entry.mlp_ready() {
        mask |= 1 << 1;
    }
    if entry.decode_attention_launch_eligible() {
        mask |= 1 << 2;
    }
    if entry.mlp_launch_eligible() {
        mask |= 1 << 3;
    }
    if entry.full_layer_launch_eligible() {
        mask |= 1 << 4;
    }
    mask
}

fn qwen_resident_layer_runner_readiness_mask(entry: &QwenResidentLayerRunnerEntry) -> u64 {
    let mut mask = 0u64;
    if entry.f32_residual_required {
        mask |= 1 << 0;
    }
    if entry.weights_resident {
        mask |= 1 << 1;
    }
    if entry.kv_resident {
        mask |= 1 << 2;
    }
    if entry.upstream_ready {
        mask |= 1 << 3;
    }
    if entry.graph_shape_ready {
        mask |= 1 << 4;
    }
    mask
}

fn qwen_resident_layer_runner_residual_descriptor_mask(
    entry: &QwenResidentLayerRunnerEntry,
) -> u64 {
    let mut mask = 0u64;
    if entry.residual_contract.storage == QwenResidentResidualStorage::Bf16 {
        mask |= 1 << 0;
    }
    if entry.residual_contract.transition_from_f16_to_bf16 {
        mask |= 1 << 1;
    }
    mask
}

fn qwen_resident_layer_runner_pack_descriptor(
    entry: &QwenResidentLayerRunnerEntry,
    row_idx: usize,
) -> Result<[u64; QWEN_RESIDENT_LAYER_RUNNER_PACKED_DESCRIPTOR_U64S]> {
    qwen_resident_layer_runner_validate_entry_contract(entry, "packed descriptor")?;
    let attention_ops = if entry.decode_attention_ready() {
        7u64
    } else {
        0u64
    };
    let mlp_ops = if entry.mlp_ready() { 4u64 } else { 0u64 };
    Ok([
        QWEN_RESIDENT_LAYER_RUNNER_PACKED_DESCRIPTOR_MAGIC,
        QWEN_RESIDENT_LAYER_RUNNER_PACKED_DESCRIPTOR_VERSION | ((row_idx as u64) << 32),
        entry.layer_idx as u64 | ((entry.residual_contract.layer_idx as u64) << 32),
        qwen_resident_layer_runner_stage_mask(entry),
        qwen_resident_layer_runner_dispatch_mask(entry),
        qwen_resident_layer_runner_residual_descriptor_mask(entry),
        qwen_resident_layer_runner_readiness_mask(entry),
        attention_ops | (mlp_ops << 32),
    ])
}

fn qwen_resident_layer_runner_packed_descriptor_bytes(
    descriptors: &[[u64; QWEN_RESIDENT_LAYER_RUNNER_PACKED_DESCRIPTOR_U64S]],
) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(
        descriptors.len()
            * QWEN_RESIDENT_LAYER_RUNNER_PACKED_DESCRIPTOR_U64S
            * std::mem::size_of::<u64>(),
    );
    for descriptor in descriptors {
        for word in descriptor {
            bytes.extend_from_slice(&word.to_le_bytes());
        }
    }
    bytes
}

fn qwen_resident_layer_runner_descriptor_checksum(bytes: &[u8]) -> u64 {
    let mut checksum = 0xcbf29ce484222325u64;
    for byte in bytes {
        checksum ^= *byte as u64;
        checksum = checksum.wrapping_mul(0x100000001b3);
    }
    checksum
}

fn qwen_resident_layer_runner_packed_descriptors_from_entries(
    entries: &[QwenResidentLayerRunnerEntry],
) -> Result<Vec<[u64; QWEN_RESIDENT_LAYER_RUNNER_PACKED_DESCRIPTOR_U64S]>> {
    if entries.is_empty() {
        anyhow::bail!("resident layer runner packed descriptor table requires at least one entry");
    }
    let mut seen_layers = std::collections::BTreeSet::new();
    let mut descriptors = Vec::with_capacity(entries.len());
    for (row_idx, entry) in entries.iter().enumerate() {
        if !seen_layers.insert(entry.layer_idx) {
            anyhow::bail!(
                "resident layer runner packed descriptor table has duplicate layer {}",
                entry.layer_idx
            );
        }
        descriptors.push(qwen_resident_layer_runner_pack_descriptor(entry, row_idx)?);
    }
    Ok(descriptors)
}

fn qwen_resident_layer_runner_upload_packed_descriptor_table(
    dev: &mut mcore::GpuDevice,
    entries: &[QwenResidentLayerRunnerEntry],
) -> Result<(mcore::DeviceBuffer, usize, usize, u64, u64)> {
    let descriptors = qwen_resident_layer_runner_packed_descriptors_from_entries(entries)?;
    let bytes = qwen_resident_layer_runner_packed_descriptor_bytes(&descriptors);
    let checksum = qwen_resident_layer_runner_descriptor_checksum(&bytes);
    let mut buffer = dev.alloc_device(bytes.len())?;
    qwen_resident_layer_runner_validate_dispatch_buffer(
        "packed descriptor upload",
        u32::MAX,
        "descriptor_table",
        0,
        &mut buffer,
        bytes.len(),
    )?;
    unsafe {
        buffer.as_mut_slice_of::<u8>()[..bytes.len()].copy_from_slice(&bytes);
    }
    let va = buffer.va();
    Ok((buffer, descriptors.len(), bytes.len(), checksum, va))
}

fn qwen_resident_layer_runner_pack_dag_edge_descriptor(
    row: &QwenResidentLayerRunnerDagEdgeRow,
) -> [u64; QWEN_RESIDENT_LAYER_RUNNER_PACKED_DAG_EDGE_U64S] {
    [
        QWEN_RESIDENT_LAYER_RUNNER_PACKED_DAG_EDGE_MAGIC,
        QWEN_RESIDENT_LAYER_RUNNER_PACKED_DAG_EDGE_VERSION | (u64::from(row.edge_index) << 32),
        u64::from(row.layer_idx) | (qwen_resident_layer_runner_dispatch_kind_code(row.kind) << 32),
        row.wait_mask,
        row.signal_mask,
        u64::from(row.downstream_edge_index),
        row.downstream_wait_mask,
        row.checksum_fnv1a64,
    ]
}

fn qwen_resident_layer_runner_packed_dag_edge_descriptor_bytes(
    descriptors: &[[u64; QWEN_RESIDENT_LAYER_RUNNER_PACKED_DAG_EDGE_U64S]],
) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(
        descriptors.len()
            * QWEN_RESIDENT_LAYER_RUNNER_PACKED_DAG_EDGE_U64S
            * std::mem::size_of::<u64>(),
    );
    for descriptor in descriptors {
        for word in descriptor {
            bytes.extend_from_slice(&word.to_le_bytes());
        }
    }
    bytes
}

fn qwen_resident_layer_runner_packed_dag_edge_descriptors_from_rows(
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> Result<Vec<[u64; QWEN_RESIDENT_LAYER_RUNNER_PACKED_DAG_EDGE_U64S]>> {
    if rows.is_empty() {
        anyhow::bail!("resident layer runner packed DAG edge table requires at least one row");
    }
    qwen_resident_layer_runner_validate_plan_dag_edge_rows(rows)?;
    Ok(rows
        .iter()
        .map(qwen_resident_layer_runner_pack_dag_edge_descriptor)
        .collect())
}

fn qwen_resident_layer_runner_upload_packed_dag_edge_table(
    dev: &mut mcore::GpuDevice,
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> Result<(mcore::DeviceBuffer, usize, usize, u64, u64)> {
    let descriptors = qwen_resident_layer_runner_packed_dag_edge_descriptors_from_rows(rows)?;
    let bytes = qwen_resident_layer_runner_packed_dag_edge_descriptor_bytes(&descriptors);
    let checksum = qwen_resident_layer_runner_descriptor_checksum(&bytes);
    let mut buffer = dev.alloc_device(bytes.len())?;
    qwen_resident_layer_runner_validate_dispatch_buffer(
        "packed DAG edge descriptor upload",
        u32::MAX,
        "dag_edge_descriptor_table",
        0,
        &mut buffer,
        bytes.len(),
    )?;
    unsafe {
        buffer.as_mut_slice_of::<u8>()[..bytes.len()].copy_from_slice(&bytes);
    }
    let va = buffer.va();
    Ok((buffer, descriptors.len(), bytes.len(), checksum, va))
}

fn qwen_swiglu_descriptor_checksum(words: &[u64]) -> u64 {
    let mut checksum = 0xcbf29ce484222325u64;
    for word in words {
        for byte in word.to_le_bytes() {
            checksum ^= byte as u64;
            checksum = checksum.wrapping_mul(0x100000001b3);
        }
    }
    checksum
}

fn qwen_upload_swiglu_descriptor(
    dev: &mut mcore::GpuDevice,
    gate_va: u64,
    up_va: u64,
    y_va: u64,
    n: u32,
    nthreads: u32,
) -> Result<(mcore::DeviceBuffer, u64)> {
    if n == 0 || nthreads == 0 {
        anyhow::bail!(
            "SwiGLU descriptor requires non-zero n and nthreads: n={n} nthreads={nthreads}"
        );
    }
    let mut words = [0u64; QWEN_SWIGLU_DESCRIPTOR_WORDS];
    words[0] = QWEN_SWIGLU_DESCRIPTOR_MAGIC;
    words[1] = QWEN_SWIGLU_DESCRIPTOR_VERSION;
    words[2] = gate_va;
    words[3] = up_va;
    words[4] = y_va;
    words[5] = n as u64 | ((nthreads as u64) << 32);
    words[6] = 0;
    words[7] = qwen_swiglu_descriptor_checksum(&words[..7]);

    let mut descriptor =
        dev.alloc_device(QWEN_SWIGLU_DESCRIPTOR_WORDS * std::mem::size_of::<u64>())?;
    unsafe {
        descriptor.as_mut_slice_of::<u64>()[..QWEN_SWIGLU_DESCRIPTOR_WORDS].copy_from_slice(&words);
    }
    Ok((descriptor, words[7]))
}

fn qwen_validate_swiglu_descriptor_status(
    status_buffer: &mut mcore::DeviceBuffer,
    expected_gate_va: u64,
    expected_up_va: u64,
    expected_y_va: u64,
    expected_n: u32,
    expected_checksum: u64,
) -> Result<[u64; QWEN_SWIGLU_DESCRIPTOR_STATUS_WORDS]> {
    let status = unsafe {
        let words = status_buffer.as_mut_slice_of::<u64>();
        [
            words[0], words[1], words[2], words[3], words[4], words[5], words[6], words[7],
            words[8], words[9],
        ]
    };
    if status[9] != QWEN_SWIGLU_DESCRIPTOR_STATUS_SENTINEL {
        anyhow::bail!(
            "SwiGLU descriptor kernel did not write sentinel: got 0x{:016x}",
            status[9]
        );
    }
    if status[0] != 0 {
        anyhow::bail!(
            "SwiGLU descriptor kernel failed: status={} bad_value=0x{:016x} checksum=0x{:016x} expected=0x{:016x}",
            status[0],
            status[8],
            status[3],
            status[4]
        );
    }
    if status[1] != expected_n as u64 || status[2] == 0 {
        anyhow::bail!(
            "SwiGLU descriptor kernel returned wrong shape: n={} nthreads={}",
            status[1],
            status[2]
        );
    }
    if status[3] != expected_checksum || status[4] != expected_checksum {
        anyhow::bail!(
            "SwiGLU descriptor checksum mismatch: computed=0x{:016x} expected=0x{:016x}",
            status[3],
            expected_checksum
        );
    }
    if status[5] != expected_gate_va || status[6] != expected_up_va || status[7] != expected_y_va {
        anyhow::bail!(
            "SwiGLU descriptor pointer echo mismatch: gate=0x{:x}/0x{:x} up=0x{:x}/0x{:x} y=0x{:x}/0x{:x}",
            status[5],
            expected_gate_va,
            status[6],
            expected_up_va,
            status[7],
            expected_y_va
        );
    }
    Ok(status)
}

fn qwen_upload_gemv_descriptor(
    dev: &mut mcore::GpuDevice,
    w_va: u64,
    x_va: u64,
    y_va: u64,
    n: u32,
    k: u32,
    num_wg: u32,
) -> Result<(mcore::DeviceBuffer, u64)> {
    if n == 0 || k == 0 || num_wg == 0 {
        anyhow::bail!(
            "GEMV descriptor requires non-zero n, k, and num_wg: n={n} k={k} num_wg={num_wg}"
        );
    }
    if k > 8192 || k & 511 != 0 {
        anyhow::bail!("GEMV descriptor requires K <= 8192 and K % 512 == 0, got {k}");
    }
    let mut words = [0u64; QWEN_GEMV_DESCRIPTOR_WORDS];
    words[0] = QWEN_GEMV_DESCRIPTOR_MAGIC;
    words[1] = QWEN_GEMV_DESCRIPTOR_VERSION;
    words[2] = w_va;
    words[3] = x_va;
    words[4] = y_va;
    words[5] = n as u64 | ((k as u64) << 32);
    words[6] = num_wg as u64;
    words[7] = qwen_swiglu_descriptor_checksum(&words[..7]);

    let mut descriptor =
        dev.alloc_device(QWEN_GEMV_DESCRIPTOR_WORDS * std::mem::size_of::<u64>())?;
    unsafe {
        descriptor.as_mut_slice_of::<u64>()[..QWEN_GEMV_DESCRIPTOR_WORDS].copy_from_slice(&words);
    }
    Ok((descriptor, words[7]))
}

fn qwen_validate_gemv_descriptor_status(
    status_buffer: &mut mcore::DeviceBuffer,
    expected_w_va: u64,
    expected_x_va: u64,
    expected_y_va: u64,
    expected_n: u32,
    expected_k: u32,
    expected_num_wg: u32,
    expected_checksum: u64,
) -> Result<[u64; QWEN_GEMV_DESCRIPTOR_STATUS_WORDS]> {
    let status = unsafe {
        let words = status_buffer.as_mut_slice_of::<u64>();
        [
            words[0], words[1], words[2], words[3], words[4], words[5], words[6], words[7],
            words[8], words[9], words[10],
        ]
    };
    if status[10] != QWEN_GEMV_DESCRIPTOR_STATUS_SENTINEL {
        anyhow::bail!(
            "GEMV descriptor kernel did not write sentinel: got 0x{:016x}",
            status[10]
        );
    }
    if status[0] != 0 {
        anyhow::bail!(
            "GEMV descriptor kernel failed: status={} bad_value=0x{:016x} checksum=0x{:016x} expected=0x{:016x}",
            status[0],
            status[9],
            status[4],
            status[5]
        );
    }
    if status[1] != expected_n as u64
        || status[2] != expected_k as u64
        || status[3] != expected_num_wg as u64
    {
        anyhow::bail!(
            "GEMV descriptor kernel returned wrong shape: n={} k={} num_wg={}",
            status[1],
            status[2],
            status[3]
        );
    }
    if status[4] != expected_checksum || status[5] != expected_checksum {
        anyhow::bail!(
            "GEMV descriptor checksum mismatch: computed=0x{:016x} expected=0x{:016x}",
            status[4],
            expected_checksum
        );
    }
    if status[6] != expected_w_va || status[7] != expected_x_va || status[8] != expected_y_va {
        anyhow::bail!(
            "GEMV descriptor pointer echo mismatch: W=0x{:x}/0x{:x} x=0x{:x}/0x{:x} y=0x{:x}/0x{:x}",
            status[6],
            expected_w_va,
            status[7],
            expected_x_va,
            status[8],
            expected_y_va
        );
    }
    Ok(status)
}

