#[allow(clippy::too_many_arguments)]
fn qwen_resident_layer_runner_attention_contract_preflight(
    entry: &QwenResidentLayerRunnerEntry,
    qkv: &QwenQkvProjStagePlan,
    qk: &QwenQkNormRopeStagePlan,
    allreduce_nodes: Option<&[u32]>,
    residual_replicas: Option<&mut [mcore::DeviceBuffer]>,
    post_attn_norm: Option<&QwenPostAttnNormStagePlan>,
    post_attn_norm_outputs: Option<&mut [mcore::DeviceBuffer]>,
    input_norm_outputs: &mut [mcore::DeviceBuffer],
    h_size: u32,
    h_bytes: usize,
) -> Result<QwenResidentLayerRunnerContractPreflight> {
    let layer_idx = entry.layer_idx;
    let context = "generic attention contract preflight";
    qwen_resident_layer_runner_validate_entry_contract(entry, context)?;
    qwen_resident_layer_runner_validate_hidden_contract(context, layer_idx, h_size, h_bytes)?;
    if input_norm_outputs.is_empty() {
        anyhow::bail!(
            "resident layer runner {context} layer {layer_idx} has no input norm outputs"
        );
    }
    if qkv.q_rows != qk.q_heads * qk.head_dim || qkv.kv_rows != qk.k_heads * qk.head_dim {
        anyhow::bail!(
            "resident layer runner {context} layer {layer_idx} QKV rows do not match QK plan: q_rows={} kv_rows={} q_heads={} k_heads={} head_dim={}",
            qkv.q_rows,
            qkv.kv_rows,
            qk.q_heads,
            qk.k_heads,
            qk.head_dim
        );
    }
    let q_weight_expected = qkv.q_rows as usize * h_size as usize * std::mem::size_of::<u16>();
    let kv_weight_expected = qkv.kv_rows as usize * h_size as usize * std::mem::size_of::<u16>();
    if qkv.q_weight_bytes.len() != q_weight_expected
        || qkv.k_weight_bytes.len() != kv_weight_expected
        || qkv.v_weight_bytes.len() != kv_weight_expected
    {
        anyhow::bail!(
            "resident layer runner {context} layer {layer_idx} QKV weight byte contract mismatch: q={} expected_q={} k={} v={} expected_kv={}",
            qkv.q_weight_bytes.len(),
            q_weight_expected,
            qkv.k_weight_bytes.len(),
            qkv.v_weight_bytes.len(),
            kv_weight_expected
        );
    }
    if qk.q_weight_bytes.len() != qk.head_dim as usize * std::mem::size_of::<u16>()
        || qk.k_weight_bytes.len() != qk.head_dim as usize * std::mem::size_of::<u16>()
    {
        anyhow::bail!(
            "resident layer runner {context} layer {layer_idx} QK norm weight byte contract mismatch: q={} k={} expected_per_norm={}",
            qk.q_weight_bytes.len(),
            qk.k_weight_bytes.len(),
            qk.head_dim as usize * std::mem::size_of::<u16>()
        );
    }
    if let Some(nodes) = allreduce_nodes {
        if nodes.len() != input_norm_outputs.len() {
            anyhow::bail!(
                "resident layer runner {context} layer {layer_idx} allreduce node count {} != input rank count {}",
                nodes.len(),
                input_norm_outputs.len()
            );
        }
    }
    let expected_ranks = input_norm_outputs.len();
    let mut buffers_checked = qwen_resident_layer_runner_validate_dispatch_buffers(
        context,
        layer_idx,
        "input_norm_output",
        input_norm_outputs,
        expected_ranks,
        h_bytes,
    )?;
    if post_attn_norm.is_some() || entry.residual_contract.transition_from_f16_to_bf16 {
        let residual_replicas = residual_replicas.ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner {context} layer {layer_idx} requires residual replicas"
            )
        })?;
        buffers_checked += qwen_resident_layer_runner_validate_dispatch_buffers(
            context,
            layer_idx,
            "residual_replica",
            residual_replicas,
            expected_ranks,
            h_bytes,
        )?;
    }
    if post_attn_norm.is_some() {
        let post_attn_norm_outputs = post_attn_norm_outputs.ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner {context} layer {layer_idx} requires post-attention norm outputs"
            )
        })?;
        buffers_checked += qwen_resident_layer_runner_validate_dispatch_buffers(
            context,
            layer_idx,
            "post_attention_norm_output",
            post_attn_norm_outputs,
            expected_ranks,
            h_bytes,
        )?;
    }
    Ok(QwenResidentLayerRunnerContractPreflight {
        ranks_checked: expected_ranks,
        buffers_checked,
        expected_h_bytes: h_bytes,
    })
}

#[allow(clippy::too_many_arguments)]
fn qwen_resident_layer_runner_mlp_contract_preflight(
    entry: &QwenResidentLayerRunnerEntry,
    mlp: &QwenMlpStagePlan,
    peer_mlp: &QwenTpMlpPeerStagePlan,
    nodes: &[u32],
    post_norm_outputs: &mut [mcore::DeviceBuffer],
    residual_replicas: Option<&mut [mcore::DeviceBuffer]>,
    next_input_norm: Option<&QwenNextInputNormStagePlan>,
    next_input_norm_outputs: Option<&mut [mcore::DeviceBuffer]>,
    h_size: u32,
    h_bytes: usize,
) -> Result<QwenResidentLayerRunnerContractPreflight> {
    let layer_idx = entry.layer_idx;
    let context = "generic MLP contract preflight";
    qwen_resident_layer_runner_validate_entry_contract(entry, context)?;
    qwen_resident_layer_runner_validate_hidden_contract(context, layer_idx, h_size, h_bytes)?;
    if nodes.is_empty() {
        anyhow::bail!("resident layer runner {context} layer {layer_idx} has no TP nodes");
    }
    if peer_mlp.tp_world != nodes.len() {
        anyhow::bail!(
            "resident layer runner {context} layer {layer_idx} peer TP{} does not match node count {}",
            peer_mlp.tp_world,
            nodes.len()
        );
    }
    let expected_peer_ranks = nodes.len().saturating_sub(1);
    if peer_mlp.peer_gate_weight_bytes.len() != expected_peer_ranks
        || peer_mlp.peer_up_weight_bytes.len() != expected_peer_ranks
        || peer_mlp.peer_down_weight_bytes.len() != expected_peer_ranks
    {
        anyhow::bail!(
            "resident layer runner {context} layer {layer_idx} peer weight shard count gate/up/down {}/{}/{} != expected {}",
            peer_mlp.peer_gate_weight_bytes.len(),
            peer_mlp.peer_up_weight_bytes.len(),
            peer_mlp.peer_down_weight_bytes.len(),
            expected_peer_ranks
        );
    }
    let gate_weight_expected =
        mlp.local_intermediate as usize * h_size as usize * std::mem::size_of::<u16>();
    let down_weight_expected =
        h_size as usize * mlp.down_cols as usize * std::mem::size_of::<u16>();
    if mlp.gate_weight_bytes.len() != gate_weight_expected
        || mlp.up_weight_bytes.len() != gate_weight_expected
        || mlp.down_weight_bytes.len() != down_weight_expected
    {
        anyhow::bail!(
            "resident layer runner {context} layer {layer_idx} MLP weight byte contract mismatch: gate={} up={} expected_gate_up={} down={} expected_down={}",
            mlp.gate_weight_bytes.len(),
            mlp.up_weight_bytes.len(),
            gate_weight_expected,
            mlp.down_weight_bytes.len(),
            down_weight_expected
        );
    }
    for peer_idx in 0..expected_peer_ranks {
        if peer_mlp.peer_gate_weight_bytes[peer_idx].len() != gate_weight_expected
            || peer_mlp.peer_up_weight_bytes[peer_idx].len() != gate_weight_expected
            || peer_mlp.peer_down_weight_bytes[peer_idx].len() != down_weight_expected
        {
            anyhow::bail!(
                "resident layer runner {context} layer {layer_idx} peer rank {} MLP weight byte contract mismatch",
                peer_idx + 1
            );
        }
    }
    let expected_ranks = nodes.len();
    let mut buffers_checked = qwen_resident_layer_runner_validate_dispatch_buffers(
        context,
        layer_idx,
        "post_attention_norm_input",
        post_norm_outputs,
        expected_ranks,
        h_bytes,
    )?;
    if next_input_norm.is_some() {
        let residual_replicas = residual_replicas.ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner {context} layer {layer_idx} requires residual replicas"
            )
        })?;
        let next_input_norm_outputs = next_input_norm_outputs.ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner {context} layer {layer_idx} requires next input norm outputs"
            )
        })?;
        buffers_checked += qwen_resident_layer_runner_validate_dispatch_buffers(
            context,
            layer_idx,
            "residual_replica",
            residual_replicas,
            expected_ranks,
            h_bytes,
        )?;
        buffers_checked += qwen_resident_layer_runner_validate_dispatch_buffers(
            context,
            layer_idx,
            "next_input_norm_output",
            next_input_norm_outputs,
            expected_ranks,
            h_bytes,
        )?;
    }
    Ok(QwenResidentLayerRunnerContractPreflight {
        ranks_checked: expected_ranks,
        buffers_checked,
        expected_h_bytes: h_bytes,
    })
}

fn qwen_resident_layer_runner_launch_decode_attention_result<T, F>(
    entry: &QwenResidentLayerRunnerEntry,
    execute: F,
) -> Result<T>
where
    F: FnOnce() -> Result<T>,
{
    qwen_resident_layer_runner_validate_entry_contract(entry, "decode-attention launch")?;
    if !entry.decode_attention_launch_eligible() {
        anyhow::bail!(
            "resident layer runner descriptor for layer {} is not launch eligible: {:?}",
            entry.layer_idx,
            entry
        );
    }
    let _ops = entry.resident_decode_attention_ops()?;

    execute()
}

fn qwen_resident_layer_runner_launch_decode_attention<F>(
    entry: &QwenResidentLayerRunnerEntry,
    execute: F,
) -> Result<()>
where
    F: FnOnce() -> Result<()>,
{
    qwen_resident_layer_runner_launch_decode_attention_result(entry, execute)
}

const QWEN_RESIDENT_LAYER_RUNNER_LOOP_EXECUTOR_ATTENTION_AUTHORITY_FRONTIER_MAX_EDGE: u32 = 3;

fn qwen_resident_layer_runner_loop_executor_attention_authoritative_cursor(
    dag_scheduler: QwenResidentLayerRunnerDagSchedulerContext<'_>,
    layer_idx: u32,
) -> Result<Option<u32>> {
    let Some(cursor_edge_index) = qwen_resident_layer_runner_attention_dag_edge_index(
        dag_scheduler.dag_rows,
        Some(layer_idx),
    )?
    else {
        return Ok(None);
    };
    if cursor_edge_index
        > QWEN_RESIDENT_LAYER_RUNNER_LOOP_EXECUTOR_ATTENTION_AUTHORITY_FRONTIER_MAX_EDGE
    {
        return Ok(None);
    }
    Ok(Some(cursor_edge_index))
}

fn qwen_resident_layer_runner_loop_executor_dispatch_attention_result<T, F>(
    entry: &QwenResidentLayerRunnerEntry,
    dag_scheduler: QwenResidentLayerRunnerDagSchedulerContext<'_>,
    position: u32,
    execute: F,
) -> Result<T>
where
    F: FnOnce() -> Result<T>,
{
    let Some(switch_cursor_index) =
        qwen_resident_layer_runner_loop_executor_attention_authoritative_cursor(
            dag_scheduler,
            entry.layer_idx,
        )?
    else {
        return qwen_resident_layer_runner_launch_decode_attention_result(entry, execute);
    };

    let preflight_start = std::time::Instant::now();
    qwen_resident_layer_runner_validate_entry_contract(entry, "loop executor attention dispatch")?;
    if !entry.decode_attention_launch_eligible() {
        anyhow::bail!(
            "resident layer runner loop executor descriptor for layer {} is not decode-attention launch eligible: {:?}",
            entry.layer_idx,
            entry
        );
    }
    let runner_ops = entry.resident_decode_attention_ops()?;
    let preflight_wall = preflight_start.elapsed();

    println!("  resident_layer_runner_loop_executor_attention_dispatch_stage:");
    println!("    source: host_loop_executor_dispatcher");
    println!(
        "    selected_boundary: next_decode_layer{}_attention",
        entry.layer_idx
    );
    println!("    runtime_switched: true");
    println!("    hip_graph_capture_started: false");
    println!("    dispatch_kind: attention");
    println!("    layer_idx: {}", entry.layer_idx);
    println!("    dynamic_position: {position}");
    println!("    dynamic_position_source: gpu_decode_metadata");
    println!("    switch_source: authoritative_resident_dag_attention_edge");
    println!("    switch_cursor_source: resident_layer_runner_dag_frontier");
    println!("    switch_cursor_index: {switch_cursor_index}");
    println!("    switch_ready_ordinal: {switch_cursor_index}");
    println!("    switch_frontier_edge_index: {switch_cursor_index}");
    println!(
        "    switch_frontier_max_edge_index: {}",
        QWEN_RESIDENT_LAYER_RUNNER_LOOP_EXECUTOR_ATTENTION_AUTHORITY_FRONTIER_MAX_EDGE
    );
    println!("    mirrored_layer_switch_table_used: false");
    println!("    admitted_by_authoritative_frontier: true");
    println!("    dag_descriptor_va: 0x{:x}", dag_scheduler.descriptor_va);
    println!(
        "    dag_descriptor_bytes: {}",
        dag_scheduler.descriptor_bytes
    );
    println!("    dag_rows: {}", dag_scheduler.dag_rows.len());
    println!("    dag_attention_edge_index: {switch_cursor_index}");
    println!("    launch_function: qwen_resident_layer_runner_launch_decode_attention");
    println!("    existing_kernel_sequence_preserved: true");
    println!("    runner_operation_count: {}", runner_ops.len());
    println!("    runner_operation_trace: {}", runner_ops.join(" -> "));
    println!(
        "    preflight_wall_us: {:.3}",
        preflight_wall.as_secs_f64() * 1e6
    );
    println!("    next_required: byte_exact_attention_loop_boundary_shadow_equivalence");

    qwen_resident_layer_runner_launch_decode_attention_result(entry, execute)
}

struct QwenResidentLayerRunnerAttentionShadowSnapshot {
    residual_outputs: Option<Vec<Vec<u8>>>,
    post_attn_norm_outputs: Option<Vec<Vec<u8>>>,
}

#[allow(clippy::too_many_arguments)]
fn qwen_resident_layer_runner_run_attention_unrolled_shadow_snapshot(
    layer_idx: u32,
    dev: &mut mcore::GpuDevice,
    peer_workspaces: &mut [QwenPeerMlpWorkspace],
    qkv: &QwenQkvProjStagePlan,
    qk: &QwenQkNormRopeStagePlan,
    cache_plan: Option<&QwenFp4KvCacheStagePlan>,
    attn_plan: Option<&QwenFp4SingleRowAttentionStagePlan>,
    o_proj_plan: Option<&QwenOProjStagePlan>,
    allreduce_nodes: Option<&[u32]>,
    mut residual_replicas: Option<&mut [mcore::DeviceBuffer]>,
    post_attn_norm: Option<&QwenPostAttnNormStagePlan>,
    post_attn_norm_outputs_required: bool,
    peer_plan: &QwenTpOProjPeerStagePlan,
    input_norm_outputs: &mut [mcore::DeviceBuffer],
    position: u32,
    h_size: u32,
    h_bytes: usize,
    residual_contract: QwenResidentResidualContract,
    q_w: &mut mcore::DeviceBuffer,
    k_w: &mut mcore::DeviceBuffer,
    v_w: &mut mcore::DeviceBuffer,
    q_out: &mut mcore::DeviceBuffer,
    k_out: &mut mcore::DeviceBuffer,
    v_out: &mut mcore::DeviceBuffer,
    q_norm_w: &mut mcore::DeviceBuffer,
    k_norm_w: &mut mcore::DeviceBuffer,
    q_rope: &mut mcore::DeviceBuffer,
    k_rope: &mut mcore::DeviceBuffer,
) -> Result<QwenResidentLayerRunnerAttentionShadowSnapshot> {
    let tp_world = input_norm_outputs.len();
    let mut shadow_input_norm_outputs = Vec::new();
    qwen_prepare_next_decode_layer_rank_h_buffers(
        dev,
        peer_workspaces,
        &mut shadow_input_norm_outputs,
        tp_world,
        h_bytes,
        layer_idx,
        "loop equivalence attention input norm shadow",
    )?;
    for rank in 0..tp_world {
        let input_bytes =
            unsafe { input_norm_outputs[rank].as_mut_slice_of::<u8>()[..h_bytes].to_vec() };
        unsafe {
            shadow_input_norm_outputs[rank].as_mut_slice_of::<u8>()[..h_bytes]
                .copy_from_slice(&input_bytes);
        }
    }

    let mut shadow_residual_outputs = Vec::new();
    if residual_replicas.is_some() {
        qwen_prepare_next_decode_layer_rank_h_buffers(
            dev,
            peer_workspaces,
            &mut shadow_residual_outputs,
            tp_world,
            h_bytes,
            layer_idx,
            "loop equivalence attention residual shadow",
        )?;
        let source_residuals = residual_replicas.as_deref_mut().ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner layer{layer_idx} attention loop equivalence residual clone expected source residual buffers"
            )
        })?;
        for rank in 0..tp_world {
            let residual_bytes =
                unsafe { source_residuals[rank].as_mut_slice_of::<u8>()[..h_bytes].to_vec() };
            unsafe {
                shadow_residual_outputs[rank].as_mut_slice_of::<u8>()[..h_bytes]
                    .copy_from_slice(&residual_bytes);
            }
        }
    }

    let mut shadow_post_attn_norm_outputs = Vec::new();
    if post_attn_norm_outputs_required {
        qwen_prepare_next_decode_layer_rank_h_buffers(
            dev,
            peer_workspaces,
            &mut shadow_post_attn_norm_outputs,
            tp_world,
            h_bytes,
            layer_idx,
            "loop equivalence post attention norm shadow",
        )?;
    }

    let shadow_residual_arg = if !shadow_residual_outputs.is_empty() {
        Some(shadow_residual_outputs.as_mut_slice())
    } else {
        None
    };
    let shadow_post_norm_arg = if !shadow_post_attn_norm_outputs.is_empty() {
        Some(shadow_post_attn_norm_outputs.as_mut_slice())
    } else {
        None
    };

    let _shadow_result = run_qwen_next_decode_layer1_qkv_qk_rope_all_rank_with_residual_contract(
        dev,
        peer_workspaces,
        qkv,
        qk,
        cache_plan,
        attn_plan,
        o_proj_plan,
        allreduce_nodes,
        shadow_residual_arg,
        post_attn_norm,
        shadow_post_norm_arg,
        peer_plan,
        shadow_input_norm_outputs.as_mut_slice(),
        position,
        h_size,
        h_bytes,
        residual_contract,
        q_w,
        k_w,
        v_w,
        q_out,
        k_out,
        v_out,
        q_norm_w,
        k_norm_w,
        q_rope,
        k_rope,
    )
    .map_err(|err| {
        anyhow::anyhow!(
            "resident layer runner layer{layer_idx} unrolled attention shadow dispatch failed: {err:#}"
        )
    })?;

    let residual_outputs = if !shadow_residual_outputs.is_empty() {
        Some(
            shadow_residual_outputs
                .iter_mut()
                .map(|buffer| unsafe { buffer.as_mut_slice_of::<u8>()[..h_bytes].to_vec() })
                .collect::<Vec<_>>(),
        )
    } else {
        None
    };
    let post_attn_norm_outputs = if !shadow_post_attn_norm_outputs.is_empty() {
        Some(
            shadow_post_attn_norm_outputs
                .iter_mut()
                .map(|buffer| unsafe { buffer.as_mut_slice_of::<u8>()[..h_bytes].to_vec() })
                .collect::<Vec<_>>(),
        )
    } else {
        None
    };

    Ok(QwenResidentLayerRunnerAttentionShadowSnapshot {
        residual_outputs,
        post_attn_norm_outputs,
    })
}

fn qwen_resident_layer_runner_validate_attention_shadow_equivalence(
    layer_idx: u32,
    position: u32,
    snapshot: &QwenResidentLayerRunnerAttentionShadowSnapshot,
    residual_replicas: Option<&mut [mcore::DeviceBuffer]>,
    post_attn_norm_outputs: Option<&mut [mcore::DeviceBuffer]>,
    h_bytes: usize,
) -> Result<()> {
    let mut residual_checked = false;
    let mut residual_ranks = 0usize;
    let mut residual_mismatch_bytes = 0usize;
    if let Some(expected_residual) = &snapshot.residual_outputs {
        let got_residual = residual_replicas.ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner layer{layer_idx} attention loop-vs-unrolled residual shadow expected real residual buffers"
            )
        })?;
        residual_mismatch_bytes = qwen_resident_layer_runner_compare_shadow_h_buffers(
            layer_idx,
            "attention_residual",
            got_residual,
            expected_residual.as_slice(),
            h_bytes,
        )?;
        residual_checked = true;
        residual_ranks = expected_residual.len();
    }

    let mut post_attn_norm_checked = false;
    let mut post_attn_norm_ranks = 0usize;
    let mut post_attn_norm_mismatch_bytes = 0usize;
    if let Some(expected_norm) = &snapshot.post_attn_norm_outputs {
        let got_norm = post_attn_norm_outputs.ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner layer{layer_idx} attention loop-vs-unrolled post-attention norm shadow expected real norm buffers"
            )
        })?;
        post_attn_norm_mismatch_bytes = qwen_resident_layer_runner_compare_shadow_h_buffers(
            layer_idx,
            "post_attention_norm",
            got_norm,
            expected_norm.as_slice(),
            h_bytes,
        )?;
        post_attn_norm_checked = true;
        post_attn_norm_ranks = expected_norm.len();
    }

    println!("  resident_layer_runner_loop_executor_attention_shadow_equivalence_stage:");
    println!("    selected_boundary: next_decode_layer{layer_idx}_attention");
    println!("    baseline: unrolled_direct_attention_descriptor_replay");
    println!("    dispatched: host_loop_executor_dispatcher");
    println!("    compare: byte_exact_rank_h_buffers");
    println!("    dynamic_position: {position}");
    println!("    h_bytes_per_rank: {h_bytes}");
    println!("    residual_checked: {residual_checked}");
    println!("    residual_ranks: {residual_ranks}");
    println!("    residual_mismatch_bytes: {residual_mismatch_bytes}");
    println!("    post_attn_norm_checked: {post_attn_norm_checked}");
    println!("    post_attn_norm_ranks: {post_attn_norm_ranks}");
    println!("    post_attn_norm_mismatch_bytes: {post_attn_norm_mismatch_bytes}");
    println!("    bit_exact: true");
    println!("    hip_graph_capture_started: false");
    println!("    next_required: wire_attention_dispatcher_to_authoritative_plan_cursor_or_qwen35_gdn_router");
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn qwen_resident_layer_runner_dispatch_next_decode_attention(
    runner_entries: &[QwenResidentLayerRunnerEntry],
    layer_idx: u32,
    dag_scheduler: QwenResidentLayerRunnerDagSchedulerContext<'_>,
    dev: &mut mcore::GpuDevice,
    peer_workspaces: &mut [QwenPeerMlpWorkspace],
    qkv: &QwenQkvProjStagePlan,
    qk: &QwenQkNormRopeStagePlan,
    cache_plan: Option<&QwenFp4KvCacheStagePlan>,
    attn_plan: Option<&QwenFp4SingleRowAttentionStagePlan>,
    o_proj_plan: Option<&QwenOProjStagePlan>,
    allreduce_nodes: Option<&[u32]>,
    mut residual_replicas: Option<&mut [mcore::DeviceBuffer]>,
    post_attn_norm: Option<&QwenPostAttnNormStagePlan>,
    mut post_attn_norm_outputs: Option<&mut [mcore::DeviceBuffer]>,
    peer_plan: &QwenTpOProjPeerStagePlan,
    input_norm_outputs: &mut [mcore::DeviceBuffer],
    position: u32,
    h_size: u32,
    h_bytes: usize,
) -> Result<(
    QwenNextDecodeLayer1QkvAllRankStage,
    QwenNextDecodeLayer1QkRopeAllRankStage,
    Option<QwenNextDecodeLayer1KvAppendAllRankStage>,
    Option<QwenNextDecodeLayer1AttentionAllRankStage>,
    Option<QwenNextDecodeLayer1OProjAllReduceStage>,
    Option<QwenNextDecodeLayer1PostAttnNormAllRankStage>,
)> {
    let entry = runner_entries
        .iter()
        .find(|entry| entry.layer_idx == layer_idx)
        .ok_or_else(|| {
            anyhow::anyhow!("resident layer runner descriptor for layer {layer_idx} is missing")
        })?;

    qwen_resident_layer_runner_loop_executor_dispatch_attention_result(
        entry,
        dag_scheduler,
        position,
        || -> Result<_> {
            let contract = qwen_resident_layer_runner_attention_contract_preflight(
                entry,
                qkv,
                qk,
                allreduce_nodes,
                residual_replicas.as_deref_mut(),
                post_attn_norm,
                post_attn_norm_outputs.as_deref_mut(),
                input_norm_outputs,
                h_size,
                h_bytes,
            )?;
            println!("  resident_layer_runner_generic_attention_contract_preflight_stage:");
            println!("    layer_idx: {layer_idx}");
            println!(
                "    residual_contract_source: {}",
                entry.residual_contract.source_label()
            );
            println!(
                "    residual_storage: {}",
                entry.residual_contract.storage.label()
            );
            println!("    ranks_checked: {}", contract.ranks_checked);
            println!("    buffers_checked: {}", contract.buffers_checked);
            println!("    expected_h_bytes: {}", contract.expected_h_bytes);
            println!(
                "    min_alignment_bytes: {}",
                QWEN_RESIDENT_LAYER_RUNNER_DISPATCH_MIN_ALIGNMENT_BYTES
            );
            println!("    buffer_contract_valid: true");
            println!("    guard_placement: before_attention_gpu_allocation_and_dispatch");
            let mut q_w = dev.alloc_device(qkv.q_weight_bytes.len())?;
            let mut k_w = dev.alloc_device(qkv.k_weight_bytes.len())?;
            let mut v_w = dev.alloc_device(qkv.v_weight_bytes.len())?;
            let mut q_out = dev.alloc(qkv.q_rows as usize * 4)?;
            let mut k_out = dev.alloc(qkv.kv_rows as usize * 4)?;
            let mut v_out = dev.alloc(qkv.kv_rows as usize * 4)?;
            let mut q_norm_w = dev.alloc_device(qk.q_weight_bytes.len())?;
            let mut k_norm_w = dev.alloc_device(qk.k_weight_bytes.len())?;
            let mut q_rope = dev.alloc(qk.q_heads as usize * qk.head_dim as usize * 2)?;
            let mut k_rope = dev.alloc(qk.k_heads as usize * qk.head_dim as usize * 2)?;

            unsafe {
                q_w.as_mut_slice_of::<u8>()[..qkv.q_weight_bytes.len()]
                    .copy_from_slice(&qkv.q_weight_bytes);
                k_w.as_mut_slice_of::<u8>()[..qkv.k_weight_bytes.len()]
                    .copy_from_slice(&qkv.k_weight_bytes);
                v_w.as_mut_slice_of::<u8>()[..qkv.v_weight_bytes.len()]
                    .copy_from_slice(&qkv.v_weight_bytes);
                q_norm_w.as_mut_slice_of::<u8>()[..qk.q_weight_bytes.len()]
                    .copy_from_slice(&qk.q_weight_bytes);
                k_norm_w.as_mut_slice_of::<u8>()[..qk.k_weight_bytes.len()]
                    .copy_from_slice(&qk.k_weight_bytes);
            }

            let loop_dispatch_attention_shadow_snapshot =
                if qwen_resident_layer_runner_loop_executor_attention_authoritative_cursor(
                    dag_scheduler,
                    layer_idx,
                )?
                .is_some()
                {
                    Some(
                        qwen_resident_layer_runner_run_attention_unrolled_shadow_snapshot(
                            layer_idx,
                            dev,
                            peer_workspaces,
                            qkv,
                            qk,
                            cache_plan,
                            attn_plan,
                            o_proj_plan,
                            allreduce_nodes,
                            residual_replicas.as_deref_mut(),
                            post_attn_norm,
                            post_attn_norm_outputs.is_some(),
                            peer_plan,
                            input_norm_outputs,
                            position,
                            h_size,
                            h_bytes,
                            entry.residual_contract,
                            &mut q_w,
                            &mut k_w,
                            &mut v_w,
                            &mut q_out,
                            &mut k_out,
                            &mut v_out,
                            &mut q_norm_w,
                            &mut k_norm_w,
                            &mut q_rope,
                            &mut k_rope,
                        )?,
                    )
                } else {
                    None
                };

            let result = run_qwen_next_decode_layer1_qkv_qk_rope_all_rank_with_residual_contract(
                dev,
                peer_workspaces,
                qkv,
                qk,
                cache_plan,
                attn_plan,
                o_proj_plan,
                allreduce_nodes,
                residual_replicas.as_deref_mut(),
                post_attn_norm,
                post_attn_norm_outputs.as_deref_mut(),
                peer_plan,
                input_norm_outputs,
                position,
                h_size,
                h_bytes,
                entry.residual_contract,
                &mut q_w,
                &mut k_w,
                &mut v_w,
                &mut q_out,
                &mut k_out,
                &mut v_out,
                &mut q_norm_w,
                &mut k_norm_w,
                &mut q_rope,
                &mut k_rope,
            )?;

            if let Some(snapshot) = &loop_dispatch_attention_shadow_snapshot {
                qwen_resident_layer_runner_validate_attention_shadow_equivalence(
                    layer_idx,
                    position,
                    snapshot,
                    residual_replicas.as_deref_mut(),
                    post_attn_norm_outputs.as_deref_mut(),
                    h_bytes,
                )?;
            }

            if result.5.is_some() {
                let residual_bf16 = entry.uses_bf16_residual();
                let residual_replicas = residual_replicas.as_deref_mut().ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner generic attention layer {layer_idx} post-attention norm stage ran without residual replica buffers"
                )
            })?;
                let post_attn_norm_outputs = post_attn_norm_outputs.as_deref_mut().ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner generic attention layer {layer_idx} post-attention norm stage ran without post-attention norm output buffers"
                )
            })?;
                let mut residual_max_abs = 0.0f32;
                let mut residual_max_rank = 0usize;
                let mut residual_max_dim = 0usize;
                let mut residual_elements = 0usize;
                for rank in 0..residual_replicas.len() {
                    let residual_slice = unsafe { residual_replicas[rank].as_mut_slice_of::<u8>() };
                    if residual_slice.len() < h_bytes {
                        anyhow::bail!(
                        "resident layer runner generic attention layer {layer_idx} post_attention_residual_stream_after_attention_norm rank{rank} buffer bytes {} < expected {}",
                        residual_slice.len(),
                        h_bytes
                    );
                    }
                    let residual_bytes = residual_slice[..h_bytes].to_vec();
                    let rank_label = format!("rank{rank}");
                    let stats = if residual_bf16 {
                        qwen_resident_layer_runner_validate_bf16_finite_bytes_for_context(
                            "generic attention",
                            layer_idx,
                            "post_attention_residual_stream_after_attention_norm",
                            &rank_label,
                            &residual_bytes,
                            h_bytes,
                        )?
                    } else {
                        qwen_resident_layer_runner_validate_f16_finite_bytes_for_context(
                            "generic attention",
                            layer_idx,
                            "post_attention_residual_stream_after_attention_norm",
                            &rank_label,
                            &residual_bytes,
                            h_bytes,
                        )?
                    };
                    residual_elements = stats.elements;
                    if stats.max_abs > residual_max_abs {
                        residual_max_abs = stats.max_abs;
                        residual_max_rank = rank;
                        residual_max_dim = stats.max_dim;
                    }
                }
                let mut norm_max_abs = 0.0f32;
                let mut norm_max_rank = 0usize;
                let mut norm_max_dim = 0usize;
                let mut norm_elements = 0usize;
                for rank in 0..post_attn_norm_outputs.len() {
                    let norm_slice =
                        unsafe { post_attn_norm_outputs[rank].as_mut_slice_of::<u8>() };
                    if norm_slice.len() < h_bytes {
                        anyhow::bail!(
                        "resident layer runner generic attention layer {layer_idx} post_attention_norm_output_after_attention rank{rank} buffer bytes {} < expected {}",
                        norm_slice.len(),
                        h_bytes
                    );
                    }
                    let norm_bytes = norm_slice[..h_bytes].to_vec();
                    let rank_label = format!("rank{rank}");
                    let stats = qwen_resident_layer_runner_validate_f16_finite_bytes_for_context(
                        "generic attention",
                        layer_idx,
                        "post_attention_norm_output_after_attention",
                        &rank_label,
                        &norm_bytes,
                        h_bytes,
                    )?;
                    norm_elements = stats.elements;
                    if stats.max_abs > norm_max_abs {
                        norm_max_abs = stats.max_abs;
                        norm_max_rank = rank;
                        norm_max_dim = stats.max_dim;
                    }
                }
                println!("  resident_layer_runner_generic_attention_post_attn_finite_guard_stage:");
                println!("    layer_idx: {layer_idx}");
                println!(
                    "    residual_storage: {}",
                    entry.residual_contract.storage.label()
                );
                println!(
                    "    residual_contract_source: {}",
                    entry.residual_contract.source_label()
                );
                println!("    ranks_checked: {}", residual_replicas.len());
                println!("    residual_elements_per_rank: {residual_elements}");
                println!("    residual_finite: true");
                println!(
                    "    residual_max_abs: {:.6} at rank {} dim {}",
                    residual_max_abs, residual_max_rank, residual_max_dim
                );
                println!("    post_attention_norm_elements_per_rank: {norm_elements}");
                println!("    post_attention_norm_finite: true");
                println!(
                    "    post_attention_norm_max_abs: {:.6} at rank {} dim {}",
                    norm_max_abs, norm_max_rank, norm_max_dim
                );
                println!("    guard_placement: after_attention_residual_norm_before_mlp");
            }

            Ok(result)
        },
    )
}

fn qwen_resident_layer_runner_launch_mlp_result<T, F>(
    entry: &QwenResidentLayerRunnerEntry,
    execute: F,
) -> Result<T>
where
    F: FnOnce() -> Result<T>,
{
    qwen_resident_layer_runner_validate_entry_contract(entry, "MLP launch")?;
    if !entry.mlp_launch_eligible() {
        anyhow::bail!(
            "resident layer runner descriptor for layer {} is not MLP launch eligible: {:?}",
            entry.layer_idx,
            entry
        );
    }
    let _ops = entry.resident_mlp_ops()?;

    execute()
}

fn qwen_resident_layer_runner_launch_mlp<F>(
    entry: &QwenResidentLayerRunnerEntry,
    execute: F,
) -> Result<()>
where
    F: FnOnce() -> Result<()>,
{
    qwen_resident_layer_runner_launch_mlp_result(entry, execute)
}

const QWEN_RESIDENT_LAYER_RUNNER_LOOP_EXECUTOR_MLP_AUTHORITY_FRONTIER_MAX_EDGE: u32 = 4;

fn qwen_resident_layer_runner_loop_executor_mlp_authoritative_cursor(
    dag_scheduler: QwenResidentLayerRunnerDagSchedulerContext<'_>,
    layer_idx: u32,
) -> Result<Option<u32>> {
    let Some(cursor_edge_index) = qwen_resident_layer_runner_mlp_dag_completion_edge_index(
        dag_scheduler.dag_rows,
        Some(layer_idx),
    )?
    else {
        return Ok(None);
    };
    if cursor_edge_index > QWEN_RESIDENT_LAYER_RUNNER_LOOP_EXECUTOR_MLP_AUTHORITY_FRONTIER_MAX_EDGE
    {
        return Ok(None);
    }
    Ok(Some(cursor_edge_index))
}

fn qwen_resident_layer_runner_loop_executor_dispatch_mlp_result<T, F>(
    entry: &QwenResidentLayerRunnerEntry,
    dag_scheduler: QwenResidentLayerRunnerDagSchedulerContext<'_>,
    execute: F,
) -> Result<T>
where
    F: FnOnce() -> Result<T>,
{
    let Some(switch_cursor_index) =
        qwen_resident_layer_runner_loop_executor_mlp_authoritative_cursor(
            dag_scheduler,
            entry.layer_idx,
        )?
    else {
        return qwen_resident_layer_runner_launch_mlp_result(entry, execute);
    };

    let preflight_start = std::time::Instant::now();
    qwen_resident_layer_runner_validate_entry_contract(entry, "loop executor MLP dispatch")?;
    if !entry.mlp_launch_eligible() {
        anyhow::bail!(
            "resident layer runner loop executor descriptor for layer {} is not MLP launch eligible: {:?}",
            entry.layer_idx,
            entry
        );
    }
    if dag_scheduler.descriptor_va == 0 {
        anyhow::bail!(
            "resident layer runner loop executor layer {} requires nonzero DAG descriptor VA",
            entry.layer_idx
        );
    }
    if dag_scheduler.descriptor_bytes == 0 {
        anyhow::bail!(
            "resident layer runner loop executor layer {} requires nonzero DAG descriptor bytes",
            entry.layer_idx
        );
    }
    if dag_scheduler.dag_rows.is_empty() {
        anyhow::bail!(
            "resident layer runner loop executor layer {} requires DAG rows",
            entry.layer_idx
        );
    }
    let dag_completion_edge_index = qwen_resident_layer_runner_mlp_dag_completion_edge_index(
        dag_scheduler.dag_rows,
        Some(entry.layer_idx),
    )?
    .ok_or_else(|| {
        anyhow::anyhow!(
            "resident layer runner loop executor layer {} has no MLP completion DAG edge",
            entry.layer_idx
        )
    })?;
    let runner_ops = entry.resident_mlp_ops()?;
    let preflight_wall = preflight_start.elapsed();

    println!("  resident_layer_runner_loop_executor_dispatch_stage:");
    println!("    source: host_loop_executor_dispatcher");
    println!(
        "    selected_boundary: next_decode_layer{}_mlp",
        entry.layer_idx
    );
    println!("    runtime_switched: true");
    println!("    hip_graph_capture_started: false");
    println!("    dispatch_kind: mlp");
    println!("    layer_idx: {}", entry.layer_idx);
    println!("    switch_source: authoritative_resident_dag_completion_edge");
    println!("    switch_cursor_source: resident_layer_runner_dag_frontier");
    println!("    switch_cursor_index: {switch_cursor_index}");
    println!("    switch_ready_ordinal: {switch_cursor_index}");
    println!("    switch_frontier_edge_index: {switch_cursor_index}");
    println!(
        "    switch_frontier_max_edge_index: {}",
        QWEN_RESIDENT_LAYER_RUNNER_LOOP_EXECUTOR_MLP_AUTHORITY_FRONTIER_MAX_EDGE
    );
    println!("    mirrored_layer_switch_table_used: false");
    println!("    admitted_by_authoritative_frontier: true");
    println!("    dag_descriptor_va: 0x{:x}", dag_scheduler.descriptor_va);
    println!(
        "    dag_descriptor_bytes: {}",
        dag_scheduler.descriptor_bytes
    );
    println!("    dag_rows: {}", dag_scheduler.dag_rows.len());
    println!("    dag_completion_edge_index: {dag_completion_edge_index}");
    println!("    launch_function: qwen_resident_layer_runner_launch_mlp");
    println!("    existing_kernel_sequence_preserved: true");
    println!("    runner_operation_count: {}", runner_ops.len());
    println!("    runner_operation_trace: {}", runner_ops.join(" -> "));
    println!(
        "    preflight_wall_us: {:.3}",
        preflight_wall.as_secs_f64() * 1e6
    );
    println!("    next_required: bit_exact_compare_one_loop_boundary_against_unrolled_shadow");

    qwen_resident_layer_runner_launch_mlp_result(entry, execute)
}

fn qwen_print_resident_layer_runner_attention_dispatch_stage(
    runner_entries: &[QwenResidentLayerRunnerEntry],
    layer_idx: u32,
    next_required: &str,
    launch_function: &str,
) -> Result<()> {
    if let Some(layer_entry) = runner_entries
        .iter()
        .find(|entry| entry.layer_idx == layer_idx)
    {
        let runner_ops = layer_entry.resident_decode_attention_ops()?;
        println!("  resident_layer_runner_attention_dispatch_stage:");
        println!("    layers_described: {}", runner_entries.len());
        println!("    exercised_layer: {}", layer_entry.layer_idx);
        println!("    dispatch: next_decode_layer{}_attention", layer_idx);
        println!("    execution_mode: eager_no_hip_graph_capture");
        println!("    launch_function: {launch_function}");
        println!("    runner_operation_count: {}", runner_ops.len());
        println!("    runner_operation_trace: {}", runner_ops.join(" -> "));
        println!(
            "    attention_launch_eligible: {}",
            layer_entry.decode_attention_launch_eligible()
        );
        println!(
            "    full_layer_launch_eligible: {}",
            layer_entry.full_layer_launch_eligible()
        );
        println!("    runner_determinism_contract: fixed_rank_order_allreduce_before_rmsnorm");
        println!("    next_required: {next_required}");
    }
    Ok(())
}

fn qwen_print_resident_layer_runner_attention_dispatch_markers(
    runner_entries: &[QwenResidentLayerRunnerEntry],
    markers: &[QwenResidentLayerRunnerDispatchMarker],
) -> Result<()> {
    for marker in markers {
        if marker.enabled {
            if marker.kind != QwenResidentLayerRunnerDispatchKind::DecodeAttention {
                anyhow::bail!(
                    "resident layer runner attention marker for layer {} has wrong dispatch kind: {:?}",
                    marker.layer_idx,
                    marker.kind
                );
            }
            qwen_print_resident_layer_runner_attention_dispatch_stage(
                runner_entries,
                marker.layer_idx,
                marker.next_required,
                marker.launch_function,
            )?;
            println!("    capture_boundary: {}", marker.capture_boundary.label());
        }
    }
    Ok(())
}

