#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
enum QwenResidentLayerRunnerDependencyId {
    NextDecodeLayer18QkvAllRank = 0,
    NextDecodeLayer19QkvAllRank = 1,
    NextDecodeLayer19MlpAllreduce = 2,
    NextDecodeLayer20QkvAllRank = 3,
    NextDecodeLayer20MlpAllreduce = 4,
    NextDecodeLayer21QkvAllRank = 5,
    NextDecodeLayer21MlpResidualNormAllRank = 6,
    NextDecodeLayer22QkvAllRank = 7,
    NextDecodeLayer22MlpResidualNormAllRank = 8,
}

impl QwenResidentLayerRunnerDependencyId {
    fn label(self) -> &'static str {
        match self {
            Self::NextDecodeLayer18QkvAllRank => "next_decode_layer18_qkv_all_rank_stage",
            Self::NextDecodeLayer19QkvAllRank => "next_decode_layer19_qkv_all_rank_stage",
            Self::NextDecodeLayer19MlpAllreduce => "next_decode_layer19_mlp_allreduce_stage",
            Self::NextDecodeLayer20QkvAllRank => "next_decode_layer20_qkv_all_rank_stage",
            Self::NextDecodeLayer20MlpAllreduce => "next_decode_layer20_mlp_allreduce_stage",
            Self::NextDecodeLayer21QkvAllRank => "next_decode_layer21_qkv_all_rank_stage",
            Self::NextDecodeLayer21MlpResidualNormAllRank => {
                "next_decode_layer21_mlp_residual_norm_all_rank_stage"
            }
            Self::NextDecodeLayer22QkvAllRank => "next_decode_layer22_qkv_all_rank_stage",
            Self::NextDecodeLayer22MlpResidualNormAllRank => {
                "next_decode_layer22_mlp_residual_norm_all_rank_stage"
            }
        }
    }

    const fn bit(self) -> u64 {
        1u64 << (self as u8)
    }
}

