#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum QwenResidentLayerRunnerMlpTopology {
    Dense,
    SharedExpertRoutedMoe {
        routed_experts: u16,
        shared_experts: u16,
        active_experts: u16,
    },
}

impl QwenResidentLayerRunnerMlpTopology {
    fn label(self) -> &'static str {
        match self {
            QwenResidentLayerRunnerMlpTopology::Dense => "dense_mlp",
            QwenResidentLayerRunnerMlpTopology::SharedExpertRoutedMoe { .. } => {
                "shared_expert_routed_moe"
            }
        }
    }

    fn is_moe(self) -> bool {
        matches!(
            self,
            QwenResidentLayerRunnerMlpTopology::SharedExpertRoutedMoe { .. }
        )
    }

    fn routed_experts(self) -> u16 {
        match self {
            QwenResidentLayerRunnerMlpTopology::Dense => 0,
            QwenResidentLayerRunnerMlpTopology::SharedExpertRoutedMoe {
                routed_experts, ..
            } => routed_experts,
        }
    }

    fn shared_experts(self) -> u16 {
        match self {
            QwenResidentLayerRunnerMlpTopology::Dense => 0,
            QwenResidentLayerRunnerMlpTopology::SharedExpertRoutedMoe {
                shared_experts, ..
            } => shared_experts,
        }
    }

    fn active_experts(self) -> u16 {
        match self {
            QwenResidentLayerRunnerMlpTopology::Dense => 0,
            QwenResidentLayerRunnerMlpTopology::SharedExpertRoutedMoe {
                active_experts, ..
            } => active_experts,
        }
    }
}

