#[derive(Clone, Copy, Debug)]
struct QwenResidentLayerRunnerDirectChainReadiness {
    plan_state: QwenResidentLayerRunnerPlanState,
}

impl QwenResidentLayerRunnerDirectChainReadiness {
    fn all_rank_direct_attention_chain_ready(self) -> bool {
        self.plan_state.input_norm
            && self.plan_state.qkv
            && self.plan_state.qk_norm_rope
            && self.plan_state.fp4_kv_cache
            && self.plan_state.fp4_attention
            && self.plan_state.o_proj
            && self.plan_state.tp_o_proj_peer
            && self.plan_state.post_attn_norm
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum QwenResidentResidualStorage {
    F16,
    Bf16,
}

impl QwenResidentResidualStorage {
    fn label(self) -> &'static str {
        match self {
            QwenResidentResidualStorage::F16 => "f16",
            QwenResidentResidualStorage::Bf16 => "bf16",
        }
    }
}

#[derive(Clone, Copy, Debug)]
struct QwenResidentResidualContract {
    layer_idx: u32,
    storage: QwenResidentResidualStorage,
    transition_from_f16_to_bf16: bool,
}

impl QwenResidentResidualContract {
    fn uses_bf16(self) -> bool {
        self.storage == QwenResidentResidualStorage::Bf16
    }

    fn source_label(self) -> &'static str {
        "resident_runner_descriptor"
    }
}

const QWEN_RESIDENT_LAYER_RUNNER_BF16_RESIDUAL_MASK: u64 = (1u64 << 20) | (1u64 << 21);
const QWEN_RESIDENT_LAYER_RUNNER_F16_TO_BF16_TRANSITION_MASK: u64 = 1u64 << 20;

fn qwen_resident_layer_runner_residual_contract(layer_idx: u32) -> QwenResidentResidualContract {
    let bit = if layer_idx < 64 { 1u64 << layer_idx } else { 0 };
    let storage = if QWEN_RESIDENT_LAYER_RUNNER_BF16_RESIDUAL_MASK & bit != 0 {
        QwenResidentResidualStorage::Bf16
    } else {
        QwenResidentResidualStorage::F16
    };
    QwenResidentResidualContract {
        layer_idx,
        storage,
        transition_from_f16_to_bf16: QWEN_RESIDENT_LAYER_RUNNER_F16_TO_BF16_TRANSITION_MASK & bit
            != 0,
    }
}

fn qwen_legacy_next_decode_residual_contract_from_label(
    label: &str,
) -> QwenResidentResidualContract {
    let layer_idx = qwen_stage_label_layer_idx(label).unwrap_or(u32::MAX);
    qwen_resident_layer_runner_residual_contract(layer_idx)
}

fn qwen_resident_layer_runner_direct_chain_readiness_from_plan_states(
    states: &[QwenResidentLayerRunnerPlanState],
    layer_idx: u32,
) -> Result<QwenResidentLayerRunnerDirectChainReadiness> {
    let plan_state = states
        .iter()
        .find(|state| state.layer_idx == layer_idx)
        .copied()
        .ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner direct chain readiness has no plan state for layer {}",
                layer_idx
            )
        })?;
    Ok(QwenResidentLayerRunnerDirectChainReadiness { plan_state })
}

fn qwen_print_resident_layer_runner_direct_chain_readiness_stage(
    states: &[QwenResidentLayerRunnerPlanState],
    layer_idx: u32,
    execution_status: &str,
    next_implementation_step: &str,
) -> Result<()> {
    let readiness =
        qwen_resident_layer_runner_direct_chain_readiness_from_plan_states(states, layer_idx)?;
    let state = readiness.plan_state;
    println!("  resident_layer_runner_layer{layer_idx}_direct_chain_readiness_stage:");
    println!("    source: resident_layer_runner_scaffold_stage");
    println!("    target: layer{layer_idx}_direct_attention_tp_o_proj_allreduce_post_attn_norm");
    println!("    plan_state_source: resident_layer_runner_plan_states");
    println!("    plan_state_layer_idx: {}", state.layer_idx);
    println!("    input_norm_ready: {}", state.input_norm);
    println!("    qkv_ready: {}", state.qkv);
    println!("    qk_norm_rope_ready: {}", state.qk_norm_rope);
    println!("    fp4_kv_cache_ready: {}", state.fp4_kv_cache);
    println!("    fp4_attention_ready: {}", state.fp4_attention);
    println!("    o_proj_ready: {}", state.o_proj);
    println!("    tp_o_proj_peer_ready: {}", state.tp_o_proj_peer);
    println!("    post_attn_norm_ready: {}", state.post_attn_norm);
    println!(
        "    all_rank_direct_attention_chain_ready: {}",
        readiness.all_rank_direct_attention_chain_ready()
    );
    println!("    execution_status: {execution_status}");
    println!("    next_implementation_step: {next_implementation_step}");
    Ok(())
}

fn qwen_resident_layer_runner_plan_descriptors_from_states(
    states: &[QwenResidentLayerRunnerPlanState],
) -> Result<Vec<QwenResidentLayerRunnerPlanDescriptor>> {
    let mut descriptors = Vec::with_capacity(QWEN_RESIDENT_LAYER_RUNNER_LAYER_TOPOLOGY.len());
    for topology in QWEN_RESIDENT_LAYER_RUNNER_LAYER_TOPOLOGY {
        let state = states
            .iter()
            .find(|state| state.layer_idx == topology.layer_idx)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner plan state for layer {} is missing",
                    topology.layer_idx
                )
            })?;
        descriptors.push(QwenResidentLayerRunnerPlanDescriptor {
            layer_idx: topology.layer_idx,
            attention_dispatch: topology.attention_dispatch,
            mlp_dispatch: topology.mlp_dispatch,
            residual_contract: qwen_resident_layer_runner_residual_contract(topology.layer_idx),
            input_norm: state.input_norm,
            qkv: state.qkv,
            qk_norm_rope: state.qk_norm_rope,
            fp4_kv_cache: state.fp4_kv_cache,
            fp4_attention: state.fp4_attention,
            o_proj: state.o_proj,
            post_attn_norm: state.post_attn_norm,
            tp_o_proj_peer: state.tp_o_proj_peer,
            mlp: state.mlp,
            tp_mlp_peer: state.tp_mlp_peer,
        });
    }
    qwen_resident_layer_runner_assign_plan_dependency_masks(descriptors.as_mut_slice())?;
    Ok(descriptors)
}

fn qwen_resident_layer_runner_assign_plan_dependency_masks(
    descriptors: &mut [QwenResidentLayerRunnerPlanDescriptor],
) -> Result<()> {
    let mut next_bit = 0u32;
    for descriptor in descriptors {
        if let Some(dispatch) = descriptor.attention_dispatch.as_mut() {
            let mask = qwen_resident_layer_runner_next_plan_dependency_mask(&mut next_bit)?;
            dispatch.wait_mask = mask;
            dispatch.signal_mask = mask;
        }
        if let Some(dispatch) = descriptor.mlp_dispatch.as_mut() {
            let mask = qwen_resident_layer_runner_next_plan_dependency_mask(&mut next_bit)?;
            dispatch.wait_mask = mask;
            dispatch.signal_mask = mask;
        }
    }
    Ok(())
}

fn qwen_resident_layer_runner_next_plan_dependency_mask(next_bit: &mut u32) -> Result<u64> {
    if *next_bit >= u64::BITS {
        anyhow::bail!(
            "resident layer runner dependency plan has more than {} dependency rows",
            u64::BITS
        );
    }
    let mask = 1u64 << *next_bit;
    *next_bit += 1;
    Ok(mask)
}

