fn qwen_resident_layer_runner_runtime_dispatch_states_from_readiness_rows(
    rows: &[QwenResidentLayerRunnerRuntimeReadinessRow],
) -> Result<Vec<QwenResidentLayerRunnerRuntimeDispatchState>> {
    qwen_resident_layer_runner_validate_unique_layer_rows(rows, "runtime readiness", |row| {
        row.layer_idx
    })?;
    Ok(rows
        .iter()
        .map(|row| {
            qwen_resident_layer_runner_runtime_dispatch_state(
                row.layer_idx,
                row.attention_stage_ready,
                row.mlp_stage_ready,
            )
        })
        .collect())
}

fn qwen_resident_layer_runner_plan_has_runtime_dispatch(
    plan: &QwenResidentLayerRunnerPlanDescriptor,
) -> bool {
    plan.attention_dispatch.is_some() || plan.mlp_dispatch.is_some()
}

fn qwen_resident_layer_runner_runtime_dispatch_observations_from_plan_descriptors_and_layer_observations(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
    layer_observations: &[QwenResidentLayerRunnerRuntimeLayerObservation],
) -> Result<Vec<QwenResidentLayerRunnerRuntimeDispatchObservation>> {
    qwen_resident_layer_runner_validate_unique_layer_rows(
        runner_plans,
        "plan descriptor",
        |plan| plan.layer_idx,
    )?;
    qwen_resident_layer_runner_validate_unique_layer_rows(
        layer_observations,
        "runtime layer observation",
        |observation| observation.layer_idx,
    )?;
    for observation in layer_observations {
        let plan = runner_plans
            .iter()
            .find(|plan| plan.layer_idx == observation.layer_idx)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner runtime layer observation {} has no plan descriptor",
                    observation.layer_idx
                )
            })?;
        if !qwen_resident_layer_runner_plan_has_runtime_dispatch(plan) {
            anyhow::bail!(
                "resident layer runner runtime layer observation {} has no planned runtime dispatch",
                observation.layer_idx
            );
        }
    }
    let mut dispatch_observations = Vec::new();
    for plan in runner_plans {
        if !qwen_resident_layer_runner_plan_has_runtime_dispatch(plan) {
            continue;
        }
        let observation = layer_observations
            .iter()
            .find(|observation| observation.layer_idx == plan.layer_idx)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner planned runtime dispatch layer {} has no runtime layer observation",
                    plan.layer_idx
                )
            })?;
        if plan.attention_dispatch.is_some() {
            dispatch_observations.push(QwenResidentLayerRunnerRuntimeDispatchObservation {
                layer_idx: plan.layer_idx,
                kind: QwenResidentLayerRunnerDispatchKind::DecodeAttention,
                satisfied: observation.attention_satisfied,
            });
        }
        if plan.mlp_dispatch.is_some() {
            dispatch_observations.push(QwenResidentLayerRunnerRuntimeDispatchObservation {
                layer_idx: plan.layer_idx,
                kind: QwenResidentLayerRunnerDispatchKind::Mlp,
                satisfied: observation.mlp_satisfied,
            });
        }
    }
    Ok(dispatch_observations)
}

fn qwen_resident_layer_runner_runtime_dependency_observations_from_plan_descriptors_and_dispatch_observations(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
    dispatch_observations: &[QwenResidentLayerRunnerRuntimeDispatchObservation],
) -> Result<Vec<QwenResidentLayerRunnerRuntimeDependencyObservation>> {
    qwen_resident_layer_runner_validate_unique_layer_rows(
        runner_plans,
        "plan descriptor",
        |plan| plan.layer_idx,
    )?;
    qwen_resident_layer_runner_validate_unique_runtime_dispatch_observation_rows(
        dispatch_observations,
    )?;
    let plan_dispatch_dependencies =
        qwen_resident_layer_runner_plan_dispatch_dependency_rows(runner_plans);
    let dependency_ids = plan_dispatch_dependencies
        .iter()
        .map(|(_, _, dependency_id)| *dependency_id)
        .collect::<Vec<_>>();
    qwen_resident_layer_runner_validate_unique_dependency_id_list(
        dependency_ids.as_slice(),
        "plan dispatch dependency",
    )?;
    for observation in dispatch_observations {
        if !plan_dispatch_dependencies
            .iter()
            .any(|(layer_idx, kind, _)| {
                *layer_idx == observation.layer_idx && *kind == observation.kind
            })
        {
            anyhow::bail!(
                "resident layer runner runtime dispatch observation layer {} {} has no planned dispatch dependency",
                observation.layer_idx,
                qwen_resident_layer_runner_dispatch_kind_label(observation.kind)
            );
        }
    }
    let mut dependency_observations = Vec::with_capacity(plan_dispatch_dependencies.len());
    for (layer_idx, kind, dependency_id) in plan_dispatch_dependencies {
        let observation = dispatch_observations
            .iter()
            .find(|observation| observation.layer_idx == layer_idx && observation.kind == kind)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner planned dispatch dependency layer {} {} has no runtime dispatch observation",
                    layer_idx,
                    qwen_resident_layer_runner_dispatch_kind_label(kind)
                )
            })?;
        dependency_observations.push(QwenResidentLayerRunnerRuntimeDependencyObservation {
            dependency_id,
            satisfied: observation.satisfied,
        });
    }
    Ok(dependency_observations)
}

fn qwen_resident_layer_runner_runtime_dependency_satisfactions_from_plan_descriptors_and_observations(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
    dependency_observations: &[QwenResidentLayerRunnerRuntimeDependencyObservation],
) -> Result<Vec<QwenResidentLayerRunnerRuntimeDependencySatisfaction>> {
    qwen_resident_layer_runner_validate_unique_layer_rows(
        runner_plans,
        "plan descriptor",
        |plan| plan.layer_idx,
    )?;
    let dependency_masks = qwen_resident_layer_runner_plan_dependency_masks(runner_plans);
    let dependency_ids = dependency_masks
        .iter()
        .map(|(dependency_id, _)| *dependency_id)
        .collect::<Vec<_>>();
    qwen_resident_layer_runner_validate_unique_dependency_id_list(
        dependency_ids.as_slice(),
        "plan dependency",
    )?;
    qwen_resident_layer_runner_validate_unique_dependency_ids(
        dependency_observations,
        "runtime dependency observation",
        |observation| observation.dependency_id,
    )?;
    for observation in dependency_observations {
        if !dependency_ids
            .iter()
            .any(|dependency_id| *dependency_id == observation.dependency_id)
        {
            anyhow::bail!(
                "resident layer runner runtime dependency observation {} has no planned dispatch dependency",
                observation.dependency_id.label()
            );
        }
    }
    let mut dependency_satisfactions = Vec::with_capacity(dependency_masks.len());
    for (dependency_id, mask) in dependency_masks {
        let observation = dependency_observations
            .iter()
            .find(|observation| observation.dependency_id == dependency_id)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner planned dependency {} has no runtime dependency observation",
                    dependency_id.label()
                )
            })?;
        dependency_satisfactions.push(QwenResidentLayerRunnerRuntimeDependencySatisfaction {
            dependency_id,
            mask,
            satisfied: observation.satisfied,
        });
    }
    Ok(dependency_satisfactions)
}

fn qwen_resident_layer_runner_runtime_stage_readiness_from_plan_descriptors(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
    dependency_satisfactions: &[QwenResidentLayerRunnerRuntimeDependencySatisfaction],
) -> Result<Vec<QwenResidentLayerRunnerRuntimeStageReadiness>> {
    qwen_resident_layer_runner_validate_unique_layer_rows(
        runner_plans,
        "plan descriptor",
        |plan| plan.layer_idx,
    )?;
    qwen_resident_layer_runner_validate_unique_dependency_ids(
        dependency_satisfactions,
        "runtime dependency satisfaction",
        |satisfaction| satisfaction.dependency_id,
    )?;
    let plan_dependency_ids = qwen_resident_layer_runner_plan_dependency_ids(runner_plans);
    qwen_resident_layer_runner_validate_unique_dependency_id_list(
        plan_dependency_ids.as_slice(),
        "plan dependency",
    )?;
    let observed_dependency_mask =
        qwen_resident_layer_runner_observed_dependency_mask(dependency_satisfactions);
    let satisfied_dependency_mask =
        qwen_resident_layer_runner_satisfied_dependency_mask(dependency_satisfactions);
    let mut stage_rows = Vec::with_capacity(
        runner_plans
            .iter()
            .filter(|plan| qwen_resident_layer_runner_plan_has_runtime_dispatch(plan))
            .count(),
    );
    for plan in runner_plans {
        if !qwen_resident_layer_runner_plan_has_runtime_dispatch(plan) {
            continue;
        }
        let attention_stage_ready = match plan.attention_dispatch {
            Some(dispatch) => qwen_resident_layer_runner_wait_mask_satisfied(
                observed_dependency_mask,
                satisfied_dependency_mask,
                dispatch,
            )?,
            None => false,
        };
        let mlp_stage_ready = match plan.mlp_dispatch {
            Some(dispatch) => qwen_resident_layer_runner_wait_mask_satisfied(
                observed_dependency_mask,
                satisfied_dependency_mask,
                dispatch,
            )?,
            None => false,
        };
        stage_rows.push(QwenResidentLayerRunnerRuntimeStageReadiness {
            layer_idx: plan.layer_idx,
            attention_stage_ready,
            attention_dependency_label: plan
                .attention_dispatch
                .map(|dispatch| dispatch.dependency_id.label()),
            mlp_stage_ready,
            mlp_dependency_label: plan
                .mlp_dispatch
                .map(|dispatch| dispatch.dependency_id.label()),
        });
    }
    for satisfaction in dependency_satisfactions {
        if !plan_dependency_ids
            .iter()
            .any(|dependency_id| *dependency_id == satisfaction.dependency_id)
        {
            anyhow::bail!(
                "resident layer runner runtime dependency satisfaction {} has no planned dispatch dependency",
                satisfaction.dependency_id.label()
            );
        }
    }
    Ok(stage_rows)
}

fn qwen_resident_layer_runner_plan_dependency_ids(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
) -> Vec<QwenResidentLayerRunnerDependencyId> {
    let mut dependency_ids = Vec::new();
    for plan in runner_plans {
        if let Some(dispatch) = plan.attention_dispatch {
            dependency_ids.push(dispatch.dependency_id);
        }
        if let Some(dispatch) = plan.mlp_dispatch {
            dependency_ids.push(dispatch.dependency_id);
        }
    }
    dependency_ids
}

fn qwen_resident_layer_runner_plan_dependency_masks(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
) -> Vec<(QwenResidentLayerRunnerDependencyId, u64)> {
    let mut dependency_masks = Vec::new();
    for plan in runner_plans {
        if let Some(dispatch) = plan.attention_dispatch {
            dependency_masks.push((dispatch.dependency_id, dispatch.wait_mask));
        }
        if let Some(dispatch) = plan.mlp_dispatch {
            dependency_masks.push((dispatch.dependency_id, dispatch.wait_mask));
        }
    }
    dependency_masks
}

fn qwen_resident_layer_runner_plan_dispatch_dependency_rows(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
) -> Vec<(
    u32,
    QwenResidentLayerRunnerDispatchKind,
    QwenResidentLayerRunnerDependencyId,
)> {
    let mut dependency_rows = Vec::new();
    for plan in runner_plans {
        if let Some(dispatch) = plan.attention_dispatch {
            dependency_rows.push((
                plan.layer_idx,
                QwenResidentLayerRunnerDispatchKind::DecodeAttention,
                dispatch.dependency_id,
            ));
        }
        if let Some(dispatch) = plan.mlp_dispatch {
            dependency_rows.push((
                plan.layer_idx,
                QwenResidentLayerRunnerDispatchKind::Mlp,
                dispatch.dependency_id,
            ));
        }
    }
    dependency_rows
}

fn qwen_resident_layer_runner_wait_mask_satisfied(
    observed_dependency_mask: u64,
    satisfied_dependency_mask: u64,
    dispatch: QwenResidentLayerRunnerDispatchPlan,
) -> Result<bool> {
    if (observed_dependency_mask & dispatch.wait_mask) != dispatch.wait_mask {
        anyhow::bail!(
            "resident layer runner runtime dependency wait_mask 0x{:016x} for {} is missing",
            dispatch.wait_mask,
            dispatch.dependency_id.label()
        );
    }
    Ok((satisfied_dependency_mask & dispatch.wait_mask) == dispatch.wait_mask)
}

fn qwen_resident_layer_runner_observed_dependency_mask(
    dependency_satisfactions: &[QwenResidentLayerRunnerRuntimeDependencySatisfaction],
) -> u64 {
    dependency_satisfactions
        .iter()
        .fold(0u64, |mask, satisfaction| mask | satisfaction.mask)
}

fn qwen_resident_layer_runner_satisfied_dependency_mask(
    dependency_satisfactions: &[QwenResidentLayerRunnerRuntimeDependencySatisfaction],
) -> u64 {
    dependency_satisfactions
        .iter()
        .filter(|satisfaction| satisfaction.satisfied)
        .fold(0u64, |mask, satisfaction| mask | satisfaction.mask)
}

fn qwen_resident_layer_runner_plan_wait_mask(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
) -> u64 {
    let mut wait_mask = 0u64;
    for plan in runner_plans {
        if let Some(dispatch) = plan.attention_dispatch {
            wait_mask |= dispatch.wait_mask;
        }
        if let Some(dispatch) = plan.mlp_dispatch {
            wait_mask |= dispatch.wait_mask;
        }
    }
    wait_mask
}

fn qwen_resident_layer_runner_plan_signal_mask(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
) -> u64 {
    let mut signal_mask = 0u64;
    for plan in runner_plans {
        if let Some(dispatch) = plan.attention_dispatch {
            signal_mask |= dispatch.signal_mask;
        }
        if let Some(dispatch) = plan.mlp_dispatch {
            signal_mask |= dispatch.signal_mask;
        }
    }
    signal_mask
}

fn qwen_resident_layer_runner_plan_dag_edge_rows(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
) -> Result<Vec<QwenResidentLayerRunnerDagEdgeRow>> {
    let mut rows = Vec::new();
    for plan in runner_plans {
        if let Some(dispatch) = plan.attention_dispatch {
            rows.push(QwenResidentLayerRunnerDagEdgeRow {
                edge_index: rows.len() as u32,
                layer_idx: plan.layer_idx,
                kind: QwenResidentLayerRunnerDispatchKind::DecodeAttention,
                wait_mask: dispatch.wait_mask,
                signal_mask: dispatch.signal_mask,
                downstream_edge_index: u32::MAX,
                downstream_wait_mask: 0,
                checksum_fnv1a64: 0,
            });
        }
        if let Some(dispatch) = plan.mlp_dispatch {
            rows.push(QwenResidentLayerRunnerDagEdgeRow {
                edge_index: rows.len() as u32,
                layer_idx: plan.layer_idx,
                kind: QwenResidentLayerRunnerDispatchKind::Mlp,
                wait_mask: dispatch.wait_mask,
                signal_mask: dispatch.signal_mask,
                downstream_edge_index: u32::MAX,
                downstream_wait_mask: 0,
                checksum_fnv1a64: 0,
            });
        }
    }
    let downstream_edges: Vec<(u32, u64)> = rows
        .iter()
        .skip(1)
        .map(|row| (row.edge_index, row.wait_mask))
        .chain(std::iter::once((u32::MAX, 0)))
        .collect();
    for (row, (downstream_edge_index, downstream_wait_mask)) in
        rows.iter_mut().zip(downstream_edges)
    {
        row.downstream_edge_index = downstream_edge_index;
        row.downstream_wait_mask = downstream_wait_mask;
        row.checksum_fnv1a64 = qwen_resident_layer_runner_dag_edge_row_checksum_fnv1a64(row);
    }
    qwen_resident_layer_runner_validate_plan_dag_edge_rows(rows.as_slice())?;
    Ok(rows)
}

fn qwen_resident_layer_runner_validate_plan_dag_edge_rows(
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> Result<()> {
    for (idx, row) in rows.iter().enumerate() {
        if row.edge_index != idx as u32 {
            anyhow::bail!(
                "resident layer runner DAG edge row {} {:?} layer {} has edge_index {}",
                idx,
                row.kind,
                row.layer_idx,
                row.edge_index
            );
        }
        if row.wait_mask == 0 {
            anyhow::bail!(
                "resident layer runner DAG edge row {} {:?} layer {} has empty wait_mask",
                idx,
                row.kind,
                row.layer_idx
            );
        }
        if row.signal_mask == 0 {
            anyhow::bail!(
                "resident layer runner DAG edge row {} {:?} layer {} has empty signal_mask",
                idx,
                row.kind,
                row.layer_idx
            );
        }
        let expected_downstream_edge_index = rows
            .get(idx + 1)
            .map(|next| next.edge_index)
            .unwrap_or(u32::MAX);
        let expected_downstream_wait_mask =
            rows.get(idx + 1).map(|next| next.wait_mask).unwrap_or(0);
        if row.downstream_edge_index != expected_downstream_edge_index {
            anyhow::bail!(
                "resident layer runner DAG edge row {} {:?} layer {} downstream_edge_index {} expected {}",
                idx,
                row.kind,
                row.layer_idx,
                row.downstream_edge_index,
                expected_downstream_edge_index
            );
        }
        if row.downstream_wait_mask != expected_downstream_wait_mask {
            anyhow::bail!(
                "resident layer runner DAG edge row {} {:?} layer {} downstream_wait_mask 0x{:016x} expected 0x{:016x}",
                idx,
                row.kind,
                row.layer_idx,
                row.downstream_wait_mask,
                expected_downstream_wait_mask
            );
        }
        let expected_checksum = qwen_resident_layer_runner_dag_edge_row_checksum_fnv1a64(row);
        if row.checksum_fnv1a64 != expected_checksum {
            anyhow::bail!(
                "resident layer runner DAG edge row {} {:?} layer {} checksum 0x{:016x} expected 0x{:016x}",
                idx,
                row.kind,
                row.layer_idx,
                row.checksum_fnv1a64,
                expected_checksum
            );
        }
    }
    Ok(())
}

pub(crate) fn qwen_resident_layer_runner_dispatch_kind_code(
    kind: QwenResidentLayerRunnerDispatchKind,
) -> u64 {
    match kind {
        QwenResidentLayerRunnerDispatchKind::DecodeAttention => 1,
        QwenResidentLayerRunnerDispatchKind::Mlp => 2,
    }
}

pub(crate) fn qwen_resident_layer_runner_dispatch_kind_from_code(
    code: u64,
) -> Result<QwenResidentLayerRunnerDispatchKind> {
    match code {
        1 => Ok(QwenResidentLayerRunnerDispatchKind::DecodeAttention),
        2 => Ok(QwenResidentLayerRunnerDispatchKind::Mlp),
        _ => anyhow::bail!(
            "resident layer runner dispatch kind code {} is not recognized",
            code
        ),
    }
}

pub(crate) fn qwen_resident_layer_runner_dispatch_kind_label(
    kind: QwenResidentLayerRunnerDispatchKind,
) -> &'static str {
    match kind {
        QwenResidentLayerRunnerDispatchKind::DecodeAttention => "attention",
        QwenResidentLayerRunnerDispatchKind::Mlp => "mlp",
    }
}

fn qwen_resident_layer_runner_fnv1a64_update(mut hash: u64, value: u64) -> u64 {
    for byte in value.to_le_bytes() {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x00000100000001b3);
    }
    hash
}

fn qwen_resident_layer_runner_dag_edge_row_checksum_fnv1a64(
    row: &QwenResidentLayerRunnerDagEdgeRow,
) -> u64 {
    let mut hash = 0xcbf29ce484222325;
    hash = qwen_resident_layer_runner_fnv1a64_update(hash, u64::from(row.edge_index));
    hash = qwen_resident_layer_runner_fnv1a64_update(hash, u64::from(row.layer_idx));
    hash = qwen_resident_layer_runner_fnv1a64_update(
        hash,
        qwen_resident_layer_runner_dispatch_kind_code(row.kind),
    );
    hash = qwen_resident_layer_runner_fnv1a64_update(hash, row.wait_mask);
    hash = qwen_resident_layer_runner_fnv1a64_update(hash, row.signal_mask);
    hash = qwen_resident_layer_runner_fnv1a64_update(hash, u64::from(row.downstream_edge_index));
    qwen_resident_layer_runner_fnv1a64_update(hash, row.downstream_wait_mask)
}

fn qwen_resident_layer_runner_dag_edge_last_index(
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> u32 {
    rows.last().map(|row| row.edge_index).unwrap_or(u32::MAX)
}

fn qwen_resident_layer_runner_dag_edge_wait_mask(
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> u64 {
    rows.iter().fold(0u64, |mask, row| mask | row.wait_mask)
}

fn qwen_resident_layer_runner_dag_edge_signal_mask(
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> u64 {
    rows.iter().fold(0u64, |mask, row| mask | row.signal_mask)
}

fn qwen_resident_layer_runner_dag_edge_downstream_wait_mask(
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> u64 {
    rows.iter()
        .fold(0u64, |mask, row| mask | row.downstream_wait_mask)
}

fn qwen_resident_layer_runner_dag_terminal_signal_mask(
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> u64 {
    rows.last().map(|row| row.signal_mask).unwrap_or(0)
}

fn qwen_resident_layer_runner_dag_edge_checksum_fnv1a64(
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> u64 {
    rows.iter().fold(0xcbf29ce484222325, |hash, row| {
        qwen_resident_layer_runner_fnv1a64_update(hash, row.checksum_fnv1a64)
    })
}

fn qwen_resident_layer_runner_dag_edge_row_trace(
    rows: &[QwenResidentLayerRunnerDagEdgeRow],
) -> String {
    rows.iter()
        .map(|row| {
            let downstream = if row.downstream_edge_index == u32::MAX {
                "terminal".to_string()
            } else {
                row.downstream_edge_index.to_string()
            };
            format!(
                "{}:{}:{}:wait=0x{:016x}:signal=0x{:016x}:downstream={}:downstream_wait=0x{:016x}:checksum=0x{:016x}",
                row.edge_index,
                row.layer_idx,
                qwen_resident_layer_runner_dispatch_kind_label(row.kind),
                row.wait_mask,
                row.signal_mask,
                downstream,
                row.downstream_wait_mask,
                row.checksum_fnv1a64
            )
        })
        .collect::<Vec<_>>()
        .join(",")
}

fn qwen_resident_layer_runner_runtime_readiness_rows_from_entries(
    runner_entries: &[QwenResidentLayerRunnerEntry],
    stage_rows: &[QwenResidentLayerRunnerRuntimeStageReadiness],
) -> Result<Vec<QwenResidentLayerRunnerRuntimeReadinessRow>> {
    qwen_resident_layer_runner_validate_unique_layer_rows(runner_entries, "entry", |entry| {
        entry.layer_idx
    })?;
    qwen_resident_layer_runner_validate_unique_layer_rows(
        stage_rows,
        "runtime stage readiness",
        |row| row.layer_idx,
    )?;
    let mut rows = Vec::with_capacity(stage_rows.len());
    for entry in runner_entries {
        if let Some(stage_row) = stage_rows
            .iter()
            .find(|stage_row| stage_row.layer_idx == entry.layer_idx)
        {
            rows.push(QwenResidentLayerRunnerRuntimeReadinessRow {
                layer_idx: entry.layer_idx,
                attention_stage_ready: stage_row.attention_stage_ready,
                mlp_stage_ready: stage_row.mlp_stage_ready,
            });
        }
    }
    for stage_row in stage_rows {
        if !runner_entries
            .iter()
            .any(|entry| entry.layer_idx == stage_row.layer_idx)
        {
            return Err(anyhow::anyhow!(
                "resident layer runner runtime stage readiness row for layer {} has no runner entry",
                stage_row.layer_idx
            ));
        }
    }
    Ok(rows)
}

fn qwen_resident_layer_runner_mlp_dispatch_plan_for_layer(
    layer_idx: u32,
) -> Result<QwenResidentLayerRunnerDispatchPlan> {
    QWEN_RESIDENT_LAYER_RUNNER_LAYER_TOPOLOGY
        .iter()
        .find(|topology| topology.layer_idx == layer_idx)
        .and_then(|topology| topology.mlp_dispatch)
        .ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner MLP dispatch plan for layer {layer_idx} is missing"
            )
        })
}

fn qwen_resident_layer_runner_dispatch_plan_enabled(
    dispatch: QwenResidentLayerRunnerDispatchPlan,
) -> bool {
    dispatch.default_enabled
        && dispatch
            .disable_env
            .map(|env| std::env::var_os(env).is_none())
            .unwrap_or(true)
}

fn qwen_resident_layer_runner_dispatch_disable_env_label(
    dispatch: QwenResidentLayerRunnerDispatchPlan,
) -> &'static str {
    dispatch.disable_env.unwrap_or("none")
}

fn qwen_resident_layer_runner_mlp_launch_function(
    dispatch: QwenResidentLayerRunnerDispatchPlan,
) -> &'static str {
    dispatch
        .launch_function
        .unwrap_or("qwen_resident_layer_runner_launch_mlp")
}

fn qwen_resident_layer_runner_dispatch_readiness_from_runtime_states(
    runner_entries: &[QwenResidentLayerRunnerEntry],
    runtime_states: &[QwenResidentLayerRunnerRuntimeDispatchState],
) -> Result<Vec<QwenResidentLayerRunnerDispatchReadiness>> {
    qwen_resident_layer_runner_validate_unique_layer_rows(runner_entries, "entry", |entry| {
        entry.layer_idx
    })?;
    qwen_resident_layer_runner_validate_unique_layer_rows(
        runtime_states,
        "runtime dispatch state",
        |state| state.layer_idx,
    )?;
    let mut readiness = Vec::with_capacity(runtime_states.len());
    for runtime_state in runtime_states {
        let entry = runner_entries
            .iter()
            .find(|entry| entry.layer_idx == runtime_state.layer_idx)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner entry for runtime dispatch layer {} is missing",
                    runtime_state.layer_idx
                )
            })?;
        readiness.push(QwenResidentLayerRunnerDispatchReadiness {
            layer_idx: runtime_state.layer_idx,
            attention_enabled: runtime_state.attention_stage_ready
                && entry.decode_attention_launch_eligible(),
            mlp_enabled: runtime_state.mlp_stage_ready && entry.mlp_launch_eligible(),
        });
    }
    Ok(readiness)
}

fn qwen_resident_layer_runner_validate_unique_layer_rows<T, F>(
    rows: &[T],
    label: &str,
    layer_idx: F,
) -> Result<()>
where
    F: Fn(&T) -> u32,
{
    for left in 0..rows.len() {
        let left_layer_idx = layer_idx(&rows[left]);
        for right in (left + 1)..rows.len() {
            let right_layer_idx = layer_idx(&rows[right]);
            if left_layer_idx == right_layer_idx {
                anyhow::bail!(
                    "resident layer runner {label} rows contain duplicate layer_idx {}",
                    left_layer_idx
                );
            }
        }
    }
    Ok(())
}

fn qwen_resident_layer_runner_validate_unique_dependency_ids<T, F>(
    rows: &[T],
    label: &str,
    dependency_id: F,
) -> Result<()>
where
    F: Fn(&T) -> QwenResidentLayerRunnerDependencyId,
{
    for left in 0..rows.len() {
        let left_dependency_id = dependency_id(&rows[left]);
        for right in (left + 1)..rows.len() {
            let right_dependency_id = dependency_id(&rows[right]);
            if left_dependency_id == right_dependency_id {
                anyhow::bail!(
                    "resident layer runner {label} rows contain duplicate dependency_id {}",
                    left_dependency_id.label()
                );
            }
        }
    }
    Ok(())
}

fn qwen_resident_layer_runner_validate_unique_dependency_id_list(
    dependency_ids: &[QwenResidentLayerRunnerDependencyId],
    label: &str,
) -> Result<()> {
    for left in 0..dependency_ids.len() {
        for right in (left + 1)..dependency_ids.len() {
            if dependency_ids[left] == dependency_ids[right] {
                anyhow::bail!(
                    "resident layer runner {label} rows contain duplicate dependency_id {}",
                    dependency_ids[left].label()
                );
            }
        }
    }
    Ok(())
}

fn qwen_resident_layer_runner_validate_unique_runtime_dispatch_observation_rows(
    rows: &[QwenResidentLayerRunnerRuntimeDispatchObservation],
) -> Result<()> {
    for left in 0..rows.len() {
        let left_row = rows[left];
        for right in (left + 1)..rows.len() {
            let right_row = rows[right];
            if left_row.layer_idx == right_row.layer_idx && left_row.kind == right_row.kind {
                anyhow::bail!(
                    "resident layer runner runtime dispatch observations contain duplicate layer {} {} rows",
                    left_row.layer_idx,
                    qwen_resident_layer_runner_dispatch_kind_label(left_row.kind)
                );
            }
        }
    }
    Ok(())
}

fn qwen_resident_layer_runner_configured_dispatch_count(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
    kind: QwenResidentLayerRunnerDispatchKind,
) -> usize {
    runner_plans
        .iter()
        .filter(|plan| match kind {
            QwenResidentLayerRunnerDispatchKind::DecodeAttention => {
                plan.attention_dispatch.is_some()
            }
            QwenResidentLayerRunnerDispatchKind::Mlp => plan.mlp_dispatch.is_some(),
        })
        .count()
}

fn qwen_resident_layer_runner_topology_disable_env_count(
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
    kind: QwenResidentLayerRunnerDispatchKind,
) -> usize {
    runner_plans
        .iter()
        .filter_map(|plan| match kind {
            QwenResidentLayerRunnerDispatchKind::DecodeAttention => plan.attention_dispatch,
            QwenResidentLayerRunnerDispatchKind::Mlp => plan.mlp_dispatch,
        })
        .filter(|dispatch| dispatch.disable_env.is_some())
        .count()
}

fn qwen_print_packet_completion_lease_proof(
    prefix: &str,
    packet: Option<mcore::AqlLastDispatchCompletion>,
    in_flight_rearm_rejected: Option<bool>,
) {
    if let Some(packet) = packet {
        println!(
            "    {prefix}_completion_signal_bound: {}",
            packet.packet_completion_signal_bound
        );
        println!("    {prefix}_dedicated_signal: {}", packet.dedicated_signal);
        println!(
            "    {prefix}_dedicated_signal_slot: {}",
            packet.dedicated_signal_slot.unwrap_or(usize::MAX)
        );
        println!(
            "    {prefix}_dedicated_signal_epoch: {}",
            packet.dedicated_signal_epoch
        );
        println!(
            "    {prefix}_dedicated_signal_active_on_publish: {}",
            packet.dedicated_signal_active_on_publish
        );
        println!(
            "    {prefix}_dedicated_signal_released_after_wait: {}",
            packet.dedicated_signal_released_after_wait
        );
        println!(
            "    {prefix}_dedicated_signal_reuse_guard_passed: {}",
            packet.dedicated_signal_reuse_guard_passed
        );
        if let Some(rejected) = in_flight_rearm_rejected {
            println!("    {prefix}_in_flight_rearm_rejected: {}", rejected);
        }
        println!(
            "    {prefix}_queue_write_index: {}",
            packet.queue_write_index
        );
        println!(
            "    {prefix}_completion_signal_va: 0x{:016x}",
            packet.completion_signal_va
        );
        println!(
            "    {prefix}_completion_signal_initial_value: {}",
            packet.completion_signal_initial_value
        );
        println!(
            "    {prefix}_completion_signal_after_wait: {}",
            packet.completion_signal_after_wait
        );
        println!(
            "    {prefix}_host_signal_poll_completed: {}",
            packet.host_signal_poll_completed
        );
        println!(
            "    {prefix}_completion_signal_reached_success: {}",
            packet.completion_signal_reached_success
        );
    } else {
        println!("    {prefix}_completion_signal_bound: false");
    }
}

#[derive(Clone, Copy)]
struct QwenResidentLayerRunnerDispatchCursorRow {
    cursor_index: usize,
    ready_ordinal: usize,
    marker: QwenResidentLayerRunnerDispatchMarker,
}

#[derive(Clone, Copy)]
struct QwenResidentLayerRunnerDispatchCursorCandidate {
    frontier_edge_index: usize,
    cursor_row: QwenResidentLayerRunnerDispatchCursorRow,
}

fn qwen_resident_layer_runner_cursor_dispatch_kind_name(
    kind: QwenResidentLayerRunnerDispatchKind,
) -> &'static str {
    match kind {
        QwenResidentLayerRunnerDispatchKind::DecodeAttention => "attention",
        QwenResidentLayerRunnerDispatchKind::Mlp => "mlp",
    }
}

fn qwen_resident_layer_runner_dispatch_cursor_from_markers(
    markers: &[QwenResidentLayerRunnerDispatchMarker],
) -> Result<Vec<QwenResidentLayerRunnerDispatchCursorRow>> {
    let mut rows = Vec::new();
    for marker in markers {
        if !marker.enabled {
            anyhow::bail!(
                "resident layer runner dispatch cursor cannot include disabled marker for layer {} {:?}",
                marker.layer_idx,
                marker.kind
            );
        }
        if rows
            .iter()
            .any(|row: &QwenResidentLayerRunnerDispatchCursorRow| {
                row.marker.layer_idx == marker.layer_idx && row.marker.kind == marker.kind
            })
        {
            anyhow::bail!(
                "resident layer runner dispatch cursor duplicate marker for layer {} {:?}",
                marker.layer_idx,
                marker.kind
            );
        }
        let cursor_index = rows.len();
        rows.push(QwenResidentLayerRunnerDispatchCursorRow {
            cursor_index,
            ready_ordinal: cursor_index,
            marker: *marker,
        });
    }
    Ok(rows)
}

fn qwen_resident_layer_runner_dispatch_cursor_candidate_from_frontier(
    rows: &[QwenResidentLayerRunnerDispatchCursorRow],
    frontier_edge_index: usize,
) -> Result<QwenResidentLayerRunnerDispatchCursorCandidate> {
    if rows.is_empty() {
        anyhow::bail!(
            "resident layer runner dispatch cursor cannot admit frontier edge {} from an empty cursor",
            frontier_edge_index
        );
    }

    let mut cursor_row = None;
    for (expected_cursor_index, row) in rows.iter().copied().enumerate() {
        if row.cursor_index != expected_cursor_index {
            anyhow::bail!(
                "resident layer runner dispatch cursor row {} is out of order at walk index {}",
                row.cursor_index,
                expected_cursor_index
            );
        }
        if row.ready_ordinal != expected_cursor_index {
            anyhow::bail!(
                "resident layer runner dispatch cursor row {} has non-contiguous ready ordinal {}",
                row.cursor_index,
                row.ready_ordinal
            );
        }
        if row.ready_ordinal == frontier_edge_index {
            cursor_row = Some(row);
            break;
        }
        if row.ready_ordinal > frontier_edge_index {
            break;
        }
    }

    let cursor_row = cursor_row.ok_or_else(|| {
        anyhow::anyhow!(
            "resident layer runner dispatch cursor walk reached no row for frontier edge {}",
            frontier_edge_index
        )
    })?;
    if cursor_row.cursor_index != frontier_edge_index {
        anyhow::bail!(
            "resident layer runner dispatch cursor row {} does not match frontier edge {}",
            cursor_row.cursor_index,
            frontier_edge_index
        );
    }
    Ok(QwenResidentLayerRunnerDispatchCursorCandidate {
        frontier_edge_index,
        cursor_row,
    })
}

fn qwen_resident_layer_runner_dispatch_cursor_trace(
    rows: &[QwenResidentLayerRunnerDispatchCursorRow],
) -> String {
    rows.iter()
        .map(|row| {
            format!(
                "{}:{}:{}:ready={}",
                row.cursor_index,
                row.marker.layer_idx,
                qwen_resident_layer_runner_cursor_dispatch_kind_name(row.marker.kind),
                row.ready_ordinal
            )
        })
        .collect::<Vec<_>>()
        .join(",")
}

fn qwen_resident_layer_runner_dispatch_cursor_candidate_trace(
    candidate: QwenResidentLayerRunnerDispatchCursorCandidate,
) -> String {
    format!(
        "{}:{}:{}:frontier={}:ready={}:walked={}",
        candidate.cursor_row.cursor_index,
        candidate.cursor_row.marker.layer_idx,
        qwen_resident_layer_runner_cursor_dispatch_kind_name(candidate.cursor_row.marker.kind),
        candidate.frontier_edge_index,
        candidate.cursor_row.ready_ordinal,
        candidate.frontier_edge_index + 1
    )
}

#[derive(Debug)]
struct QwenResidentLayerRunnerLoopExecutorSkeleton {
    plan_rows: usize,
    static_buffer_registry_rows: usize,
    static_h_buffer_slots: usize,
    static_h_buffer_bytes: usize,
    tp_world: usize,
    h_bytes_per_rank: usize,
    dispatch_steps: usize,
    attention_steps: usize,
    mlp_steps: usize,
    first_layer: u32,
    last_layer: u32,
    f16_residual_rows: usize,
    bf16_residual_rows: usize,
    f16_to_bf16_transition_rows: usize,
    all_rows_resident_and_async_ready: bool,
    all_steps_piecewise_comm_break: bool,
    all_launch_functions_static: bool,
    loop_order_trace: String,
}

fn qwen_resident_layer_runner_loop_executor_skeleton_from_plan(
    runner_entries: &[QwenResidentLayerRunnerEntry],
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
    readiness: &[QwenResidentLayerRunnerDispatchReadiness],
    dispatch_markers: &[QwenResidentLayerRunnerDispatchMarker],
    tp_world: usize,
    h_bytes_per_rank: usize,
) -> Result<QwenResidentLayerRunnerLoopExecutorSkeleton> {
    if tp_world == 0 {
        anyhow::bail!("resident layer runner loop executor skeleton requires nonzero TP world");
    }
    if h_bytes_per_rank == 0 {
        anyhow::bail!(
            "resident layer runner loop executor skeleton requires nonzero H buffer byte count"
        );
    }
    qwen_resident_layer_runner_validate_unique_layer_rows(runner_entries, "entry", |entry| {
        entry.layer_idx
    })?;
    qwen_resident_layer_runner_validate_unique_layer_rows(
        runner_plans,
        "plan descriptor",
        |plan| plan.layer_idx,
    )?;
    qwen_resident_layer_runner_validate_unique_layer_rows(
        readiness,
        "dispatch readiness",
        |row| row.layer_idx,
    )?;

    let mut first_layer = u32::MAX;
    let mut last_layer = 0u32;
    let mut f16_residual_rows = 0usize;
    let mut bf16_residual_rows = 0usize;
    let mut f16_to_bf16_transition_rows = 0usize;
    let mut all_rows_resident_and_async_ready = true;

    for plan in runner_plans {
        let entry = runner_entries
            .iter()
            .find(|entry| entry.layer_idx == plan.layer_idx)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner loop executor skeleton plan layer {} has no runner entry",
                    plan.layer_idx
                )
            })?;
        qwen_resident_layer_runner_validate_entry_contract(entry, "loop executor skeleton")?;
        if entry.layer_idx < first_layer {
            first_layer = entry.layer_idx;
        }
        if entry.layer_idx > last_layer {
            last_layer = entry.layer_idx;
        }
        match entry.residual_contract.storage {
            QwenResidentResidualStorage::F16 => f16_residual_rows += 1,
            QwenResidentResidualStorage::Bf16 => bf16_residual_rows += 1,
        }
        if entry.residual_contract.transition_from_f16_to_bf16 {
            f16_to_bf16_transition_rows += 1;
        }
        all_rows_resident_and_async_ready &=
            entry.residency_ready() && entry.async_boundary_ready();
    }

    for readiness_row in readiness {
        if !runner_plans
            .iter()
            .any(|plan| plan.layer_idx == readiness_row.layer_idx)
        {
            anyhow::bail!(
                "resident layer runner loop executor skeleton readiness layer {} has no plan descriptor",
                readiness_row.layer_idx
            );
        }
    }

    let attention_steps = dispatch_markers
        .iter()
        .filter(|marker| marker.kind == QwenResidentLayerRunnerDispatchKind::DecodeAttention)
        .count();
    let mlp_steps = dispatch_markers
        .iter()
        .filter(|marker| marker.kind == QwenResidentLayerRunnerDispatchKind::Mlp)
        .count();
    let all_steps_piecewise_comm_break = dispatch_markers.iter().all(|marker| {
        marker.capture_boundary == QwenResidentLayerRunnerCaptureBoundary::PiecewiseCommBreak
    });
    let all_launch_functions_static = dispatch_markers
        .iter()
        .all(|marker| !marker.launch_function.is_empty());
    let loop_order_trace = dispatch_markers
        .iter()
        .enumerate()
        .map(|(idx, marker)| {
            format!(
                "{}:{}:{}:{}",
                idx,
                marker.layer_idx,
                qwen_resident_layer_runner_cursor_dispatch_kind_name(marker.kind),
                marker.capture_boundary.label()
            )
        })
        .collect::<Vec<_>>()
        .join(",");

    Ok(QwenResidentLayerRunnerLoopExecutorSkeleton {
        plan_rows: runner_plans.len(),
        static_buffer_registry_rows: runner_entries.len(),
        static_h_buffer_slots: runner_entries.len() * tp_world,
        static_h_buffer_bytes: runner_entries.len() * tp_world * h_bytes_per_rank,
        tp_world,
        h_bytes_per_rank,
        dispatch_steps: dispatch_markers.len(),
        attention_steps,
        mlp_steps,
        first_layer: if first_layer == u32::MAX {
            0
        } else {
            first_layer
        },
        last_layer,
        f16_residual_rows,
        bf16_residual_rows,
        f16_to_bf16_transition_rows,
        all_rows_resident_and_async_ready,
        all_steps_piecewise_comm_break,
        all_launch_functions_static,
        loop_order_trace,
    })
}

fn qwen_resident_layer_runner_dispatch_kind_is_token_commit_boundary(
    kind: QwenResidentLayerRunnerDispatchKind,
) -> bool {
    match kind {
        QwenResidentLayerRunnerDispatchKind::DecodeAttention => false,
        QwenResidentLayerRunnerDispatchKind::Mlp => false,
    }
}

fn qwen_resident_layer_runner_dispatch_markers_from_plan_ordered_configs(
    runner_entries: &[QwenResidentLayerRunnerEntry],
    runner_plans: &[QwenResidentLayerRunnerPlanDescriptor],
    readiness: &[QwenResidentLayerRunnerDispatchReadiness],
) -> Result<Vec<QwenResidentLayerRunnerDispatchMarker>> {
    qwen_resident_layer_runner_validate_unique_layer_rows(runner_entries, "entry", |entry| {
        entry.layer_idx
    })?;
    qwen_resident_layer_runner_validate_unique_layer_rows(
        runner_plans,
        "plan descriptor",
        |plan| plan.layer_idx,
    )?;
    qwen_resident_layer_runner_validate_unique_layer_rows(
        readiness,
        "dispatch readiness",
        |row| row.layer_idx,
    )?;

    let mut markers = Vec::new();
    for plan in runner_plans {
        if plan.attention_dispatch.is_none() && plan.mlp_dispatch.is_none() {
            continue;
        }
        let entry = runner_entries
            .iter()
            .find(|entry| entry.layer_idx == plan.layer_idx)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner dispatch plan for layer {} has no runner entry",
                    plan.layer_idx
                )
            })?;
        let readiness = readiness
            .iter()
            .find(|readiness| readiness.layer_idx == plan.layer_idx)
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner dispatch plan for layer {} is configured but missing runtime readiness row",
                    plan.layer_idx
                )
            })?;

        if let Some(dispatch) = plan.attention_dispatch {
            if readiness.attention_enabled {
                markers.push(qwen_resident_layer_runner_attention_dispatch_marker(
                    true,
                    entry.layer_idx,
                    dispatch,
                ));
            }
        }
        if let Some(dispatch) = plan.mlp_dispatch {
            if readiness.mlp_enabled {
                markers.push(qwen_resident_layer_runner_mlp_dispatch_marker(
                    true,
                    entry.layer_idx,
                    dispatch,
                ));
            }
        }
    }

    Ok(markers)
}

fn qwen_resident_layer_runner_dispatch_markers_for_kind(
    markers: &[QwenResidentLayerRunnerDispatchMarker],
    kind: QwenResidentLayerRunnerDispatchKind,
) -> Vec<QwenResidentLayerRunnerDispatchMarker> {
    markers
        .iter()
        .copied()
        .filter(|marker| marker.kind == kind)
        .collect()
}

fn qwen_resident_layer_runner_attention_dispatch_marker(
    enabled: bool,
    layer_idx: u32,
    dispatch: QwenResidentLayerRunnerDispatchPlan,
) -> QwenResidentLayerRunnerDispatchMarker {
    QwenResidentLayerRunnerDispatchMarker {
        enabled,
        kind: QwenResidentLayerRunnerDispatchKind::DecodeAttention,
        layer_idx,
        next_required: dispatch.next_required,
        capture_boundary: dispatch.capture_boundary,
        launch_function: dispatch
            .launch_function
            .unwrap_or("qwen_resident_layer_runner_launch_decode_attention"),
    }
}

fn qwen_resident_layer_runner_mlp_dispatch_marker(
    enabled: bool,
    layer_idx: u32,
    dispatch: QwenResidentLayerRunnerDispatchPlan,
) -> QwenResidentLayerRunnerDispatchMarker {
    QwenResidentLayerRunnerDispatchMarker {
        enabled,
        kind: QwenResidentLayerRunnerDispatchKind::Mlp,
        layer_idx,
        next_required: dispatch.next_required,
        capture_boundary: dispatch.capture_boundary,
        launch_function: dispatch
            .launch_function
            .unwrap_or("qwen_resident_layer_runner_launch_mlp"),
    }
}

#[derive(Clone, Copy)]
struct QwenResidentLayerRunnerF16FiniteStats {
    elements: usize,
    max_abs: f32,
    max_dim: usize,
}

fn qwen_resident_layer_runner_validate_f16_byte_len(
    layer_idx: u32,
    label: &str,
    rank_label: &str,
    bytes: &[u8],
    expected_bytes: usize,
) -> Result<usize> {
    qwen_resident_layer_runner_validate_f16_byte_len_for_context(
        "generic MLP",
        layer_idx,
        label,
        rank_label,
        bytes,
        expected_bytes,
    )
}

fn qwen_resident_layer_runner_validate_f16_byte_len_for_context(
    context: &str,
    layer_idx: u32,
    label: &str,
    rank_label: &str,
    bytes: &[u8],
    expected_bytes: usize,
) -> Result<usize> {
    if bytes.len() != expected_bytes {
        anyhow::bail!(
            "resident layer runner {context} layer {layer_idx} {label} {rank_label} byte length {} != expected {}",
            bytes.len(),
            expected_bytes
        );
    }
    if bytes.len() % 2 != 0 {
        anyhow::bail!(
            "resident layer runner {context} layer {layer_idx} {label} {rank_label} has odd f16 byte length {}",
            bytes.len()
        );
    }
    Ok(bytes.len() / 2)
}

fn qwen_resident_layer_runner_validate_f16_finite_bytes(
    layer_idx: u32,
    label: &str,
    rank_label: &str,
    bytes: &[u8],
    expected_bytes: usize,
) -> Result<QwenResidentLayerRunnerF16FiniteStats> {
    qwen_resident_layer_runner_validate_f16_finite_bytes_for_context(
        "generic MLP",
        layer_idx,
        label,
        rank_label,
        bytes,
        expected_bytes,
    )
}

fn qwen_resident_layer_runner_validate_f16_finite_bytes_for_context(
    context: &str,
    layer_idx: u32,
    label: &str,
    rank_label: &str,
    bytes: &[u8],
    expected_bytes: usize,
) -> Result<QwenResidentLayerRunnerF16FiniteStats> {
    let elements = qwen_resident_layer_runner_validate_f16_byte_len_for_context(
        context,
        layer_idx,
        label,
        rank_label,
        bytes,
        expected_bytes,
    )?;
    let mut max_abs = 0.0f32;
    let mut max_dim = 0usize;
    for (dim, pair) in bytes.chunks_exact(2).enumerate() {
        let bits = u16::from_le_bytes([pair[0], pair[1]]);
        if bits & 0x7c00 == 0x7c00 {
            let value = mcore::gemm::f16_to_f32(bits);
            anyhow::bail!(
                "resident layer runner {context} layer {layer_idx} {label} {rank_label} contains non-finite f16 at dim {dim}: bits=0x{bits:04x} value={value}"
            );
        }
        let abs = mcore::gemm::f16_to_f32(bits).abs();
        if abs > max_abs {
            max_abs = abs;
            max_dim = dim;
        }
    }
    Ok(QwenResidentLayerRunnerF16FiniteStats {
        elements,
        max_abs,
        max_dim,
    })
}

fn qwen_resident_layer_runner_validate_bf16_finite_bytes_for_context(
    context: &str,
    layer_idx: u32,
    label: &str,
    rank_label: &str,
    bytes: &[u8],
    expected_bytes: usize,
) -> Result<QwenResidentLayerRunnerF16FiniteStats> {
    let elements = qwen_resident_layer_runner_validate_f16_byte_len_for_context(
        context,
        layer_idx,
        label,
        rank_label,
        bytes,
        expected_bytes,
    )?;
    let mut max_abs = 0.0f32;
    let mut max_dim = 0usize;
    for (dim, pair) in bytes.chunks_exact(2).enumerate() {
        let bits = u16::from_le_bytes([pair[0], pair[1]]);
        if bits & 0x7f80 == 0x7f80 {
            let value = bf16_to_f32(bits);
            anyhow::bail!(
                "resident layer runner {context} layer {layer_idx} {label} {rank_label} contains non-finite bf16 at dim {dim}: bits=0x{bits:04x} value={value}"
            );
        }
        let abs = bf16_to_f32(bits).abs();
        if abs > max_abs {
            max_abs = abs;
            max_dim = dim;
        }
    }
    Ok(QwenResidentLayerRunnerF16FiniteStats {
        elements,
        max_abs,
        max_dim,
    })
}

fn qwen_stage_label_layer_idx(label: &str) -> Option<u32> {
    let marker = "model.layers.";
    let start = label.find(marker)? + marker.len();
    let digits = label[start..]
        .chars()
        .take_while(|ch| ch.is_ascii_digit())
        .collect::<String>();
    if digits.is_empty() {
        None
    } else {
        digits.parse::<u32>().ok()
    }
}

fn qwen_prepare_next_decode_layer_rank_h_buffers(
    dev: &mut mcore::GpuDevice,
    peer_workspaces: &mut [QwenPeerMlpWorkspace],
    outputs: &mut Vec<mcore::DeviceBuffer>,
    tp_world: usize,
    h_bytes: usize,
    layer_idx: u32,
    buffer_label: &str,
) -> Result<()> {
    outputs.clear();
    outputs.push(dev.alloc(h_bytes)?);
    for peer_workspace in peer_workspaces.iter_mut().take(tp_world.saturating_sub(1)) {
        outputs.push(peer_workspace.dev.alloc(h_bytes)?);
    }
    if outputs.len() != tp_world {
        anyhow::bail!(
            "next decode layer{layer_idx} {buffer_label} output count {} does not match TP{}",
            outputs.len(),
            tp_world
        );
    }
    Ok(())
}

struct QwenResidentLayerRunnerMlpShadowSnapshot {
    residual_outputs: Option<Vec<Vec<u8>>>,
    next_input_norm_outputs: Option<Vec<Vec<u8>>>,
}

#[allow(clippy::too_many_arguments)]
fn qwen_resident_layer_runner_run_mlp_unrolled_shadow_snapshot(
    layer_idx: u32,
    dev: &mut mcore::GpuDevice,
    peer_workspaces: &mut [QwenPeerMlpWorkspace],
    mlp: &QwenMlpStagePlan,
    peer_mlp: &QwenTpMlpPeerStagePlan,
    nodes: &[u32],
    post_norm_outputs: &mut [mcore::DeviceBuffer],
    mut residual_replicas: Option<&mut [mcore::DeviceBuffer]>,
    next_input_norm: Option<&QwenNextInputNormStagePlan>,
    next_input_norm_outputs_required: bool,
    h_size: u32,
    h_bytes: usize,
    poison_h: u16,
    residual_contract: QwenResidentResidualContract,
    dag_scheduler: QwenResidentLayerRunnerDagSchedulerContext<'_>,
    gate_w: &mut mcore::DeviceBuffer,
    up_w: &mut mcore::DeviceBuffer,
    down_w: &mut mcore::DeviceBuffer,
    gate_out: &mut mcore::DeviceBuffer,
    up_out: &mut mcore::DeviceBuffer,
    gate_f16: &mut mcore::DeviceBuffer,
    up_f16: &mut mcore::DeviceBuffer,
    swiglu_out: &mut mcore::DeviceBuffer,
) -> Result<QwenResidentLayerRunnerMlpShadowSnapshot> {
    let tp_world = nodes.len();
    let mut shadow_post_norm_outputs = Vec::new();
    qwen_prepare_next_decode_layer_rank_h_buffers(
        dev,
        peer_workspaces,
        &mut shadow_post_norm_outputs,
        tp_world,
        h_bytes,
        layer_idx,
        "loop equivalence post norm shadow",
    )?;
    for rank in 0..tp_world {
        let input_bytes =
            unsafe { post_norm_outputs[rank].as_mut_slice_of::<u8>()[..h_bytes].to_vec() };
        unsafe {
            shadow_post_norm_outputs[rank].as_mut_slice_of::<u8>()[..h_bytes]
                .copy_from_slice(&input_bytes);
        }
    }

    let mut shadow_residual_outputs = Vec::new();
    if residual_replicas.is_some() {
        qwen_prepare_next_decode_layer_rank_h_buffers(
            dev,
            peer_workspaces,
            &mut shadow_residual_outputs,
            tp_world,
            h_bytes,
            layer_idx,
            "loop equivalence residual shadow",
        )?;
        let source_residuals = residual_replicas.as_deref_mut().ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner layer{layer_idx} loop equivalence residual clone expected source residual buffers"
            )
        })?;
        for rank in 0..tp_world {
            let residual_bytes =
                unsafe { source_residuals[rank].as_mut_slice_of::<u8>()[..h_bytes].to_vec() };
            unsafe {
                shadow_residual_outputs[rank].as_mut_slice_of::<u8>()[..h_bytes]
                    .copy_from_slice(&residual_bytes);
            }
        }
    }
    let mut shadow_next_input_norm_outputs = Vec::new();
    if next_input_norm_outputs_required {
        qwen_prepare_next_decode_layer_rank_h_buffers(
            dev,
            peer_workspaces,
            &mut shadow_next_input_norm_outputs,
            tp_world,
            h_bytes,
            layer_idx + 1,
            "loop equivalence next input norm shadow",
        )?;
    }

    let shadow_residual_arg = if !shadow_residual_outputs.is_empty() {
        Some(shadow_residual_outputs.as_mut_slice())
    } else {
        None
    };
    let shadow_next_norm_arg = if next_input_norm_outputs_required {
        Some(shadow_next_input_norm_outputs.as_mut_slice())
    } else {
        None
    };

    let _shadow_result = run_qwen_next_decode_mlp_allreduce_with_residual_contract(
        dev,
        peer_workspaces,
        mlp,
        peer_mlp,
        nodes,
        shadow_post_norm_outputs.as_mut_slice(),
        shadow_residual_arg,
        next_input_norm,
        shadow_next_norm_arg,
        h_size,
        h_bytes,
        poison_h,
        residual_contract,
        Some(layer_idx),
        Some(dag_scheduler),
        gate_w,
        up_w,
        down_w,
        gate_out,
        up_out,
        gate_f16,
        up_f16,
        swiglu_out,
    )
    .map_err(|err| {
        anyhow::anyhow!(
            "resident layer runner layer{layer_idx} unrolled MLP shadow dispatch failed: {err:#}"
        )
    })?;

    let residual_outputs = if !shadow_residual_outputs.is_empty() {
        Some(
            shadow_residual_outputs
                .iter_mut()
                .map(|buffer| unsafe { buffer.as_mut_slice_of::<u8>()[..h_bytes].to_vec() })
                .collect::<Vec<_>>(),
        )
    } else {
        None
    };
    let next_input_norm_outputs = if next_input_norm_outputs_required {
        Some(
            shadow_next_input_norm_outputs
                .iter_mut()
                .map(|buffer| unsafe { buffer.as_mut_slice_of::<u8>()[..h_bytes].to_vec() })
                .collect::<Vec<_>>(),
        )
    } else {
        None
    };

    Ok(QwenResidentLayerRunnerMlpShadowSnapshot {
        residual_outputs,
        next_input_norm_outputs,
    })
}

fn qwen_resident_layer_runner_compare_shadow_h_buffers(
    layer_idx: u32,
    label: &str,
    got_outputs: &mut [mcore::DeviceBuffer],
    expected_outputs: &[Vec<u8>],
    h_bytes: usize,
) -> Result<usize> {
    if got_outputs.len() != expected_outputs.len() {
        anyhow::bail!(
            "resident layer runner layer{layer_idx} {label} shadow rank count mismatch: got={} expected={}",
            got_outputs.len(),
            expected_outputs.len()
        );
    }
    let mut mismatch_bytes = 0usize;
    let mut first_mismatch_rank = 0usize;
    let mut first_mismatch_byte = 0usize;
    let mut first_got = 0u8;
    let mut first_expected = 0u8;
    for rank in 0..got_outputs.len() {
        if expected_outputs[rank].len() != h_bytes {
            anyhow::bail!(
                "resident layer runner layer{layer_idx} {label} shadow expected rank{rank} bytes {} != expected H bytes {}",
                expected_outputs[rank].len(),
                h_bytes
            );
        }
        let got = unsafe { got_outputs[rank].as_mut_slice_of::<u8>()[..h_bytes].to_vec() };
        for (byte_idx, (&got_byte, &expected_byte)) in
            got.iter().zip(expected_outputs[rank].iter()).enumerate()
        {
            if got_byte != expected_byte {
                if mismatch_bytes == 0 {
                    first_mismatch_rank = rank;
                    first_mismatch_byte = byte_idx;
                    first_got = got_byte;
                    first_expected = expected_byte;
                }
                mismatch_bytes += 1;
            }
        }
    }
    if mismatch_bytes != 0 {
        anyhow::bail!(
            "resident layer runner layer{layer_idx} {label} loop-vs-unrolled shadow mismatch: bytes={} first_rank={} first_byte={} got=0x{:02x} expected=0x{:02x}",
            mismatch_bytes,
            first_mismatch_rank,
            first_mismatch_byte,
            first_got,
            first_expected
        );
    }
    Ok(mismatch_bytes)
}

fn qwen_resident_layer_runner_validate_mlp_shadow_equivalence(
    layer_idx: u32,
    snapshot: &QwenResidentLayerRunnerMlpShadowSnapshot,
    residual_replicas: Option<&mut [mcore::DeviceBuffer]>,
    next_input_norm_outputs: Option<&mut [mcore::DeviceBuffer]>,
    h_bytes: usize,
) -> Result<()> {
    let mut residual_checked = false;
    let mut residual_ranks = 0usize;
    let mut residual_mismatch_bytes = 0usize;
    if let Some(expected_residual) = &snapshot.residual_outputs {
        let got_residual = residual_replicas.ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner layer{layer_idx} loop-vs-unrolled residual shadow expected real residual buffers"
            )
        })?;
        residual_mismatch_bytes = qwen_resident_layer_runner_compare_shadow_h_buffers(
            layer_idx,
            "residual",
            got_residual,
            expected_residual.as_slice(),
            h_bytes,
        )?;
        residual_checked = true;
        residual_ranks = expected_residual.len();
    }

    let mut next_input_norm_checked = false;
    let mut next_input_norm_ranks = 0usize;
    let mut next_input_norm_mismatch_bytes = 0usize;
    if let Some(expected_norm) = &snapshot.next_input_norm_outputs {
        let got_norm = next_input_norm_outputs.ok_or_else(|| {
            anyhow::anyhow!(
                "resident layer runner layer{layer_idx} loop-vs-unrolled next input norm shadow expected real norm buffers"
            )
        })?;
        next_input_norm_mismatch_bytes = qwen_resident_layer_runner_compare_shadow_h_buffers(
            layer_idx,
            "next_input_norm",
            got_norm,
            expected_norm.as_slice(),
            h_bytes,
        )?;
        next_input_norm_checked = true;
        next_input_norm_ranks = expected_norm.len();
    }

    println!("  resident_layer_runner_loop_executor_shadow_equivalence_stage:");
    println!("    selected_boundary: next_decode_layer{layer_idx}_mlp");
    println!("    baseline: unrolled_direct_mlp_descriptor_replay");
    println!("    dispatched: host_loop_executor_dispatcher");
    println!("    compare: byte_exact_rank_h_buffers");
    println!("    h_bytes_per_rank: {h_bytes}");
    println!("    residual_checked: {residual_checked}");
    println!("    residual_ranks: {residual_ranks}");
    println!("    residual_mismatch_bytes: {residual_mismatch_bytes}");
    println!("    next_input_norm_checked: {next_input_norm_checked}");
    println!("    next_input_norm_ranks: {next_input_norm_ranks}");
    println!("    next_input_norm_mismatch_bytes: {next_input_norm_mismatch_bytes}");
    println!("    bit_exact: true");
    println!("    hip_graph_capture_started: false");
    println!(
        "    next_required: wire_mlp_dispatcher_to_authoritative_plan_cursor_or_qwen35_moe_router"
    );
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn qwen_resident_layer_runner_dispatch_next_decode_mlp(
    runner_entries: &[QwenResidentLayerRunnerEntry],
    layer_idx: u32,
    dag_scheduler: QwenResidentLayerRunnerDagSchedulerContext<'_>,
    dev: &mut mcore::GpuDevice,
    peer_workspaces: &mut [QwenPeerMlpWorkspace],
    mlp: &QwenMlpStagePlan,
    peer_mlp: &QwenTpMlpPeerStagePlan,
    nodes: &[u32],
    post_norm_outputs: &mut [mcore::DeviceBuffer],
    mut residual_replicas: Option<&mut [mcore::DeviceBuffer]>,
    next_input_norm: Option<&QwenNextInputNormStagePlan>,
    mut next_input_norm_outputs: Option<&mut [mcore::DeviceBuffer]>,
    h_size: u32,
    h_bytes: usize,
    poison_h: u16,
) -> Result<(
    QwenNextDecodeLayer0MlpAllReduceStage,
    Option<QwenNextDecodeLayer0MlpResidualNormAllRankStage>,
)> {
    let entry = runner_entries
        .iter()
        .find(|entry| entry.layer_idx == layer_idx)
        .ok_or_else(|| {
            anyhow::anyhow!("resident layer runner descriptor for layer {layer_idx} is missing")
        })?;

    qwen_resident_layer_runner_loop_executor_dispatch_mlp_result(
        entry,
        dag_scheduler,
        || -> Result<_> {
            let contract = qwen_resident_layer_runner_mlp_contract_preflight(
                entry,
                mlp,
                peer_mlp,
                nodes,
                post_norm_outputs,
                residual_replicas.as_deref_mut(),
                next_input_norm,
                next_input_norm_outputs.as_deref_mut(),
                h_size,
                h_bytes,
            )?;
            println!("  resident_layer_runner_generic_mlp_contract_preflight_stage:");
            println!("    layer_idx: {layer_idx}");
            println!(
                "    residual_contract_source: {}",
                entry.residual_contract.source_label()
            );
            println!(
                "    residual_storage: {}",
                entry.residual_contract.storage.label()
            );
            println!("    ranks_checked: {}", contract.ranks_checked);
            println!("    buffers_checked: {}", contract.buffers_checked);
            println!("    expected_h_bytes: {}", contract.expected_h_bytes);
            println!(
                "    min_alignment_bytes: {}",
                QWEN_RESIDENT_LAYER_RUNNER_DISPATCH_MIN_ALIGNMENT_BYTES
            );
            println!("    buffer_contract_valid: true");
            println!("    guard_placement: before_mlp_gpu_allocation_and_dispatch");
            let mut gate_w = dev.alloc_device(mlp.gate_weight_bytes.len())?;
            let mut up_w = dev.alloc_device(mlp.up_weight_bytes.len())?;
            let mut down_w = dev.alloc_device(mlp.down_weight_bytes.len())?;
            let mut gate_out = dev.alloc(mlp.local_intermediate as usize * 4)?;
            let mut up_out = dev.alloc(mlp.local_intermediate as usize * 4)?;
            let mut gate_f16 = dev.alloc(mlp.local_intermediate as usize * 2)?;
            let mut up_f16 = dev.alloc(mlp.local_intermediate as usize * 2)?;
            let mut swiglu_out = dev.alloc(mlp.down_cols as usize * 2)?;

            let expected_peer_ranks = nodes.len().saturating_sub(1);
            if peer_mlp.peer_gate_weight_bytes.len() != expected_peer_ranks
                || peer_mlp.peer_up_weight_bytes.len() != expected_peer_ranks
                || peer_mlp.peer_down_weight_bytes.len() != expected_peer_ranks
            {
                anyhow::bail!(
                "resident layer runner generic MLP layer {layer_idx} peer weight shards gate/up/down {}/{}/{} do not match expected peer ranks {}",
                peer_mlp.peer_gate_weight_bytes.len(),
                peer_mlp.peer_up_weight_bytes.len(),
                peer_mlp.peer_down_weight_bytes.len(),
                expected_peer_ranks
            );
            }
            let gate_weight_expected_bytes =
                mlp.local_intermediate as usize * h_size as usize * std::mem::size_of::<u16>();
            let up_weight_expected_bytes = gate_weight_expected_bytes;
            let down_weight_expected_bytes =
                h_size as usize * mlp.down_cols as usize * std::mem::size_of::<u16>();
            let validate_weight_finite =
                std::env::var_os("MAINARCH_QWEN_GENERIC_MLP_VALIDATE_WEIGHTS").is_some();
            let mut input_max_abs = 0.0f32;
            let mut input_max_rank = 0usize;
            let mut input_max_dim = 0usize;
            let mut input_elements = 0usize;
            for rank in 0..post_norm_outputs.len() {
                let input_slice = unsafe { post_norm_outputs[rank].as_mut_slice_of::<u8>() };
                if input_slice.len() < h_bytes {
                    anyhow::bail!(
                    "resident layer runner generic MLP layer {layer_idx} post_attention_norm_input rank{rank} buffer bytes {} < expected {}",
                    input_slice.len(),
                    h_bytes
                );
                }
                let input_bytes = input_slice[..h_bytes].to_vec();
                let rank_label = format!("rank{rank}");
                let stats = qwen_resident_layer_runner_validate_f16_finite_bytes(
                    layer_idx,
                    "post_attention_norm_input",
                    &rank_label,
                    &input_bytes,
                    h_bytes,
                )?;
                input_elements = stats.elements;
                if stats.max_abs > input_max_abs {
                    input_max_abs = stats.max_abs;
                    input_max_rank = rank;
                    input_max_dim = stats.max_dim;
                }
            }
            let mut weight_max_abs = 0.0f32;
            let mut weight_max_rank_label = String::from("rank0");
            let mut weight_max_tensor = "gate";
            let mut weight_max_dim = 0usize;
            for (rank_label, tensor, bytes, expected_bytes) in [
                (
                    "rank0",
                    "gate",
                    mlp.gate_weight_bytes.as_slice(),
                    gate_weight_expected_bytes,
                ),
                (
                    "rank0",
                    "up",
                    mlp.up_weight_bytes.as_slice(),
                    up_weight_expected_bytes,
                ),
                (
                    "rank0",
                    "down",
                    mlp.down_weight_bytes.as_slice(),
                    down_weight_expected_bytes,
                ),
            ] {
                if validate_weight_finite {
                    let stats = qwen_resident_layer_runner_validate_f16_finite_bytes(
                        layer_idx,
                        tensor,
                        rank_label,
                        bytes,
                        expected_bytes,
                    )?;
                    if stats.max_abs > weight_max_abs {
                        weight_max_abs = stats.max_abs;
                        weight_max_rank_label = rank_label.to_string();
                        weight_max_tensor = tensor;
                        weight_max_dim = stats.max_dim;
                    }
                } else {
                    qwen_resident_layer_runner_validate_f16_byte_len(
                        layer_idx,
                        tensor,
                        rank_label,
                        bytes,
                        expected_bytes,
                    )?;
                }
            }
            for peer_idx in 0..expected_peer_ranks {
                let rank = peer_idx + 1;
                let rank_label = format!("rank{rank}");
                for (tensor, bytes, expected_bytes) in [
                    (
                        "gate",
                        peer_mlp.peer_gate_weight_bytes[peer_idx].as_slice(),
                        gate_weight_expected_bytes,
                    ),
                    (
                        "up",
                        peer_mlp.peer_up_weight_bytes[peer_idx].as_slice(),
                        up_weight_expected_bytes,
                    ),
                    (
                        "down",
                        peer_mlp.peer_down_weight_bytes[peer_idx].as_slice(),
                        down_weight_expected_bytes,
                    ),
                ] {
                    if validate_weight_finite {
                        let stats = qwen_resident_layer_runner_validate_f16_finite_bytes(
                            layer_idx,
                            tensor,
                            &rank_label,
                            bytes,
                            expected_bytes,
                        )?;
                        if stats.max_abs > weight_max_abs {
                            weight_max_abs = stats.max_abs;
                            weight_max_rank_label = rank_label.clone();
                            weight_max_tensor = tensor;
                            weight_max_dim = stats.max_dim;
                        }
                    } else {
                        qwen_resident_layer_runner_validate_f16_byte_len(
                            layer_idx,
                            tensor,
                            &rank_label,
                            bytes,
                            expected_bytes,
                        )?;
                    }
                }
            }
            println!("  resident_layer_runner_generic_mlp_finite_guard_stage:");
            println!("    layer_idx: {layer_idx}");
            println!("    ranks_checked: {}", post_norm_outputs.len());
            println!("    expected_peer_ranks: {expected_peer_ranks}");
            println!("    input_elements_per_rank: {input_elements}");
            println!("    input_finite: true");
            println!(
                "    input_max_abs: {:.6} at rank {} dim {}",
                input_max_abs, input_max_rank, input_max_dim
            );
            println!("    weight_shape_valid: true");
            println!("    weights_finite_checked: {validate_weight_finite}");
            println!(
                "    weight_finite_validation_env: MAINARCH_QWEN_GENERIC_MLP_VALIDATE_WEIGHTS"
            );
            if validate_weight_finite {
                println!("    weights_finite: true");
                println!(
                    "    weight_max_abs: {:.6} tensor {} {} dim {}",
                    weight_max_abs, weight_max_tensor, weight_max_rank_label, weight_max_dim
                );
            } else {
                println!("    weights_finite: unchecked_env_gated");
            }
            println!("    guard_placement: before_rank0_gate_proj_gemv");

            unsafe {
                gate_w.as_mut_slice_of::<u8>()[..mlp.gate_weight_bytes.len()]
                    .copy_from_slice(&mlp.gate_weight_bytes);
                up_w.as_mut_slice_of::<u8>()[..mlp.up_weight_bytes.len()]
                    .copy_from_slice(&mlp.up_weight_bytes);
                down_w.as_mut_slice_of::<u8>()[..mlp.down_weight_bytes.len()]
                    .copy_from_slice(&mlp.down_weight_bytes);
            }

            let loop_dispatch_shadow_snapshot =
                if qwen_resident_layer_runner_loop_executor_mlp_authoritative_cursor(
                    dag_scheduler,
                    layer_idx,
                )?
                .is_some()
                {
                    Some(qwen_resident_layer_runner_run_mlp_unrolled_shadow_snapshot(
                        layer_idx,
                        dev,
                        peer_workspaces,
                        mlp,
                        peer_mlp,
                        nodes,
                        post_norm_outputs,
                        residual_replicas.as_deref_mut(),
                        next_input_norm,
                        next_input_norm_outputs.is_some(),
                        h_size,
                        h_bytes,
                        poison_h,
                        entry.residual_contract,
                        dag_scheduler,
                        &mut gate_w,
                        &mut up_w,
                        &mut down_w,
                        &mut gate_out,
                        &mut up_out,
                        &mut gate_f16,
                        &mut up_f16,
                        &mut swiglu_out,
                    )?)
                } else {
                    None
                };

            let result = run_qwen_next_decode_mlp_allreduce_with_residual_contract(
                dev,
                peer_workspaces,
                mlp,
                peer_mlp,
                nodes,
                post_norm_outputs,
                residual_replicas.as_deref_mut(),
                next_input_norm,
                next_input_norm_outputs.as_deref_mut(),
                h_size,
                h_bytes,
                poison_h,
                entry.residual_contract,
                Some(layer_idx),
                Some(dag_scheduler),
                &mut gate_w,
                &mut up_w,
                &mut down_w,
                &mut gate_out,
                &mut up_out,
                &mut gate_f16,
                &mut up_f16,
                &mut swiglu_out,
            )
            .map_err(|err| {
                anyhow::anyhow!(
                "resident layer runner generic MLP dispatch for layer {layer_idx} failed: {err:#}"
            )
            })?;

            if let Some(snapshot) = &loop_dispatch_shadow_snapshot {
                qwen_resident_layer_runner_validate_mlp_shadow_equivalence(
                    layer_idx,
                    snapshot,
                    residual_replicas.as_deref_mut(),
                    next_input_norm_outputs.as_deref_mut(),
                    h_bytes,
                )?;
            }

            if result.1.is_some() {
                let residual_bf16 = entry.uses_bf16_residual();
                let residual_replicas = residual_replicas.as_deref_mut().ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner generic MLP layer {layer_idx} residual norm stage ran without residual replica buffers"
                )
            })?;
                let next_input_norm_outputs = next_input_norm_outputs.as_deref_mut().ok_or_else(|| {
                anyhow::anyhow!(
                    "resident layer runner generic MLP layer {layer_idx} residual norm stage ran without next input norm output buffers"
                )
            })?;
                let mut residual_max_abs = 0.0f32;
                let mut residual_max_rank = 0usize;
                let mut residual_max_dim = 0usize;
                let mut residual_elements = 0usize;
                for rank in 0..residual_replicas.len() {
                    let residual_slice = unsafe { residual_replicas[rank].as_mut_slice_of::<u8>() };
                    if residual_slice.len() < h_bytes {
                        anyhow::bail!(
                        "resident layer runner generic MLP layer {layer_idx} mlp_residual_stream_after_residual_norm rank{rank} buffer bytes {} < expected {}",
                        residual_slice.len(),
                        h_bytes
                    );
                    }
                    let residual_bytes = residual_slice[..h_bytes].to_vec();
                    let rank_label = format!("rank{rank}");
                    let stats = if residual_bf16 {
                        qwen_resident_layer_runner_validate_bf16_finite_bytes_for_context(
                            "generic MLP",
                            layer_idx,
                            "mlp_residual_stream_after_residual_norm",
                            &rank_label,
                            &residual_bytes,
                            h_bytes,
                        )?
                    } else {
                        qwen_resident_layer_runner_validate_f16_finite_bytes(
                            layer_idx,
                            "mlp_residual_stream_after_residual_norm",
                            &rank_label,
                            &residual_bytes,
                            h_bytes,
                        )?
                    };
                    residual_elements = stats.elements;
                    if stats.max_abs > residual_max_abs {
                        residual_max_abs = stats.max_abs;
                        residual_max_rank = rank;
                        residual_max_dim = stats.max_dim;
                    }
                }
                let mut norm_max_abs = 0.0f32;
                let mut norm_max_rank = 0usize;
                let mut norm_max_dim = 0usize;
                let mut norm_elements = 0usize;
                for rank in 0..next_input_norm_outputs.len() {
                    let norm_slice =
                        unsafe { next_input_norm_outputs[rank].as_mut_slice_of::<u8>() };
                    if norm_slice.len() < h_bytes {
                        anyhow::bail!(
                        "resident layer runner generic MLP layer {layer_idx} next_input_norm_output_after_residual_norm rank{rank} buffer bytes {} < expected {}",
                        norm_slice.len(),
                        h_bytes
                    );
                    }
                    let norm_bytes = norm_slice[..h_bytes].to_vec();
                    let rank_label = format!("rank{rank}");
                    let stats = qwen_resident_layer_runner_validate_f16_finite_bytes(
                        layer_idx,
                        "next_input_norm_output_after_residual_norm",
                        &rank_label,
                        &norm_bytes,
                        h_bytes,
                    )?;
                    norm_elements = stats.elements;
                    if stats.max_abs > norm_max_abs {
                        norm_max_abs = stats.max_abs;
                        norm_max_rank = rank;
                        norm_max_dim = stats.max_dim;
                    }
                }
                println!("  resident_layer_runner_generic_mlp_residual_finite_guard_stage:");
                println!("    layer_idx: {layer_idx}");
                println!(
                    "    residual_storage: {}",
                    entry.residual_contract.storage.label()
                );
                println!(
                    "    residual_contract_source: {}",
                    entry.residual_contract.source_label()
                );
                println!("    ranks_checked: {}", residual_replicas.len());
                println!("    residual_elements_per_rank: {residual_elements}");
                println!("    residual_finite: true");
                println!(
                    "    residual_max_abs: {:.6} at rank {} dim {}",
                    residual_max_abs, residual_max_rank, residual_max_dim
                );
                println!("    next_input_norm_elements_per_rank: {norm_elements}");
                println!("    next_input_norm_finite: true");
                println!(
                    "    next_input_norm_max_abs: {:.6} at rank {} dim {}",
                    norm_max_abs, norm_max_rank, norm_max_dim
                );
                println!("    guard_placement: after_mlp_residual_norm_before_next_attention");
            }

            Ok(result)
        },
    )
}

fn qwen_resident_layer_runner_launch_full_layer<F>(
    entry: &QwenResidentLayerRunnerEntry,
    execute: F,
) -> Result<()>
where
    F: FnOnce() -> Result<()>,
{
    qwen_resident_layer_runner_validate_entry_contract(entry, "full-layer launch")?;
    if !entry.full_layer_launch_eligible() {
        anyhow::bail!(
            "resident layer runner descriptor for layer {} is not full-layer launch eligible: {:?}",
            entry.layer_idx,
            entry
        );
    }
    let ops = entry.resident_operation_trace()?;
    if ops.len() != 11 {
        anyhow::bail!(
            "resident layer runner descriptor for layer {} expected 11 full-layer ops, got {}: {:?}",
            entry.layer_idx,
            ops.len(),
            ops
        );
    }

    execute()
}

