struct QwenPeerMlpWorkspace {
    dev: mcore::GpuDevice,
    input: mcore::DeviceBuffer,
    gate_w: mcore::DeviceBuffer,
    up_w: mcore::DeviceBuffer,
    down_w: mcore::DeviceBuffer,
    gate_out: mcore::DeviceBuffer,
    up_out: mcore::DeviceBuffer,
    gate_f16: mcore::DeviceBuffer,
    up_f16: mcore::DeviceBuffer,
    swiglu_out: mcore::DeviceBuffer,
    gate_weight_bytes: Vec<u8>,
    up_weight_bytes: Vec<u8>,
    down_weight_bytes: Vec<u8>,
}

impl QwenPeerMlpWorkspace {
    fn new(
        dev: mcore::GpuDevice,
        mlp: &QwenMlpStagePlan,
        input_bytes_len: usize,
        gate_weight: &[u8],
        up_weight: &[u8],
        down_weight: &[u8],
    ) -> Result<Self> {
        let mut input = dev.alloc_device(input_bytes_len)?;
        let mut gate_w = dev.alloc_device(gate_weight.len())?;
        let mut up_w = dev.alloc_device(up_weight.len())?;
        let mut down_w = dev.alloc_device(down_weight.len())?;
        let mut gate_out = dev.alloc(mlp.intermediate_f32_bytes())?;
        let mut up_out = dev.alloc(mlp.intermediate_f32_bytes())?;
        let mut gate_f16 = dev.alloc(mlp.intermediate_f16_bytes())?;
        let mut up_f16 = dev.alloc(mlp.intermediate_f16_bytes())?;
        let mut swiglu_out = dev.alloc(mlp.down_input_f16_bytes())?;
        unsafe {
            input.as_mut_slice_of::<u8>()[..input_bytes_len].fill(0);
            gate_w.as_mut_slice_of::<u8>()[..gate_weight.len()].copy_from_slice(gate_weight);
            up_w.as_mut_slice_of::<u8>()[..up_weight.len()].copy_from_slice(up_weight);
            down_w.as_mut_slice_of::<u8>()[..down_weight.len()].copy_from_slice(down_weight);
            gate_out.as_mut_slice_of::<f32>()[..mlp.local_intermediate as usize].fill(f32::NAN);
            up_out.as_mut_slice_of::<f32>()[..mlp.local_intermediate as usize].fill(f32::NAN);
            gate_f16.as_mut_slice_of::<u16>()[..mlp.local_intermediate as usize].fill(0);
            up_f16.as_mut_slice_of::<u16>()[..mlp.local_intermediate as usize].fill(0);
            swiglu_out.as_mut_slice_of::<u16>()[..mlp.down_cols as usize].fill(0);
        }
        Ok(Self {
            dev,
            input,
            gate_w,
            up_w,
            down_w,
            gate_out,
            up_out,
            gate_f16,
            up_f16,
            swiglu_out,
            gate_weight_bytes: gate_weight.to_vec(),
            up_weight_bytes: up_weight.to_vec(),
            down_weight_bytes: down_weight.to_vec(),
        })
    }
}

