impl QwenTpOProjPeerStagePlan {
    fn real_weight_slices(&self) -> usize {
        1 + self.peer_weight_bytes.len()
    }
}

impl QwenTpMlpPeerStagePlan {
    fn real_weight_slices(&self) -> usize {
        1 + self.peer_gate_weight_bytes.len()
    }
}

impl QwenLmHeadStagePlan {
    fn logits_bytes(&self) -> usize {
        self.vocab_rows as usize * std::mem::size_of::<f32>()
    }
}

impl QwenQkNormRopeStagePlan {
    fn q_elems(&self) -> usize {
        self.q_heads as usize * self.head_dim as usize
    }

    fn k_elems(&self) -> usize {
        self.k_heads as usize * self.head_dim as usize
    }

    fn q_bytes(&self) -> usize {
        self.q_elems() * 2
    }

    fn k_bytes(&self) -> usize {
        self.k_elems() * 2
    }
}

impl QwenFp4KvCacheStagePlan {
    fn cache_bytes(&self) -> usize {
        self.kv_heads as usize * self.physical_blocks as usize * self.block_size as usize * 64
    }

    fn scale_bytes(&self) -> usize {
        self.kv_heads as usize * self.physical_blocks as usize * self.block_size as usize * 4
    }
}

impl QwenFp4SingleRowAttentionStagePlan {
    fn q_bytes(&self) -> usize {
        self.kernel_q_heads as usize * self.head_dim as usize * 2
    }

    fn partial_stride(&self) -> usize {
        self.head_dim as usize + 2
    }

    fn partial_f32s(&self) -> usize {
        self.kernel_q_heads as usize * self.partial_stride()
    }

    fn partial_bytes(&self) -> usize {
        self.partial_f32s() * 4
    }
}

impl QwenOProjStagePlan {
    fn input_bytes(&self) -> usize {
        self.cols as usize * 2
    }

    fn output_bytes(&self) -> usize {
        self.rows as usize * 4
    }
}

impl QwenMlpStagePlan {
    fn intermediate_f16_bytes(&self) -> usize {
        self.local_intermediate as usize * 2
    }

    fn intermediate_f32_bytes(&self) -> usize {
        self.local_intermediate as usize * 4
    }

    fn down_input_f16_bytes(&self) -> usize {
        self.down_cols as usize * 2
    }

    fn output_f32_bytes(&self) -> usize {
        self.down_weight_bytes.len() / 2 / self.down_cols as usize * 4
    }
}

fn build_qwen_input_norm_stage_plan(
    input_norm_shard: Option<&Path>,
    h_size: u32,
) -> Result<QwenInputNormStagePlan> {
    match input_norm_shard {
        Some(path) => build_qwen_rank0_input_norm_stage_plan(path, h_size),
        None => {
            let one = mcore::gemm::f32_to_f16(1.0).to_le_bytes();
            let mut weight_bytes = vec![0u8; h_size as usize * 2];
            for slot in weight_bytes.chunks_exact_mut(2) {
                slot.copy_from_slice(&one);
            }
            Ok(QwenInputNormStagePlan {
                label: "synthetic_unit_rmsnorm_weight".to_string(),
                weight_bytes,
            })
        }
    }
}

fn build_qwen_rank0_input_norm_stage_plan(
    path: &Path,
    h_size: u32,
) -> Result<QwenInputNormStagePlan> {
    let tensor = "model.layers.0.input_layernorm.weight";
    let shard = mcore::weights::SafetensorsShard::open(path)?;
    let meta = shard.tensor(tensor)?.clone();
    if meta.dtype != "BF16" {
        anyhow::bail!(
            "{tensor} in {} has dtype {}, expected BF16",
            path.display(),
            meta.dtype
        );
    }
    if meta.shape != [h_size as u64] {
        anyhow::bail!(
            "{tensor} in {} has shape {:?}, expected [{h_size}]",
            path.display(),
            meta.shape
        );
    }
    let weight_bytes = shard.read_tensor_bytes(tensor)?;
    Ok(QwenInputNormStagePlan {
        label: format!("rank0:{tensor}:{}:{h_size}:BF16", path.display()),
        weight_bytes,
    })
}

fn build_qwen_next_input_norm_stage_plan(
    input_norm_shard: Option<&Path>,
    mlp_plan: Option<&QwenMlpStagePlan>,
    runtime_config: Option<&QwenRuntimeConfig>,
    h_size: u32,
) -> Result<Option<QwenNextInputNormStagePlan>> {
    build_qwen_next_input_norm_stage_plan_for_layer(
        input_norm_shard,
        mlp_plan,
        runtime_config,
        h_size,
        1,
    )
}

fn build_qwen_next_input_norm_stage_plan_for_layer(
    input_norm_shard: Option<&Path>,
    mlp_plan: Option<&QwenMlpStagePlan>,
    runtime_config: Option<&QwenRuntimeConfig>,
    h_size: u32,
    layer_idx: u32,
) -> Result<Option<QwenNextInputNormStagePlan>> {
    if mlp_plan.is_none() {
        return Ok(None);
    }
    let Some(path) = input_norm_shard else {
        return Ok(None);
    };
    let config = runtime_config.ok_or_else(|| {
        anyhow::anyhow!(
            "next-layer input RMSNorm handoff requires a sibling config.json beside tokenizer.json"
        )
    })?;
    if config.hidden_size != h_size {
        anyhow::bail!(
            "Qwen config hidden_size {} does not match staged hidden size {}",
            config.hidden_size,
            h_size
        );
    }
    build_qwen_rank0_next_input_norm_stage_plan_for_layer(
        path,
        h_size,
        config.rms_norm_eps,
        layer_idx,
    )
    .map(Some)
}

fn build_qwen_rank0_next_input_norm_stage_plan_for_layer(
    path: &Path,
    h_size: u32,
    eps: f32,
    layer_idx: u32,
) -> Result<QwenNextInputNormStagePlan> {
    let tensor = format!("model.layers.{layer_idx}.input_layernorm.weight");
    let shard = mcore::weights::SafetensorsShard::open(path)?;
    let meta = shard.tensor(&tensor)?.clone();
    if meta.dtype != "BF16" {
        anyhow::bail!(
            "{tensor} in {} has dtype {}, expected BF16",
            path.display(),
            meta.dtype
        );
    }
    if meta.shape != [h_size as u64] {
        anyhow::bail!(
            "{tensor} in {} has shape {:?}, expected [{h_size}]",
            path.display(),
            meta.shape
        );
    }
    let weight_bytes = shard.read_tensor_bytes(&tensor)?;
    Ok(QwenNextInputNormStagePlan {
        label: format!("rank0:{tensor}:{}:{h_size}:BF16", path.display()),
        eps,
        weight_bytes,
    })
}

fn build_qwen_q_proj_stage_plan(
    q_proj_shard: Option<&Path>,
    h_size: u32,
) -> Result<Option<QwenQProjStagePlan>> {
    match q_proj_shard {
        Some(path) => Ok(Some(build_qwen_rank0_q_proj_stage_plan(path, h_size)?)),
        None => Ok(None),
    }
}

fn build_qwen_rank0_q_proj_stage_plan(path: &Path, h_size: u32) -> Result<QwenQProjStagePlan> {
    let tensor = "model.layers.0.self_attn.q_proj.weight";
    let shard = mcore::weights::SafetensorsShard::open(path)?;
    let meta = shard.tensor(tensor)?.clone();
    if meta.dtype != "BF16" {
        anyhow::bail!(
            "{tensor} in {} has dtype {}, expected BF16",
            path.display(),
            meta.dtype
        );
    }
    if meta.shape.len() != 2 || meta.shape[1] != h_size as u64 {
        anyhow::bail!(
            "{tensor} in {} has shape {:?}, expected [local_q_rows, {h_size}]",
            path.display(),
            meta.shape
        );
    }
    let rows = u32::try_from(meta.shape[0])
        .map_err(|_| anyhow::anyhow!("{tensor} row count exceeds u32"))?;
    if rows == 0 || !rows.is_multiple_of(4) {
        anyhow::bail!("{tensor} row count {rows} must be non-zero and divisible by 4 for gemv_f16");
    }
    if !h_size.is_multiple_of(512) {
        anyhow::bail!("{tensor} K={h_size} must be divisible by 512 for gemv_f16");
    }
    let weight_bytes = shard.read_tensor_bytes(tensor)?;
    Ok(QwenQProjStagePlan {
        label: format!("rank0:{tensor}:{}:{rows}x{h_size}:BF16", path.display()),
        rows,
        weight_bytes,
    })
}

