fn build_qwen_post_attn_norm_stage_plan_for_layer(
    post_attn_norm_shard: Option<&Path>,
    o_proj_plan: Option<&QwenOProjStagePlan>,
    runtime_config: Option<&QwenRuntimeConfig>,
    h_size: u32,
    layer_idx: u32,
) -> Result<Option<QwenPostAttnNormStagePlan>> {
    let Some(path) = post_attn_norm_shard else {
        return Ok(None);
    };
    if o_proj_plan.is_none() {
        return Ok(None);
    }
    let config = runtime_config.ok_or_else(|| {
        anyhow::anyhow!(
            "--post-attn-norm-shard requires a sibling config.json beside tokenizer.json"
        )
    })?;
    if config.hidden_size != h_size {
        anyhow::bail!(
            "Qwen config hidden_size {} does not match staged hidden size {}",
            config.hidden_size,
            h_size
        );
    }
    build_qwen_rank0_post_attn_norm_stage_plan_for_layer(
        path,
        layer_idx,
        h_size,
        config.rms_norm_eps,
    )
    .map(Some)
}

fn build_qwen_rank0_post_attn_norm_stage_plan_for_layer(
    path: &Path,
    layer_idx: u32,
    h_size: u32,
    eps: f32,
) -> Result<QwenPostAttnNormStagePlan> {
    let tensor = format!("model.layers.{layer_idx}.post_attention_layernorm.weight");
    let shard = mcore::weights::SafetensorsShard::open(path)?;
    let meta = shard.tensor(&tensor)?.clone();
    if meta.dtype != "BF16" {
        anyhow::bail!(
            "{tensor} in {} has dtype {}, expected BF16",
            path.display(),
            meta.dtype
        );
    }
    if meta.shape != [h_size as u64] {
        anyhow::bail!(
            "{tensor} in {} has shape {:?}, expected [{h_size}]",
            path.display(),
            meta.shape
        );
    }
    let weight_bytes = shard.read_tensor_bytes(&tensor)?;
    Ok(QwenPostAttnNormStagePlan {
        label: format!("rank0:{tensor}:{}:{h_size}:BF16", path.display()),
        eps,
        weight_bytes,
    })
}

