fn build_qwen_mlp_stage_plan_for_layer(
    mlp_shard: Option<&Path>,
    post_attn_norm_plan: Option<&QwenPostAttnNormStagePlan>,
    runtime_config: Option<&QwenRuntimeConfig>,
    h_size: u32,
    tp_world: usize,
    layer_idx: u32,
) -> Result<Option<QwenMlpStagePlan>> {
    let Some(path) = mlp_shard else {
        return Ok(None);
    };
    post_attn_norm_plan.ok_or_else(|| {
        anyhow::anyhow!(
            "--mlp-shard requires --post-attn-norm-shard because it consumes post-attention RMSNorm"
        )
    })?;
    let config = runtime_config.ok_or_else(|| {
        anyhow::anyhow!("--mlp-shard requires a sibling config.json beside tokenizer.json")
    })?;
    if config.hidden_size != h_size {
        anyhow::bail!(
            "Qwen config hidden_size {} does not match staged hidden size {}",
            config.hidden_size,
            h_size
        );
    }
    if tp_world == 0 {
        anyhow::bail!("--mlp-shard internal TP world must be non-zero");
    }
    let full_intermediate = config.intermediate_size.ok_or_else(|| {
        anyhow::anyhow!("Qwen config is missing intermediate_size required by --mlp-shard")
    })?;
    build_qwen_rank0_mlp_stage_plan(path, h_size, full_intermediate, tp_world, layer_idx).map(Some)
}

fn build_qwen_tp_mlp_peer_stage_plan(
    tp_index: Option<&Path>,
    mlp_plan: Option<&QwenMlpStagePlan>,
    h_size: u32,
    tp_world: usize,
) -> Result<Option<QwenTpMlpPeerStagePlan>> {
    build_qwen_tp_mlp_peer_stage_plan_for_layer(tp_index, mlp_plan, h_size, tp_world, 0)
}

fn build_qwen_tp_mlp_peer_stage_plan_for_layer(
    tp_index: Option<&Path>,
    mlp_plan: Option<&QwenMlpStagePlan>,
    h_size: u32,
    tp_world: usize,
    layer_idx: u32,
) -> Result<Option<QwenTpMlpPeerStagePlan>> {
    let Some(mlp) = mlp_plan else {
        return Ok(None);
    };
    let Some(path) = tp_index else {
        anyhow::bail!(
            "--mlp-shard requires --tp-o-proj-index so peer MLP shards can be materialized"
        );
    };
    if tp_world < 2 {
        anyhow::bail!("Qwen TP MLP peer plan requires at least two ranks");
    }
    let index = mcore::weights::SafetensorsIndex::open(path)?;
    let mut peer_gate_weight_bytes = Vec::with_capacity(tp_world - 1);
    let mut peer_up_weight_bytes = Vec::with_capacity(tp_world - 1);
    let mut peer_down_weight_bytes = Vec::with_capacity(tp_world - 1);
    let gate_tensor = format!("model.layers.{layer_idx}.mlp.gate_proj.weight");
    let up_tensor = format!("model.layers.{layer_idx}.mlp.up_proj.weight");
    let down_tensor = format!("model.layers.{layer_idx}.mlp.down_proj.weight");
    for rank in 1..tp_world {
        let gate = materialize_indexed_tp_slice(
            &index,
            &gate_tensor,
            0,
            rank,
            tp_world,
            &[u64::from(mlp.local_intermediate), u64::from(h_size)],
        )?;
        peer_gate_weight_bytes.push(bf16_bytes_to_f16_bytes(&gate)?);
        let up = materialize_indexed_tp_slice(
            &index,
            &up_tensor,
            0,
            rank,
            tp_world,
            &[u64::from(mlp.local_intermediate), u64::from(h_size)],
        )?;
        peer_up_weight_bytes.push(bf16_bytes_to_f16_bytes(&up)?);
        let down = materialize_indexed_tp_slice(
            &index,
            &down_tensor,
            1,
            rank,
            tp_world,
            &[u64::from(h_size), u64::from(mlp.local_intermediate)],
        )?;
        let down_f16 = bf16_bytes_to_f16_bytes(&down)?;
        peer_down_weight_bytes.push(pad_qwen_mlp_down_weight(
            &down_f16,
            h_size,
            mlp.local_intermediate,
            mlp.down_cols,
        )?);
    }
    Ok(Some(QwenTpMlpPeerStagePlan {
        label: format!(
            "hf-index:model.layers.{layer_idx}.mlp.gate/up/down_proj.weight:{}:TP{}:peer-ranks-1..{}",
            path.display(),
            tp_world,
            tp_world - 1
        ),
        tp_world,
        peer_gate_weight_bytes,
        peer_up_weight_bytes,
        peer_down_weight_bytes,
    }))
}

fn build_qwen_rank0_mlp_stage_plan(
    path: &Path,
    h_size: u32,
    full_intermediate: u32,
    tp_world: usize,
    layer_idx: u32,
) -> Result<QwenMlpStagePlan> {
    let shard = mcore::weights::SafetensorsShard::open(path)?;
    let gate_tensor = format!("model.layers.{layer_idx}.mlp.gate_proj.weight");
    let up_tensor = format!("model.layers.{layer_idx}.mlp.up_proj.weight");
    let down_tensor = format!("model.layers.{layer_idx}.mlp.down_proj.weight");
    let (gate_rows, gate_weight_bytes_bf16) =
        read_qwen_projection_weight(&shard, path, &gate_tensor, h_size, "local_intermediate")?;
    let gate_weight_bytes = bf16_bytes_to_f16_bytes(&gate_weight_bytes_bf16)?;
    let (up_rows, up_weight_bytes_bf16) =
        read_qwen_projection_weight(&shard, path, &up_tensor, h_size, "local_intermediate")?;
    let up_weight_bytes = bf16_bytes_to_f16_bytes(&up_weight_bytes_bf16)?;
    if gate_rows != up_rows {
        anyhow::bail!(
            "Qwen layer-0 MLP gate/up row mismatch in {}: gate_rows={} up_rows={}",
            path.display(),
            gate_rows,
            up_rows
        );
    }
    let down_meta = shard.tensor(&down_tensor)?.clone();
    if down_meta.dtype != "BF16" {
        anyhow::bail!(
            "{down_tensor} in {} has dtype {}, expected BF16",
            path.display(),
            down_meta.dtype
        );
    }
    if down_meta.shape != [h_size as u64, gate_rows as u64] {
        anyhow::bail!(
            "{down_tensor} in {} has shape {:?}, expected [{h_size}, {gate_rows}] for rank-local row shard",
            path.display(),
            down_meta.shape
        );
    }
    if gate_rows == 0 || !gate_rows.is_multiple_of(4) {
        anyhow::bail!(
            "Qwen layer-0 MLP local_intermediate {gate_rows} must be non-zero and divisible by 4 for gemv_f16 rows"
        );
    }
    if !h_size.is_multiple_of(512) {
        anyhow::bail!("Qwen layer-0 MLP gate/up K={h_size} must be divisible by 512 for gemv_f16");
    }
    let expected_full = u64::from(gate_rows)
        .checked_mul(tp_world as u64)
        .ok_or_else(|| anyhow::anyhow!("Qwen layer-0 MLP TP intermediate size overflows"))?;
    if expected_full != u64::from(full_intermediate) {
        anyhow::bail!(
            "Qwen layer-0 MLP local_intermediate {} across TP{} gives {}, config intermediate_size={}",
            gate_rows,
            tp_world,
            expected_full,
            full_intermediate
        );
    }
    let raw_down_weight_bytes = bf16_bytes_to_f16_bytes(&shard.read_tensor_bytes(&down_tensor)?)?;
    let down_cols = gate_rows.div_ceil(512) * 512;
    let down_weight_bytes =
        pad_qwen_mlp_down_weight(&raw_down_weight_bytes, h_size, gate_rows, down_cols)?;
    Ok(QwenMlpStagePlan {
        label: format!(
            "rank0:model.layers.{layer_idx}.mlp.gate/up/down_proj.weight:{}:{gate_rows}x{h_size}+{h_size}x{gate_rows}->padded{down_cols}:BF16-to-F16-TP{}",
            path.display(),
            tp_world
        ),
        local_intermediate: gate_rows,
        down_cols,
        gate_weight_bytes,
        up_weight_bytes,
        down_weight_bytes,
    })
}

fn pad_qwen_mlp_down_weight(
    raw_weight_bytes: &[u8],
    h_size: u32,
    local_intermediate: u32,
    down_cols: u32,
) -> Result<Vec<u8>> {
    let rows = h_size as usize;
    let src_cols = local_intermediate as usize;
    let dst_cols = down_cols as usize;
    if dst_cols < src_cols {
        anyhow::bail!(
            "MLP down-proj padded columns {} cannot be smaller than source columns {}",
            dst_cols,
            src_cols
        );
    }
    if raw_weight_bytes.len() != rows * src_cols * 2 {
        anyhow::bail!(
            "MLP down-proj raw weight length {} does not match expected {}",
            raw_weight_bytes.len(),
            rows * src_cols * 2
        );
    }
    if dst_cols == src_cols {
        return Ok(raw_weight_bytes.to_vec());
    }
    let mut padded = vec![0u8; rows * dst_cols * 2];
    for row in 0..rows {
        let src_begin = row * src_cols * 2;
        let src_end = src_begin + src_cols * 2;
        let dst_begin = row * dst_cols * 2;
        padded[dst_begin..dst_begin + src_cols * 2]
            .copy_from_slice(&raw_weight_bytes[src_begin..src_end]);
    }
    Ok(padded)
}

fn pad_qwen_mlp_down_input(
    raw_input_bytes: &[u8],
    local_intermediate: u32,
    down_cols: u32,
) -> Result<Vec<u8>> {
    let src_cols = local_intermediate as usize;
    let dst_cols = down_cols as usize;
    if dst_cols < src_cols {
        anyhow::bail!(
            "MLP down-proj padded input columns {} cannot be smaller than source columns {}",
            dst_cols,
            src_cols
        );
    }
    if raw_input_bytes.len() != src_cols * 2 {
        anyhow::bail!(
            "MLP down-proj raw input length {} does not match expected {}",
            raw_input_bytes.len(),
            src_cols * 2
        );
    }
    if dst_cols == src_cols {
        return Ok(raw_input_bytes.to_vec());
    }
    let mut padded = vec![0u8; dst_cols * 2];
    padded[..src_cols * 2].copy_from_slice(raw_input_bytes);
    Ok(padded)
}

fn build_qwen_rank0_o_proj_stage_plan_for_layer(
    path: &Path,
    h_size: u32,
    cols: u32,
    layer_idx: u32,
) -> Result<QwenOProjStagePlan> {
    let tensor = format!("model.layers.{layer_idx}.self_attn.o_proj.weight");
    let shard = mcore::weights::SafetensorsShard::open(path)?;
    let meta = shard.tensor(&tensor)?.clone();
    if meta.dtype != "BF16" {
        anyhow::bail!(
            "{tensor} in {} has dtype {}, expected BF16",
            path.display(),
            meta.dtype
        );
    }
    if meta.shape != [h_size as u64, cols as u64] {
        anyhow::bail!(
            "{tensor} in {} has shape {:?}, expected [{h_size}, {cols}] for rank-local column shard",
            path.display(),
            meta.shape
        );
    }
    if !h_size.is_multiple_of(4) {
        anyhow::bail!("{tensor} rows={h_size} must be divisible by 4 for gemv_f16");
    }
    if !cols.is_multiple_of(512) {
        anyhow::bail!("{tensor} cols={cols} must be divisible by 512 for gemv_f16");
    }
    let weight_bytes = shard.read_tensor_bytes(&tensor)?;
    Ok(QwenOProjStagePlan {
        label: format!(
            "rank0:{tensor}:{}:{h_size}x{cols}:BF16-column-shard",
            path.display()
        ),
        rows: h_size,
        cols,
        weight_bytes,
    })
}

fn build_qwen_rank0_qk_norm_rope_stage_plan(
    path: &Path,
    qkv: &QwenQkvProjStagePlan,
    config: &QwenRuntimeConfig,
    layer_idx: u32,
) -> Result<QwenQkNormRopeStagePlan> {
    if config.attention_bias {
        anyhow::bail!(
            "config attention_bias=true is not supported by this bias-free Qwen3 proof path"
        );
    }
    let shard = mcore::weights::SafetensorsShard::open(path)?;
    let q_tensor = format!("model.layers.{layer_idx}.self_attn.q_norm.weight");
    let k_tensor = format!("model.layers.{layer_idx}.self_attn.k_norm.weight");
    let (q_head_dim, q_weight_bytes) = read_qwen_norm_weight(&shard, path, &q_tensor)?;
    let (k_head_dim, k_weight_bytes) = read_qwen_norm_weight(&shard, path, &k_tensor)?;
    if q_head_dim != k_head_dim {
        anyhow::bail!(
            "Qwen layer-{layer_idx} q/k norm head_dim mismatch in {}: q={} k={}",
            path.display(),
            q_head_dim,
            k_head_dim
        );
    }
    if q_head_dim != config.head_dim {
        anyhow::bail!(
            "Qwen config head_dim {} does not match q_norm/k_norm tensor shape {}",
            config.head_dim,
            q_head_dim
        );
    }
    if qkv.q_rows % q_head_dim != 0 || qkv.kv_rows % q_head_dim != 0 {
        anyhow::bail!(
            "Qwen rank-local q/k projection rows must be divisible by head_dim: q_rows={} kv_rows={} head_dim={}",
            qkv.q_rows,
            qkv.kv_rows,
            q_head_dim
        );
    }
    let q_heads = qkv.q_rows / q_head_dim;
    let k_heads = qkv.kv_rows / q_head_dim;
    if q_heads == 0 || k_heads == 0 {
        anyhow::bail!(
            "Qwen rank-local Q/K heads must be non-zero: q_heads={} k_heads={}",
            q_heads,
            k_heads
        );
    }
    if config.num_attention_heads % q_heads != 0 || config.num_key_value_heads % k_heads != 0 {
        anyhow::bail!(
            "Qwen rank-local heads do not evenly divide config heads: local q/k={}/{} config q/k={}/{}",
            q_heads,
            k_heads,
            config.num_attention_heads,
            config.num_key_value_heads
        );
    }
    Ok(QwenQkNormRopeStagePlan {
        label: format!(
            "rank0:model.layers.{layer_idx}.self_attn.q/k_norm.weight:{}:{}+{}:BF16",
            path.display(),
            q_head_dim,
            k_head_dim
        ),
        config_label: format!(
            "hidden={} heads={}/{} head_dim={} theta={} eps={}",
            config.hidden_size,
            config.num_attention_heads,
            config.num_key_value_heads,
            config.head_dim,
            config.rope_theta,
            config.rms_norm_eps
        ),
        q_heads,
        k_heads,
        head_dim: q_head_dim,
        theta: config.rope_theta,
        eps: config.rms_norm_eps,
        q_weight_bytes,
        k_weight_bytes,
    })
}

fn read_qwen_norm_weight(
    shard: &mcore::weights::SafetensorsShard,
    path: &Path,
    tensor: &str,
) -> Result<(u32, Vec<u8>)> {
    let meta = shard.tensor(tensor)?.clone();
    if meta.dtype != "BF16" {
        anyhow::bail!(
            "{tensor} in {} has dtype {}, expected BF16",
            path.display(),
            meta.dtype
        );
    }
    if meta.shape.len() != 1 {
        anyhow::bail!(
            "{tensor} in {} has shape {:?}, expected [head_dim]",
            path.display(),
            meta.shape
        );
    }
    let dim = u32::try_from(meta.shape[0])
        .map_err(|_| anyhow::anyhow!("{tensor} head_dim exceeds u32"))?;
    if dim == 0 || !dim.is_multiple_of(2) {
        anyhow::bail!("{tensor} head_dim {dim} must be non-zero and even for RoPE");
    }
    let weight_bytes = shard.read_tensor_bytes(tensor)?;
    Ok((dim, weight_bytes))
}

fn read_qwen_projection_weight(
    shard: &mcore::weights::SafetensorsShard,
    path: &Path,
    tensor: &str,
    h_size: u32,
    row_name: &str,
) -> Result<(u32, Vec<u8>)> {
    let meta = shard.tensor(tensor)?.clone();
    if meta.dtype != "BF16" {
        anyhow::bail!(
            "{tensor} in {} has dtype {}, expected BF16",
            path.display(),
            meta.dtype
        );
    }
    if meta.shape.len() != 2 || meta.shape[1] != h_size as u64 {
        anyhow::bail!(
            "{tensor} in {} has shape {:?}, expected [{row_name}, {h_size}]",
            path.display(),
            meta.shape
        );
    }
    let rows = u32::try_from(meta.shape[0])
        .map_err(|_| anyhow::anyhow!("{tensor} row count exceeds u32"))?;
    if rows == 0 {
        anyhow::bail!("{tensor} row count must be non-zero");
    }
    let weight_bytes = shard.read_tensor_bytes(tensor)?;
    Ok((rows, weight_bytes))
}

struct F16VectorCompare {
    expected: Vec<u8>,
    max_abs: f32,
    max_dim: usize,
    max_rel: f32,
    max_rel_dim: usize,
    matched_nonfinite: usize,
}

fn expected_rmsnorm_f16_bytes(hidden: &[u8], weight: &[u8], eps: f32) -> Result<Vec<u8>> {
    if hidden.len() != weight.len() || hidden.len() % 2 != 0 {
        anyhow::bail!(
            "RMSNorm oracle requires equal even byte lengths, got hidden={} weight={}",
            hidden.len(),
            weight.len()
        );
    }
    let h = hidden.len() / 2;
    if h == 0 {
        anyhow::bail!("RMSNorm oracle requires non-empty vectors");
    }
    let mut ss = 0.0f32;
    for pair in hidden.chunks_exact(2) {
        let bits = u16::from_le_bytes([pair[0], pair[1]]);
        let v = mcore::gemm::f16_to_f32(bits);
        ss += v * v;
    }
    let rms = 1.0f32 / (ss / h as f32 + eps).sqrt();
    let mut out = vec![0u8; hidden.len()];
    for ((h_pair, w_pair), out_pair) in hidden
        .chunks_exact(2)
        .zip(weight.chunks_exact(2))
        .zip(out.chunks_exact_mut(2))
    {
        let hv = mcore::gemm::f16_to_f32(u16::from_le_bytes([h_pair[0], h_pair[1]]));
        let wv = mcore::gemm::f16_to_f32(u16::from_le_bytes([w_pair[0], w_pair[1]]));
        out_pair.copy_from_slice(&mcore::gemm::f32_to_f16(hv * rms * wv).to_le_bytes());
    }
    Ok(out)
}

fn expected_add_rmsnorm_f16_bytes(
    residual: &[u8],
    delta: &[f32],
    weight: &[u8],
    eps: f32,
) -> Result<(Vec<u8>, Vec<u8>)> {
    if residual.len() != weight.len() || residual.len() % 2 != 0 {
        anyhow::bail!(
            "add+RMSNorm oracle requires equal even residual/weight bytes, got residual={} weight={}",
            residual.len(),
            weight.len()
        );
    }
    let h = residual.len() / 2;
    if h == 0 || delta.len() != h {
        anyhow::bail!(
            "add+RMSNorm oracle length mismatch: residual_elems={} delta_elems={}",
            h,
            delta.len()
        );
    }
    let mut residual_after = vec![0u8; residual.len()];
    let mut ss = 0.0f32;
    for i in 0..h {
        let off = i * 2;
        let rv = mcore::gemm::f16_to_f32(u16::from_le_bytes([residual[off], residual[off + 1]]));
        let hv = mcore::gemm::f32_to_f16(rv + delta[i]);
        residual_after[off..off + 2].copy_from_slice(&hv.to_le_bytes());
        let rounded = mcore::gemm::f16_to_f32(hv);
        ss += rounded * rounded;
    }
    let rms = 1.0f32 / (ss / h as f32 + eps).sqrt();
    let mut normed = vec![0u8; residual.len()];
    for i in 0..h {
        let off = i * 2;
        let hv = mcore::gemm::f16_to_f32(u16::from_le_bytes([
            residual_after[off],
            residual_after[off + 1],
        ]));
        let wv = mcore::gemm::f16_to_f32(u16::from_le_bytes([weight[off], weight[off + 1]]));
        normed[off..off + 2].copy_from_slice(&mcore::gemm::f32_to_f16(hv * rms * wv).to_le_bytes());
    }
    Ok((residual_after, normed))
}

fn expected_add_rmsnorm_bf16_residual_f16_output_bytes(
    residual: &[u8],
    delta: &[f32],
    weight: &[u8],
    eps: f32,
) -> Result<(Vec<u8>, Vec<u8>)> {
    if residual.len() != weight.len() || residual.len() % 2 != 0 {
        anyhow::bail!(
            "bf16 residual add+RMSNorm oracle requires equal even residual/weight bytes, got residual={} weight={}",
            residual.len(),
            weight.len()
        );
    }
    let h = residual.len() / 2;
    if h == 0 || delta.len() != h {
        anyhow::bail!(
            "bf16 residual add+RMSNorm oracle length mismatch: residual_elems={} delta_elems={}",
            h,
            delta.len()
        );
    }
    let mut residual_after = vec![0u8; residual.len()];
    let mut ss = 0.0f32;
    for i in 0..h {
        let off = i * 2;
        let rv = bf16_to_f32(u16::from_le_bytes([residual[off], residual[off + 1]]));
        let rounded = f32_to_bf16_bits(rv + delta[i]);
        residual_after[off..off + 2].copy_from_slice(&rounded.to_le_bytes());
        let rounded_f32 = bf16_to_f32(rounded);
        ss += rounded_f32 * rounded_f32;
    }
    let rms = 1.0f32 / (ss / h as f32 + eps).sqrt();
    let mut normed = vec![0u8; residual.len()];
    for i in 0..h {
        let off = i * 2;
        let rv = bf16_to_f32(u16::from_le_bytes([
            residual_after[off],
            residual_after[off + 1],
        ]));
        let wv = mcore::gemm::f16_to_f32(u16::from_le_bytes([weight[off], weight[off + 1]]));
        normed[off..off + 2].copy_from_slice(&mcore::gemm::f32_to_f16(rv * rms * wv).to_le_bytes());
    }
    Ok((residual_after, normed))
}

fn f16_bytes_to_f32_vec(bytes: &[u8]) -> Result<Vec<f32>> {
    if bytes.len() % 2 != 0 {
        anyhow::bail!(
            "f16 byte conversion requires even byte length, got {}",
            bytes.len()
        );
    }
    Ok(bytes
        .chunks_exact(2)
        .map(|pair| mcore::gemm::f16_to_f32(u16::from_le_bytes([pair[0], pair[1]])))
        .collect())
}

fn expected_f32_allreduce_residual_rmsnorm(
    inputs: &[Vec<f32>],
    residual: &[f32],
    weight: &[f32],
    eps: f32,
) -> Result<(Vec<f32>, Vec<f32>)> {
    let n = residual.len();
    if n == 0 || weight.len() != n {
        anyhow::bail!(
            "f32 allreduce+RMSNorm oracle length mismatch: residual={} weight={}",
            residual.len(),
            weight.len()
        );
    }
    let mut reduced = vec![0.0f32; n];
    for (rank, input) in inputs.iter().enumerate() {
        if input.len() != n {
            anyhow::bail!(
                "f32 allreduce+RMSNorm oracle rank {rank} input length {} != n {n}",
                input.len()
            );
        }
        for (dst, src) in reduced.iter_mut().zip(input.iter()) {
            *dst += *src;
        }
    }
    let mut residual_out = vec![0.0f32; n];
    let mut ss = 0.0f32;
    for i in 0..n {
        let v = reduced[i] + residual[i];
        residual_out[i] = v;
        ss += v * v;
    }
    let inv = 1.0f32 / (ss / n as f32 + eps).sqrt();
    let normed = residual_out
        .iter()
        .zip(weight.iter())
        .map(|(v, w)| *v * inv * *w)
        .collect();
    Ok((residual_out, normed))
}

fn max_rankwise_abs_diff(vectors: &[Vec<f32>]) -> Result<f32> {
    let Some(first) = vectors.first() else {
        anyhow::bail!("rankwise compare requires at least one vector");
    };
    let mut max_abs = 0.0f32;
    for (rank, vector) in vectors.iter().enumerate().skip(1) {
        if vector.len() != first.len() {
            anyhow::bail!(
                "rankwise compare rank {rank} length {} != first length {}",
                vector.len(),
                first.len()
            );
        }
        for (&a, &b) in first.iter().zip(vector.iter()) {
            max_abs = max_abs.max((a - b).abs());
        }
    }
    Ok(max_abs)
}

fn compare_f16_vectors(got: &[u8], expected: &[u8]) -> Result<F16VectorCompare> {
    if got.len() != expected.len() || got.len() % 2 != 0 {
        anyhow::bail!(
            "f16 compare requires equal even byte lengths, got={} expected={}",
            got.len(),
            expected.len()
        );
    }
    let mut max_abs = 0.0f32;
    let mut max_dim = 0usize;
    let mut max_rel = 0.0f32;
    let mut max_rel_dim = 0usize;
    let mut matched_nonfinite = 0usize;
    for (dim, (g, e)) in got
        .chunks_exact(2)
        .zip(expected.chunks_exact(2))
        .enumerate()
    {
        let gb = u16::from_le_bytes([g[0], g[1]]);
        let eb = u16::from_le_bytes([e[0], e[1]]);
        let gv = mcore::gemm::f16_to_f32(gb);
        let ev = mcore::gemm::f16_to_f32(eb);
        if !gv.is_finite() || !ev.is_finite() {
            if gb == eb {
                matched_nonfinite += 1;
                continue;
            }
            return Ok(F16VectorCompare {
                expected: expected.to_vec(),
                max_abs: f32::INFINITY,
                max_dim: dim,
                max_rel: f32::INFINITY,
                max_rel_dim: dim,
                matched_nonfinite,
            });
        }
        let diff = (gv - ev).abs();
        if diff > max_abs {
            max_abs = diff;
            max_dim = dim;
        }
        let rel = diff / (ev.abs() + 1.0e-3);
        if rel > max_rel {
            max_rel = rel;
            max_rel_dim = dim;
        }
    }
    Ok(F16VectorCompare {
        expected: expected.to_vec(),
        max_abs,
        max_dim,
        max_rel,
        max_rel_dim,
        matched_nonfinite,
    })
}

fn max_f16_ulp_diff_over_abs(
    got: &[u8],
    expected: &[u8],
    min_abs: f32,
) -> Result<(u32, usize, f32)> {
    if got.len() != expected.len() || got.len() % 2 != 0 {
        anyhow::bail!(
            "f16 ULP/abs compare requires equal even byte lengths, got={} expected={}",
            got.len(),
            expected.len()
        );
    }
    let mut max_ulp = 0u32;
    let mut max_dim = 0usize;
    let mut max_abs = 0.0f32;
    for (dim, (g, e)) in got
        .chunks_exact(2)
        .zip(expected.chunks_exact(2))
        .enumerate()
    {
        let gb = u16::from_le_bytes([g[0], g[1]]);
        let eb = u16::from_le_bytes([e[0], e[1]]);
        let gv = mcore::gemm::f16_to_f32(gb);
        let ev = mcore::gemm::f16_to_f32(eb);
        if !gv.is_finite() || !ev.is_finite() {
            return Ok((u32::MAX, dim, f32::INFINITY));
        }
        let abs = (gv - ev).abs();
        if abs <= min_abs {
            continue;
        }
        let ulp = ordered_f16_bits(gb).abs_diff(ordered_f16_bits(eb));
        if ulp > max_ulp {
            max_ulp = ulp;
            max_dim = dim;
            max_abs = abs;
        }
    }
    Ok((max_ulp, max_dim, max_abs))
}

fn ordered_f16_bits(bits: u16) -> i32 {
    let bits = bits as i32;
    if bits & 0x8000 != 0 {
        0x8000 - bits
    } else {
        bits
    }
}

struct F32VectorCompare {
    max_rel: f32,
    max_abs: f32,
    max_dim: usize,
}

struct Fp4PackedRow {
    packed: [u8; 64],
    scale: [u8; 4],
}

fn expected_gemv_f32(weight: &[u8], x: &[u8], rows: u32, cols: u32) -> Result<Vec<f32>> {
    let rows = rows as usize;
    let cols = cols as usize;
    if weight.len() != rows * cols * 2 {
        anyhow::bail!(
            "GEMV oracle weight bytes mismatch: got {}, expected {}",
            weight.len(),
            rows * cols * 2
        );
    }
    if x.len() != cols * 2 {
        anyhow::bail!(
            "GEMV oracle input bytes mismatch: got {}, expected {}",
            x.len(),
            cols * 2
        );
    }
    let mut xf = Vec::with_capacity(cols);
    for pair in x.chunks_exact(2) {
        xf.push(mcore::gemm::f16_to_f32(u16::from_le_bytes([
            pair[0], pair[1],
        ])));
    }
    let mut out = vec![0.0f32; rows];
    for row in 0..rows {
        let mut acc = 0.0f32;
        let base = row * cols * 2;
        for (col, xv) in xf.iter().enumerate() {
            let off = base + col * 2;
            let wv = mcore::gemm::f16_to_f32(u16::from_le_bytes([weight[off], weight[off + 1]]));
            acc += wv * *xv;
        }
        out[row] = acc;
    }
    Ok(out)
}

fn expected_f32_allreduce_sum(inputs: &[Vec<f32>]) -> Result<Vec<f32>> {
    let first = inputs
        .first()
        .ok_or_else(|| anyhow::anyhow!("allreduce sum oracle requires at least one input"))?;
    let n = first.len();
    let mut out = vec![0.0f32; n];
    for (rank, input) in inputs.iter().enumerate() {
        if input.len() != n {
            anyhow::bail!(
                "allreduce sum oracle rank {rank} length {} does not match expected {n}",
                input.len()
            );
        }
        for (dst, src) in out.iter_mut().zip(input) {
            *dst += *src;
        }
    }
    Ok(out)
}

fn expected_add_into_f16_bytes(acc: &[u8], x: &[f32]) -> Result<Vec<u8>> {
    if acc.len() != x.len() * 2 || acc.len() % 2 != 0 {
        anyhow::bail!(
            "add-into-f16 oracle length mismatch: acc_bytes={} x_f32={}",
            acc.len(),
            x.len()
        );
    }
    let mut out = Vec::with_capacity(acc.len());
    for (pair, &xv) in acc.chunks_exact(2).zip(x.iter()) {
        let av = mcore::gemm::f16_to_f32(u16::from_le_bytes([pair[0], pair[1]]));
        out.extend_from_slice(&mcore::gemm::f32_to_f16(av + xv).to_le_bytes());
    }
    Ok(out)
}

fn f32_vec_to_f16_bytes(values: &[f32]) -> Result<Vec<u8>> {
    let mut out = Vec::with_capacity(values.len() * 2);
    for &value in values {
        out.extend_from_slice(&mcore::gemm::f32_to_f16(value).to_le_bytes());
    }
    Ok(out)
}

fn f32_to_bf16_bits(value: f32) -> u16 {
    let bits = value.to_bits();
    let lsb = (bits >> 16) & 1;
    ((bits + 0x7fff + lsb) >> 16) as u16
}

fn bf16_to_f32(bits: u16) -> f32 {
    f32::from_bits((bits as u32) << 16)
}

fn f32_vec_to_bf16_bytes(values: &[f32]) -> Result<Vec<u8>> {
    let mut out = Vec::with_capacity(values.len() * 2);
    for &value in values {
        out.extend_from_slice(&f32_to_bf16_bits(value).to_le_bytes());
    }
    Ok(out)
}

fn bf16_bytes_to_f16_bytes(bytes: &[u8]) -> Result<Vec<u8>> {
    if bytes.len() % 2 != 0 {
        anyhow::bail!(
            "BF16-to-F16 conversion requires an even byte length, got {}",
            bytes.len()
        );
    }
    let mut out = Vec::with_capacity(bytes.len());
    for pair in bytes.chunks_exact(2) {
        let bf16 = u16::from_le_bytes([pair[0], pair[1]]);
        let value = f32::from_bits((bf16 as u32) << 16);
        out.extend_from_slice(&mcore::gemm::f32_to_f16(value).to_le_bytes());
    }
    Ok(out)
}

