fn expected_swiglu_f16_bytes_from_f32(gate: &[f32], up: &[f32]) -> Result<Vec<u8>> {
    if gate.len() != up.len() {
        anyhow::bail!(
            "SwiGLU oracle length mismatch: gate={} up={}",
            gate.len(),
            up.len()
        );
    }
    let mut out = Vec::with_capacity(gate.len() * 2);
    for (&gate_v, &up_v) in gate.iter().zip(up.iter()) {
        let gate_h = mcore::gemm::f32_to_f16(gate_v);
        let up_h = mcore::gemm::f32_to_f16(up_v);
        let gate_f = mcore::gemm::f16_to_f32(gate_h);
        let up_f = mcore::gemm::f16_to_f32(up_h);
        let silu = gate_f / (1.0 + (-gate_f).exp());
        out.extend_from_slice(&mcore::gemm::f32_to_f16(silu * up_f).to_le_bytes());
    }
    Ok(out)
}

fn compare_f32_vectors_rel(got: &[f32], expected: &[f32]) -> Result<F32VectorCompare> {
    if got.len() != expected.len() {
        anyhow::bail!(
            "f32 compare length mismatch: got={} expected={}",
            got.len(),
            expected.len()
        );
    }
    let mut max_rel = 0.0f32;
    let mut max_abs = 0.0f32;
    let mut max_dim = 0usize;
    for (i, (&g, &e)) in got.iter().zip(expected.iter()).enumerate() {
        if !g.is_finite() || !e.is_finite() {
            return Ok(F32VectorCompare {
                max_rel: f32::INFINITY,
                max_abs: f32::INFINITY,
                max_dim: i,
            });
        }
        let abs = (g - e).abs();
        let rel = abs / (e.abs() + 1.0e-2);
        if rel > max_rel {
            max_rel = rel;
            max_abs = abs;
            max_dim = i;
        }
    }
    Ok(F32VectorCompare {
        max_rel,
        max_abs,
        max_dim,
    })
}

fn expected_cast_rmsnorm_rope_heads_f16_bytes(
    src: &[f32],
    weight: &[u8],
    heads: u32,
    d: u32,
    pos: u32,
    theta: f32,
    eps: f32,
) -> Result<Vec<u8>> {
    let heads = heads as usize;
    let d = d as usize;
    if d == 0 || d % 2 != 0 {
        anyhow::bail!("QK-Norm+RoPE oracle requires an even non-zero head dim, got {d}");
    }
    if src.len() != heads * d {
        anyhow::bail!(
            "QK-Norm+RoPE oracle source length mismatch: got {}, expected {}",
            src.len(),
            heads * d
        );
    }
    if weight.len() != d * 2 {
        anyhow::bail!(
            "QK-Norm+RoPE oracle weight bytes mismatch: got {}, expected {}",
            weight.len(),
            d * 2
        );
    }
    let mut wf = Vec::with_capacity(d);
    for pair in weight.chunks_exact(2) {
        wf.push(mcore::gemm::f16_to_f32(u16::from_le_bytes([
            pair[0], pair[1],
        ])));
    }
    let mut out = vec![0u8; heads * d * 2];
    let half_d = d / 2;
    for head in 0..heads {
        let base = head * d;
        let mut cast_src = Vec::with_capacity(d);
        let mut ss = 0.0f32;
        for i in 0..d {
            let v = mcore::gemm::f16_to_f32(mcore::gemm::f32_to_f16(src[base + i]));
            cast_src.push(v);
            ss += v * v;
        }
        let rms = 1.0f32 / (ss / d as f32 + eps).sqrt();
        for i in 0..half_d {
            let ah = mcore::gemm::f16_to_f32(mcore::gemm::f32_to_f16(cast_src[i] * rms * wf[i]));
            let bh = mcore::gemm::f16_to_f32(mcore::gemm::f32_to_f16(
                cast_src[i + half_d] * rms * wf[i + half_d],
            ));
            let freq = theta.powf(-2.0f32 * i as f32 / d as f32);
            let ang = pos as f32 * freq;
            let (s, c) = ang.sin_cos();
            let first = mcore::gemm::f32_to_f16(ah * c - bh * s).to_le_bytes();
            let second = mcore::gemm::f32_to_f16(bh * c + ah * s).to_le_bytes();
            let out_base = (base + i) * 2;
            out[out_base..out_base + 2].copy_from_slice(&first);
            let out_pair = (base + i + half_d) * 2;
            out[out_pair..out_pair + 2].copy_from_slice(&second);
        }
    }
    Ok(out)
}

fn expected_single_row_attention_f16_bytes(
    value_row: &[f32],
    q_heads: u32,
    head_dim: u32,
) -> Result<Vec<u8>> {
    let head_dim = head_dim as usize;
    if value_row.len() != head_dim {
        anyhow::bail!(
            "single-row attention oracle requires one value row of head_dim={}, got {}",
            head_dim,
            value_row.len()
        );
    }
    let mut out = Vec::with_capacity(q_heads as usize * head_dim * 2);
    for _ in 0..q_heads {
        for &v in value_row {
            out.extend_from_slice(&mcore::gemm::f32_to_f16(v).to_le_bytes());
        }
    }
    Ok(out)
}

fn expected_fp4_cache_attention_f16_bytes(
    q_rope: &[u8],
    k_cache: &[u8],
    k_scale: &[u8],
    v_cache: &[u8],
    v_scale: &[u8],
    q_heads: u32,
    head_dim: u32,
    n: u32,
    rows_per_head: usize,
    scale: f32,
) -> Result<Vec<u8>> {
    let head_dim_usize = head_dim as usize;
    let q_heads_usize = q_heads as usize;
    let n_usize = n as usize;
    if head_dim_usize != 128 {
        anyhow::bail!(
            "FP4 cache attention oracle currently requires head_dim=128, got {}",
            head_dim
        );
    }
    if n == 0 {
        anyhow::bail!("FP4 cache attention oracle requires non-zero n");
    }
    if n_usize > rows_per_head {
        anyhow::bail!(
            "FP4 cache attention oracle n={} exceeds rows_per_head={}",
            n,
            rows_per_head
        );
    }
    let expected_q_bytes = q_heads_usize * head_dim_usize * 2;
    if q_rope.len() != expected_q_bytes {
        anyhow::bail!(
            "FP4 cache attention oracle Q bytes mismatch: got {}, expected {}",
            q_rope.len(),
            expected_q_bytes
        );
    }
    if k_cache.len() < rows_per_head * 64
        || v_cache.len() < rows_per_head * 64
        || k_scale.len() < rows_per_head * 4
        || v_scale.len() < rows_per_head * 4
    {
        anyhow::bail!(
            "FP4 cache attention oracle cache too small: k={} v={} sk={} sv={} rows_per_head={}",
            k_cache.len(),
            v_cache.len(),
            k_scale.len(),
            v_scale.len(),
            rows_per_head
        );
    }
    let mut k_rows = Vec::with_capacity(n_usize);
    let mut v_rows = Vec::with_capacity(n_usize);
    for row in 0..n_usize {
        let packed_begin = row * 64;
        let scale_begin = row * 4;
        k_rows.push(decode_fp4_row_from_cache(
            &k_cache[packed_begin..packed_begin + 64],
            &k_scale[scale_begin..scale_begin + 4],
        )?);
        v_rows.push(decode_fp4_row_from_cache(
            &v_cache[packed_begin..packed_begin + 64],
            &v_scale[scale_begin..scale_begin + 4],
        )?);
    }
    let mut out = Vec::with_capacity(q_heads_usize * head_dim_usize * 2);
    for head in 0..q_heads_usize {
        let q_base = head * head_dim_usize * 2;
        let mut q = [0.0f32; 128];
        for dim in 0..head_dim_usize {
            let p = q_base + dim * 2;
            q[dim] = mcore::gemm::f16_to_f32(u16::from_le_bytes([q_rope[p], q_rope[p + 1]]));
        }
        let mut scores = vec![0.0f32; n_usize];
        let mut max_score = f32::NEG_INFINITY;
        for row in 0..n_usize {
            let mut dot = 0.0f32;
            for dim in 0..head_dim_usize {
                dot += q[dim] * k_rows[row][dim];
            }
            let score = dot * scale;
            scores[row] = score;
            max_score = max_score.max(score);
        }
        if !max_score.is_finite() {
            anyhow::bail!("FP4 cache attention oracle produced non-finite max score");
        }
        let mut denom = 0.0f32;
        for score in &scores {
            denom += (*score - max_score).exp();
        }
        if denom == 0.0 || !denom.is_finite() {
            anyhow::bail!("FP4 cache attention oracle produced invalid softmax denom {denom}");
        }
        for dim in 0..head_dim_usize {
            let mut acc = 0.0f32;
            for row in 0..n_usize {
                let p = (scores[row] - max_score).exp() / denom;
                acc += p * v_rows[row][dim];
            }
            out.extend_from_slice(&mcore::gemm::f32_to_f16(acc).to_le_bytes());
        }
    }
    Ok(out)
}

fn expected_fp4_row_from_f16_bytes(row: &[u8]) -> Result<Fp4PackedRow> {
    let values = fp4_values_from_f16_bytes(row)?;
    expected_fp4_row_from_values(&values)
}

fn fp4_values_from_f16_bytes(row: &[u8]) -> Result<[f32; 128]> {
    if row.len() != 128 * 2 {
        anyhow::bail!(
            "FP4 row oracle requires one D=128 f16 row (256 bytes), got {}",
            row.len()
        );
    }
    let mut values = [0.0f32; 128];
    for (i, pair) in row.chunks_exact(2).enumerate() {
        values[i] = mcore::gemm::f16_to_f32(u16::from_le_bytes([pair[0], pair[1]]));
    }
    Ok(values)
}

fn expected_fp4_row_from_f32_cast(row: &[f32]) -> Result<Fp4PackedRow> {
    let values = fp4_values_from_f32_cast(row)?;
    expected_fp4_row_from_values(&values)
}

fn fp4_values_from_f32_cast(row: &[f32]) -> Result<[f32; 128]> {
    if row.len() != 128 {
        anyhow::bail!(
            "FP4 row oracle requires one D=128 f32 row, got {}",
            row.len()
        );
    }
    let mut values = [0.0f32; 128];
    for (i, &v) in row.iter().enumerate() {
        values[i] = mcore::gemm::f16_to_f32(mcore::gemm::f32_to_f16(v));
    }
    Ok(values)
}

fn run_next_decode_fp4_kv_append_rank(
    dev: &mut mcore::GpuDevice,
    cache_plan: &QwenFp4KvCacheStagePlan,
    attn_plan: Option<&QwenFp4SingleRowAttentionStagePlan>,
    o_proj_plan: Option<&QwenOProjStagePlan>,
    o_proj_weight_bytes: Option<&[u8]>,
    o_proj_output_va: Option<u64>,
    q_rope_va: u64,
    k_rope_va: u64,
    v_va: u64,
    got_q_rope: &[u8],
    got_k_rope: &[u8],
    got_v: &[f32],
    expected_q_rope: &[u8],
    expected_k_rope: &[u8],
    expected_v: &[f32],
    position: u32,
) -> Result<QwenNextDecodeKvAppendRankProof> {
    if cache_plan.head_dim != 128 {
        anyhow::bail!(
            "next decode FP4 KV append requires head_dim=128, got {}",
            cache_plan.head_dim
        );
    }
    if cache_plan.block_size == 0 {
        anyhow::bail!("next decode FP4 KV append requires non-zero block_size");
    }
    let expected_k_bytes = cache_plan.kv_heads as usize * cache_plan.head_dim as usize * 2;
    let expected_v_values = cache_plan.kv_heads as usize * cache_plan.head_dim as usize;
    if got_k_rope.len() != expected_k_bytes {
        anyhow::bail!(
            "next decode FP4 KV append K bytes mismatch: got {}, expected {}",
            got_k_rope.len(),
            expected_k_bytes
        );
    }
    if got_v.len() != expected_v_values {
        anyhow::bail!(
            "next decode FP4 KV append V value count mismatch: got {}, expected {}",
            got_v.len(),
            expected_v_values
        );
    }
    if expected_q_rope.len() != got_q_rope.len()
        || expected_k_rope.len() != got_k_rope.len()
        || expected_v.len() != got_v.len()
    {
        anyhow::bail!(
            "next decode FP4 independent oracle length mismatch: q {} vs {}, k {} vs {}, v {} vs {}",
            expected_q_rope.len(),
            got_q_rope.len(),
            expected_k_rope.len(),
            got_k_rope.len(),
            expected_v.len(),
            got_v.len()
        );
    }
    if let Some(attn) = attn_plan {
        if attn.head_dim != cache_plan.head_dim {
            anyhow::bail!(
                "next decode FP4 attention head_dim={} does not match cache head_dim={}",
                attn.head_dim,
                cache_plan.head_dim
            );
        }
        if attn.real_q_heads != attn.kernel_q_heads || attn.kernel_q_heads_per_kv != 4 {
            anyhow::bail!(
                "next decode FP4 attention requires native 4Q/1KV plan, got real_q={} kernel_q={} q_per_kv={}",
                attn.real_q_heads,
                attn.kernel_q_heads,
                attn.kernel_q_heads_per_kv
            );
        }
        if got_q_rope.len() != attn.q_bytes() {
            anyhow::bail!(
                "next decode FP4 attention Q bytes mismatch: got {}, expected {}",
                got_q_rope.len(),
                attn.q_bytes()
            );
        }
    }
    match (
        o_proj_plan,
        o_proj_weight_bytes,
        o_proj_output_va,
        attn_plan,
    ) {
        (Some(o_plan), Some(weight_bytes), Some(_), Some(attn)) => {
            if o_plan.cols != attn.real_q_heads * attn.head_dim {
                anyhow::bail!(
                    "next decode O-proj cols={} do not match attention output {}",
                    o_plan.cols,
                    attn.real_q_heads * attn.head_dim
                );
            }
            let expected_weight_bytes = o_plan.rows as usize * o_plan.cols as usize * 2;
            if weight_bytes.len() != expected_weight_bytes {
                anyhow::bail!(
                    "next decode O-proj weight bytes mismatch: got {}, expected {}",
                    weight_bytes.len(),
                    expected_weight_bytes
                );
            }
        }
        (None, None, None, _) => {}
        _ => {
            anyhow::bail!(
                "next decode O-proj proof requires o_proj_plan, weight bytes, output VA, and attention plan together"
            );
        }
    }
    let total_indices = position / cache_plan.block_size + 1;
    let physical_blocks = total_indices;
    let page = position / cache_plan.block_size;
    let page_offset = position - page * cache_plan.block_size;
    let seq_len = position
        .checked_add(1)
        .ok_or_else(|| anyhow::anyhow!("next decode FP4 KV append sequence length overflow"))?;
    let last_page_len = if seq_len % cache_plan.block_size == 0 {
        cache_plan.block_size
    } else {
        seq_len % cache_plan.block_size
    };
    if page >= total_indices || page_offset >= cache_plan.block_size {
        anyhow::bail!(
            "next decode FP4 KV append position {} maps outside total_indices={} block_size={}",
            position,
            total_indices,
            cache_plan.block_size
        );
    }
    if page == total_indices - 1 && page_offset >= last_page_len {
        anyhow::bail!(
            "next decode FP4 KV append offset {} exceeds last_page_len {}",
            page_offset,
            last_page_len
        );
    }
    let cache_bytes = cache_plan.kv_heads as usize
        * physical_blocks as usize
        * cache_plan.block_size as usize
        * 64;
    let scale_bytes = cache_plan.kv_heads as usize
        * physical_blocks as usize
        * cache_plan.block_size as usize
        * 4;
    let mut k_cache = dev.alloc(cache_bytes)?;
    let mut v_cache = dev.alloc(cache_bytes)?;
    let mut scale_k = dev.alloc(scale_bytes)?;
    let mut scale_v = dev.alloc(scale_bytes)?;
    let mut indices = dev.alloc_device(total_indices as usize * 4)?;
    let mut indptr = dev.alloc_device(2 * 4)?;
    let mut last_page_len_buf = dev.alloc_device(4)?;
    let mut batch_indices = dev.alloc_device(4)?;
    let mut positions = dev.alloc_device(4)?;
    unsafe {
        k_cache.as_mut_slice_of::<u8>()[..cache_bytes].fill(0);
        v_cache.as_mut_slice_of::<u8>()[..cache_bytes].fill(0);
        scale_k.as_mut_slice_of::<u8>()[..scale_bytes].fill(0);
        scale_v.as_mut_slice_of::<u8>()[..scale_bytes].fill(0);
        let index_slice = indices.as_mut_slice_of::<u32>();
        for (idx, slot) in index_slice
            .iter_mut()
            .enumerate()
            .take(total_indices as usize)
        {
            *slot = u32::try_from(idx)
                .map_err(|_| anyhow::anyhow!("next decode FP4 KV append index exceeds u32"))?;
        }
        let indptr_slice = indptr.as_mut_slice_of::<u32>();
        indptr_slice[0] = 0;
        indptr_slice[1] = total_indices;
        last_page_len_buf.as_mut_slice_of::<u32>()[0] = last_page_len;
        batch_indices.as_mut_slice_of::<u32>()[0] = 0;
        positions.as_mut_slice_of::<u32>()[0] = position;
    }
    let before_append = std::time::Instant::now();
    dev.arm_kv_append_paged_fp4_from_f16_vf32_heads(
        k_cache.va(),
        v_cache.va(),
        scale_k.va(),
        scale_v.va(),
        k_rope_va,
        v_va,
        indices.va(),
        indptr.va(),
        last_page_len_buf.va(),
        batch_indices.va(),
        positions.va(),
        1,
        1,
        total_indices,
        physical_blocks,
        cache_plan.block_size,
        cache_plan.kv_heads,
    )?;
    let wait = dev.wait(std::time::Duration::from_secs(10))?;
    let wall = before_append.elapsed();
    let got_k_cache = unsafe { k_cache.as_mut_slice_of::<u8>()[..cache_bytes].to_vec() };
    let got_v_cache = unsafe { v_cache.as_mut_slice_of::<u8>()[..cache_bytes].to_vec() };
    let got_k_scale = unsafe { scale_k.as_mut_slice_of::<u8>()[..scale_bytes].to_vec() };
    let got_v_scale = unsafe { scale_v.as_mut_slice_of::<u8>()[..scale_bytes].to_vec() };
    let mut expected_k_cache = vec![0u8; cache_bytes];
    let mut expected_v_cache = vec![0u8; cache_bytes];
    let mut expected_k_scale = vec![0u8; scale_bytes];
    let mut expected_v_scale = vec![0u8; scale_bytes];
    let rows_per_head = physical_blocks as usize * cache_plan.block_size as usize;
    let row = page as usize * cache_plan.block_size as usize + page_offset as usize;
    let mut byte_mismatches = 0usize;
    let mut k_cache_first = 0u8;
    let mut k_cache_first_expected = 0u8;
    let mut k_cache_last = 0u8;
    let mut k_cache_last_expected = 0u8;
    let mut v_cache_first = 0u8;
    let mut v_cache_first_expected = 0u8;
    let mut v_cache_last = 0u8;
    let mut v_cache_last_expected = 0u8;
    let mut k_scale_bytes = [0u8; 4];
    let mut k_scale_expected = [0u8; 4];
    let mut v_scale_bytes = [0u8; 4];
    let mut v_scale_expected = [0u8; 4];
    for head in 0..cache_plan.kv_heads as usize {
        let k_head_begin = head * cache_plan.head_dim as usize * 2;
        let k_head_end = k_head_begin + cache_plan.head_dim as usize * 2;
        let v_head_begin = head * cache_plan.head_dim as usize;
        let v_head_end = v_head_begin + cache_plan.head_dim as usize;
        let expected_k_values =
            fp4_values_from_f16_bytes(&expected_k_rope[k_head_begin..k_head_end])?;
        let expected_v_values = fp4_values_from_f32_cast(&expected_v[v_head_begin..v_head_end])?;
        let expected_k = expected_fp4_row_from_values(&expected_k_values)?;
        let expected_v_row = expected_fp4_row_from_values(&expected_v_values)?;
        let row_base = (head * rows_per_head + row) * 64;
        let scale_base = (head * rows_per_head + row) * 4;
        expected_k_cache[row_base..row_base + 64].copy_from_slice(&expected_k.packed);
        expected_v_cache[row_base..row_base + 64].copy_from_slice(&expected_v_row.packed);
        expected_k_scale[scale_base..scale_base + 4].copy_from_slice(&expected_k.scale);
        expected_v_scale[scale_base..scale_base + 4].copy_from_slice(&expected_v_row.scale);
        let got_k_row = &got_k_cache[row_base..row_base + 64];
        let got_v_row = &got_v_cache[row_base..row_base + 64];
        let got_ks = &got_k_scale[scale_base..scale_base + 4];
        let got_vs = &got_v_scale[scale_base..scale_base + 4];
        let mut first_mismatch = None;
        if first_mismatch.is_none() {
            first_mismatch = fp4_packed_mismatch_detail(
                "k_packed",
                head,
                got_k_row,
                &expected_k.packed,
                &expected_k_values,
                &expected_k.scale,
            );
        }
        if first_mismatch.is_none() {
            first_mismatch = fp4_packed_mismatch_detail(
                "v_packed",
                head,
                got_v_row,
                &expected_v_row.packed,
                &expected_v_values,
                &expected_v_row.scale,
            );
        }
        if first_mismatch.is_none() {
            first_mismatch = fp4_scale_mismatch_detail("k_scale", head, got_ks, &expected_k.scale);
        }
        if first_mismatch.is_none() {
            first_mismatch =
                fp4_scale_mismatch_detail("v_scale", head, got_vs, &expected_v_row.scale);
        }
        byte_mismatches += count_fp4_packed_semantic_mismatches(got_k_row, &expected_k.packed)?;
        byte_mismatches += count_fp4_packed_semantic_mismatches(got_v_row, &expected_v_row.packed)?;
        byte_mismatches += count_byte_mismatches(got_ks, &expected_k.scale)?;
        byte_mismatches += count_byte_mismatches(got_vs, &expected_v_row.scale)?;
        if byte_mismatches != 0 {
            let detail = first_mismatch.unwrap_or_else(|| "first mismatch unavailable".to_string());
            anyhow::bail!(
                "next decode FP4 KV cache append mismatch: {byte_mismatches} packed/scale bytes differ; first_mismatch: {detail}"
            );
        }
        if head == 0 {
            k_cache_first = got_k_row[0];
            k_cache_first_expected = expected_k.packed[0];
            k_cache_last = got_k_row[63];
            k_cache_last_expected = expected_k.packed[63];
            v_cache_first = got_v_row[0];
            v_cache_first_expected = expected_v_row.packed[0];
            v_cache_last = got_v_row[63];
            v_cache_last_expected = expected_v_row.packed[63];
            k_scale_bytes.copy_from_slice(got_ks);
            k_scale_expected.copy_from_slice(&expected_k.scale);
            v_scale_bytes.copy_from_slice(got_vs);
            v_scale_expected.copy_from_slice(&expected_v_row.scale);
        }
    }
    let mut o_proj = None;
    let attention = if let Some(attn) = attn_plan {
        let mut block_table = dev.alloc_device(total_indices as usize * 4)?;
        let mut partials = dev.alloc(attn.partial_bytes())?;
        let attention_out_bytes = attn.real_q_heads as usize * attn.head_dim as usize * 2;
        let mut combined = dev.alloc(attention_out_bytes)?;
        unsafe {
            let block_table_slice = block_table.as_mut_slice_of::<u32>();
            for (idx, slot) in block_table_slice
                .iter_mut()
                .enumerate()
                .take(total_indices as usize)
            {
                *slot = u32::try_from(idx).map_err(|_| {
                    anyhow::anyhow!("next decode FP4 attention block index exceeds u32")
                })?;
            }
            partials.as_mut_slice_of::<f32>()[..attn.partial_f32s()].fill(f32::NAN);
            combined.as_mut_slice_of::<u8>()[..attention_out_bytes].fill(0);
        }
        let rows_per_head_u32 = physical_blocks
            .checked_mul(cache_plan.block_size)
            .ok_or_else(|| anyhow::anyhow!("next decode FP4 attention rows_per_head overflow"))?;
        let attention_scale = 1.0f32 / (attn.head_dim as f32).sqrt();
        let before_attention = std::time::Instant::now();
        dev.arm_attn_decode_split_fp4_gqa4_paged_groups(
            q_rope_va,
            k_cache.va(),
            v_cache.va(),
            scale_k.va(),
            scale_v.va(),
            block_table.va(),
            cache_plan.block_size,
            physical_blocks,
            partials.va(),
            seq_len,
            attn.head_dim,
            attention_scale,
            1,
            1,
            attn.kernel_q_heads_per_kv,
            rows_per_head_u32,
        )?;
        let attention_wait = dev.wait(std::time::Duration::from_secs(10))?;
        dev.arm_attn_decode_combine_gqa_f16(
            partials.va(),
            combined.va(),
            attn.head_dim,
            1,
            attn.real_q_heads,
        )?;
        let combine_wait = dev.wait(std::time::Duration::from_secs(10))?;
        let attention_wall = before_attention.elapsed();
        let partial_values =
            unsafe { partials.as_mut_slice_of::<f32>()[..attn.partial_f32s()].to_vec() };
        let got_attention =
            unsafe { combined.as_mut_slice_of::<u8>()[..attention_out_bytes].to_vec() };
        let expected_attention = expected_fp4_cache_attention_f16_bytes(
            expected_q_rope,
            &expected_k_cache,
            &expected_k_scale,
            &expected_v_cache,
            &expected_v_scale,
            attn.real_q_heads,
            attn.head_dim,
            seq_len,
            rows_per_head,
            attention_scale,
        )?;
        let attention_cmp = compare_f16_vectors(&got_attention, &expected_attention)?;
        if attention_cmp.max_abs > 2.5e-3 && attention_cmp.max_rel > 2.0e-2 {
            anyhow::bail!(
                "next decode FP4 attention mismatch: max_abs={} at dim {} max_rel={} at dim {} exceeds tolerance",
                attention_cmp.max_abs,
                attention_cmp.max_dim,
                attention_cmp.max_rel,
                attention_cmp.max_rel_dim
            );
        }
        if let (Some(o_plan), Some(weight_bytes), Some(output_va)) =
            (o_proj_plan, o_proj_weight_bytes, o_proj_output_va)
        {
            let mut o_weight = dev.alloc_device(weight_bytes.len())?;
            unsafe {
                o_weight.as_mut_slice_of::<u8>()[..weight_bytes.len()]
                    .copy_from_slice(weight_bytes);
            }
            let before_o_proj = std::time::Instant::now();
            dev.arm_gemv(
                o_weight.va(),
                combined.va(),
                output_va,
                o_plan.rows,
                o_plan.cols,
            )?;
            let o_wait = dev.wait(std::time::Duration::from_secs(10))?;
            let o_wall = before_o_proj.elapsed();
            let expected_contribution =
                expected_gemv_f32(weight_bytes, &got_attention, o_plan.rows, o_plan.cols)?;
            o_proj = Some(QwenNextDecodeOProjRankProof {
                expected_contribution,
                gpu_wait_us: o_wait.as_secs_f64() * 1e6,
                wall_us: o_wall.as_secs_f64() * 1e6,
            });
        }
        let output_first = u16::from_le_bytes([got_attention[0], got_attention[1]]);
        let output_first_expected =
            u16::from_le_bytes([expected_attention[0], expected_attention[1]]);
        let last = got_attention.len() - 2;
        let output_last = u16::from_le_bytes([got_attention[last], got_attention[last + 1]]);
        let output_last_expected =
            u16::from_le_bytes([expected_attention[last], expected_attention[last + 1]]);
        Some(QwenNextDecodeAttentionRankProof {
            max_abs: attention_cmp.max_abs,
            max_dim: attention_cmp.max_dim,
            max_rel: attention_cmp.max_rel,
            max_rel_dim: attention_cmp.max_rel_dim,
            attention_gpu_wait_us: attention_wait.as_secs_f64() * 1e6,
            combine_gpu_wait_us: combine_wait.as_secs_f64() * 1e6,
            wall_us: attention_wall.as_secs_f64() * 1e6,
            softmax_m_head0: partial_values[0],
            softmax_l_head0: partial_values[1],
            output_first,
            output_first_expected,
            output_last,
            output_last_expected,
        })
    } else {
        None
    };
    Ok(QwenNextDecodeKvAppendRankProof {
        byte_mismatches,
        gpu_wait_us: wait.as_secs_f64() * 1e6,
        wall_us: wall.as_secs_f64() * 1e6,
        total_indices,
        physical_blocks,
        page,
        page_offset,
        last_page_len,
        k_cache_first,
        k_cache_first_expected,
        k_cache_last,
        k_cache_last_expected,
        v_cache_first,
        v_cache_first_expected,
        v_cache_last,
        v_cache_last_expected,
        k_scale_bytes,
        k_scale_expected,
        v_scale_bytes,
        v_scale_expected,
        attention,
        o_proj,
    })
}

fn expected_fp4_row_from_values(values: &[f32; 128]) -> Result<Fp4PackedRow> {
    let mut packed = [0u8; 64];
    let mut scale = [0u8; 4];
    for block in 0..4usize {
        let begin = block * 32;
        let maxabs = values[begin..begin + 32]
            .iter()
            .fold(0.0f32, |acc, &v| acc.max(v.abs()));
        let exp = if maxabs > 0.0 {
            (maxabs / 6.0).log2().ceil() as i32
        } else {
            0
        };
        let sb_i = (exp + 127).clamp(0, 255);
        let sb = sb_i as u8;
        scale[block] = sb;
        let sf = f32::from_bits((sb as u32) << 23);
        for j in 0..16usize {
            let d0 = begin + j * 2;
            let n0 = e2m1_quant_nearest(values[d0] / sf);
            let n1 = e2m1_quant_nearest(values[d0 + 1] / sf);
            packed[block * 16 + j] = n0 | (n1 << 4);
        }
    }
    Ok(Fp4PackedRow { packed, scale })
}

fn e2m1_quant_nearest(x: f32) -> u8 {
    let sign = if x < 0.0 { 8 } else { 0 };
    let a = x.abs();
    let idx = if a < 0.25 {
        0
    } else if a < 0.75 {
        1
    } else if a < 1.25 {
        2
    } else if a < 1.75 {
        3
    } else if a < 2.5 {
        4
    } else if a < 3.5 {
        5
    } else if a < 5.0 {
        6
    } else {
        7
    };
    sign | idx
}

fn count_byte_mismatches(got: &[u8], expected: &[u8]) -> Result<usize> {
    if got.len() != expected.len() {
        anyhow::bail!(
            "byte compare length mismatch: got={} expected={}",
            got.len(),
            expected.len()
        );
    }
    Ok(got
        .iter()
        .zip(expected.iter())
        .filter(|(g, e)| g != e)
        .count())
}

fn count_fp4_packed_semantic_mismatches(got: &[u8], expected: &[u8]) -> Result<usize> {
    if got.len() != expected.len() {
        anyhow::bail!(
            "packed FP4 compare length mismatch: got={} expected={}",
            got.len(),
            expected.len()
        );
    }
    let mut mismatches = 0usize;
    for (&g, &e) in got.iter().zip(expected.iter()) {
        if !fp4_packed_bytes_semantically_equal(g, e) {
            mismatches += 1;
        }
    }
    Ok(mismatches)
}

fn fp4_nibbles_semantically_equal(got: u8, expected: u8) -> bool {
    got == expected || ((got & 0x07) == 0 && (expected & 0x07) == 0)
}

fn fp4_packed_bytes_semantically_equal(got: u8, expected: u8) -> bool {
    fp4_nibbles_semantically_equal(got & 0x0f, expected & 0x0f)
        && fp4_nibbles_semantically_equal(got >> 4, expected >> 4)
}

fn fp4_packed_mismatch_detail(
    component: &str,
    head: usize,
    got: &[u8],
    expected: &[u8],
    values: &[f32; 128],
    scale: &[u8; 4],
) -> Option<String> {
    for (byte_idx, (&g, &e)) in got.iter().zip(expected.iter()).enumerate() {
        if fp4_packed_bytes_semantically_equal(g, e) {
            continue;
        }
        let block = byte_idx / 16;
        let elem0 = block * 32 + (byte_idx % 16) * 2;
        let elem1 = elem0 + 1;
        let scale_byte = scale[block];
        let scale_f32 = f32::from_bits((scale_byte as u32) << 23);
        let g0 = g & 0x0f;
        let g1 = g >> 4;
        let e0 = e & 0x0f;
        let e1 = e >> 4;
        return Some(format!(
            "component={component} head={head} block={block} byte={byte_idx} dims={elem0},{elem1} got=0x{g:02x} expected=0x{e:02x} got_nibbles=0x{g0:x},0x{g1:x} expected_nibbles=0x{e0:x},0x{e1:x} scale=0x{scale_byte:02x} scale_f32={scale_f32:e} value0={:e} value1={:e} norm0={:e} norm1={:e}",
            values[elem0],
            values[elem1],
            values[elem0] / scale_f32,
            values[elem1] / scale_f32,
        ));
    }
    None
}

fn fp4_scale_mismatch_detail(
    component: &str,
    head: usize,
    got: &[u8],
    expected: &[u8; 4],
) -> Option<String> {
    for (byte_idx, (&g, &e)) in got.iter().zip(expected.iter()).enumerate() {
        if g == e {
            continue;
        }
        let got_scale = f32::from_bits((g as u32) << 23);
        let expected_scale = f32::from_bits((e as u32) << 23);
        return Some(format!(
            "component={component} head={head} block={byte_idx} got=0x{g:02x} expected=0x{e:02x} got_scale={got_scale:e} expected_scale={expected_scale:e}"
        ));
    }
    None
}

fn decode_fp4_row_from_cache(packed: &[u8], scale: &[u8]) -> Result<Vec<f32>> {
    if packed.len() != 64 || scale.len() != 4 {
        anyhow::bail!(
            "FP4 decode oracle requires 64 packed bytes and 4 scale bytes, got packed={} scale={}",
            packed.len(),
            scale.len()
        );
    }
    let mut out = vec![0.0f32; 128];
    for block in 0..4usize {
        let sf = f32::from_bits((scale[block] as u32) << 23);
        for j in 0..16usize {
            let byte = packed[block * 16 + j];
            out[block * 32 + j * 2] = e2m1_dequant(byte & 0x0f) * sf;
            out[block * 32 + j * 2 + 1] = e2m1_dequant(byte >> 4) * sf;
        }
    }
    Ok(out)
}

fn e2m1_dequant(bits: u8) -> f32 {
    let sign = if (bits & 0x08) != 0 { -1.0 } else { 1.0 };
    let mag = match bits & 0x07 {
        0 => 0.0,
        1 => 0.5,
        2 => 1.0,
        3 => 1.5,
        4 => 2.0,
        5 => 3.0,
        6 => 4.0,
        _ => 6.0,
    };
    sign * mag
}

fn resolve_tokenizer_path(path: &Path) -> PathBuf {
    if path.is_dir() {
        path.join("tokenizer.json")
    } else {
        path.to_path_buf()
    }
}

fn resolve_qwen_config_path(tokenizer_path: &Path) -> PathBuf {
    tokenizer_path
        .parent()
        .map(|parent| parent.join("config.json"))
        .unwrap_or_else(|| PathBuf::from("config.json"))
}

fn load_qwen_runtime_config(path: &Path) -> Result<QwenRuntimeConfig> {
    let text = fs::read_to_string(path)
        .map_err(|err| anyhow::anyhow!("reading Qwen config {} failed: {err}", path.display()))?;
    let hidden_size = required_json_u32_field(&text, "hidden_size", path)?;
    let intermediate_size = optional_json_u32_field(&text, "intermediate_size", path)?;
    let num_attention_heads = required_json_u32_field(&text, "num_attention_heads", path)?;
    let num_key_value_heads =
        optional_json_u32_field(&text, "num_key_value_heads", path)?.unwrap_or(num_attention_heads);
    let head_dim = optional_json_u32_field(&text, "head_dim", path)?
        .unwrap_or_else(|| hidden_size / num_attention_heads);
    let rms_norm_eps = required_json_f32_field(&text, "rms_norm_eps", path)?;
    let rope_theta = required_json_f32_field(&text, "rope_theta", path)?;
    let attention_bias = optional_json_bool_field(&text, "attention_bias", path)?.unwrap_or(false);
    if hidden_size == 0 || num_attention_heads == 0 || num_key_value_heads == 0 || head_dim == 0 {
        anyhow::bail!(
            "Qwen config {} has invalid zero field: hidden={} q_heads={} kv_heads={} head_dim={}",
            path.display(),
            hidden_size,
            num_attention_heads,
            num_key_value_heads,
            head_dim
        );
    }
    if intermediate_size == Some(0) {
        anyhow::bail!("Qwen config {} has intermediate_size=0", path.display());
    }
    if hidden_size % num_attention_heads != 0 {
        anyhow::bail!(
            "Qwen config {} hidden_size={} is not divisible by num_attention_heads={}",
            path.display(),
            hidden_size,
            num_attention_heads
        );
    }
    Ok(QwenRuntimeConfig {
        hidden_size,
        intermediate_size,
        num_attention_heads,
        num_key_value_heads,
        head_dim,
        rms_norm_eps,
        rope_theta,
        attention_bias,
    })
}

fn required_json_u32_field(text: &str, key: &str, path: &Path) -> Result<u32> {
    optional_json_u32_field(text, key, path)?
        .ok_or_else(|| anyhow::anyhow!("{} missing {}", path.display(), key))
}

fn optional_json_u32_field(text: &str, key: &str, path: &Path) -> Result<Option<u32>> {
    optional_json_scalar(text, key)
        .map(|value| {
            value.parse::<u32>().map_err(|err| {
                anyhow::anyhow!("parsing {} {} as u32 failed: {err}", path.display(), key)
            })
        })
        .transpose()
}

fn required_json_f32_field(text: &str, key: &str, path: &Path) -> Result<f32> {
    optional_json_scalar(text, key)
        .ok_or_else(|| anyhow::anyhow!("{} missing {}", path.display(), key))?
        .parse::<f32>()
        .map_err(|err| anyhow::anyhow!("parsing {} {} as f32 failed: {err}", path.display(), key))
}

fn optional_json_bool_field(text: &str, key: &str, path: &Path) -> Result<Option<bool>> {
    optional_json_scalar(text, key)
        .map(|value| match value {
            "true" => Ok(true),
            "false" => Ok(false),
            _ => Err(anyhow::anyhow!(
                "parsing {} {} as bool failed: got {}",
                path.display(),
                key,
                value
            )),
        })
        .transpose()
}

fn optional_json_scalar<'a>(text: &'a str, key: &str) -> Option<&'a str> {
    let needle = format!("\"{key}\"");
    let pos = text.find(&needle)?;
    let colon = text[pos + needle.len()..].find(':')? + pos + needle.len();
    let rest = text[colon + 1..].trim_start();
    let end = rest
        .find(|c: char| c == ',' || c == '}' || c.is_whitespace())
        .unwrap_or(rest.len());
    Some(rest[..end].trim_matches('"'))
}

fn render_qwen_instruct_prompt(
    system: Option<&str>,
    prompt: &str,
    add_generation_prompt: bool,
) -> String {
    let mut rendered = String::new();
    if let Some(system) = system {
        rendered.push_str("<|im_start|>system\n");
        rendered.push_str(system);
        rendered.push_str("<|im_end|>\n");
    }
    rendered.push_str("<|im_start|>user\n");
    rendered.push_str(prompt);
    rendered.push_str("<|im_end|>\n");
    if add_generation_prompt {
        rendered.push_str("<|im_start|>assistant\n");
    }
    rendered
}

fn first_gpu_or(node: Option<u32>) -> Result<u32> {
    match node {
        Some(n) => Ok(n),
        None => mcore::enumerate_gpus()?
            .first()
            .map(|g| g.node_id)
            .ok_or_else(|| anyhow::anyhow!("no GPU nodes under /sys/class/kfd")),
    }
}

fn gemm_check(node: Option<u32>, m: Option<u32>, n: Option<u32>, k: Option<u32>) -> Result<()> {
    println!("mainarch gemm-check: CDNA4 FP16 matrix core (MFMA), no ROCm\n");
    let node_id = first_gpu_or(node)?;
    let mut dev = mcore::GpuDevice::open(node_id)?;
    mcore::gemm::check_mfma_tile_16_on(&mut dev)?;
    match (m, n, k) {
        (Some(m), Some(n), Some(k)) => mcore::gemm::check_gemm_f16_on(&mut dev, m, n, k)?,
        _ => {
            for &(m, n, k) in &[
                (16u32, 16, 16),
                (64, 64, 64),
                (256, 256, 256),
                (512, 4096, 4096),
            ] {
                mcore::gemm::check_gemm_f16_on(&mut dev, m, n, k)?;
            }
        }
    }
    Ok(())
}

fn decode_layer(node: Option<u32>) -> Result<()> {
    println!("mainarch decode-layer: RMSNorm + RoPE + SwiGLU + GEMV + MoE FFN (no ROCm)\n");
    let node_id = first_gpu_or(node)?;
    let mut dev = mcore::GpuDevice::open(node_id)?;
    for &h in &[3584u32, 4096, 8192] {
        mcore::layer::check_rmsnorm_on(&mut dev, h)?;
    }
    for &h in &[128u32, 4096] {
        mcore::layer::check_rope_on(&mut dev, h)?;
    }
    for &n in &[18944u32, 4096] {
        mcore::layer::check_swiglu_on(&mut dev, n)?;
    }
    // Decode projections are matrix-vector (M=1) — memory-bound GEMV.
    for &(n, k) in &[(4096u32, 3584u32), (3584, 3584), (12288, 4096)] {
        mcore::layer::check_gemv_on(&mut dev, n, k, 30)?;
    }
    for &(n, k) in &[(4096u32, 3584u32), (12288, 4096)] {
        mcore::layer::check_gemv_fp8_on(&mut dev, n, k, 30)?;
        mcore::layer::check_gemv_fp8_wblock_on(&mut dev, n, k, 30)?;
    }
    println!();
    // MoE FFN (Qwen3-235B-A22B: 128 experts, top-8, no shared expert). Small dims
    // first, then real per-expert dims (H=4096, I=1536). The router-scan length E
    // is trivial/E-agnostic, so E=32 here bounds host RAM (deployment E=128).
    mcore::layer::check_moe_ffn_on(&mut dev, 1024, 512, 32, 8, 20)?;
    mcore::layer::check_moe_ffn_on(&mut dev, 4096, 1536, 32, 8, 20)?;
    println!();
    // Full assembled Qwen3-235B-A22B decode layer vs an f64 reference.
    mcore::attn::check_decode_layer_on(&mut dev)?;
    println!();
    mcore::attn::characterize_kv_quant(4096, 128);
    Ok(())
}

