#[allow(clippy::too_many_arguments)]
fn olmo2_generate(
    node: Option<u32>,
    config: PathBuf,
    index: PathBuf,
    tokenizer_path: PathBuf,
    prompt: String,
    max_new: usize,
    max_seq: u32,
    layers: Option<usize>,
) -> Result<()> {
    println!("mainarch olmo2-generate: OLMo 2 on the raw KFD/AQL path, no ROCm\n");
    let node_id = match node {
        Some(n) => n,
        None => {
            let gpus = mcore::enumerate_gpus()?;
            gpus.first()
                .map(|g| g.node_id)
                .ok_or_else(|| anyhow::anyhow!("no GPU nodes under /sys/class/kfd"))?
        }
    };
    let tokenizer = tokenizers::Tokenizer::from_file(&tokenizer_path).map_err(|err| {
        anyhow::anyhow!(
            "loading tokenizer {} failed: {err}",
            tokenizer_path.display()
        )
    })?;
    let encoding = tokenizer
        .encode(prompt.as_str(), false)
        .map_err(|err| anyhow::anyhow!("tokenization failed: {err}"))?;
    let ids = encoding.get_ids().to_vec();
    if ids.is_empty() {
        anyhow::bail!("prompt encoded to zero tokens");
    }

    let mut dev = mcore::GpuDevice::open(node_id)?;
    let weights = mcore::olmo2::load_olmo2_weights(&mut dev, config, index, layers)?;
    let mut runner = mcore::olmo2::Olmo2Runner::new(&mut dev, weights, max_seq)?;

    println!("  prompt   : {prompt:?}");
    println!(
        "  tokens   : {} -> {:?}",
        ids.len(),
        &ids[..ids.len().min(16)]
    );
    let started = std::time::Instant::now();
    let out = runner.generate(&mut dev, &ids, max_new)?;
    let elapsed = started.elapsed();
    let steps = ids.len() + out.len().saturating_sub(1);
    let text = tokenizer
        .decode(&out, false)
        .map_err(|err| anyhow::anyhow!("detokenization failed: {err}"))?;
    println!("  generated: {:?}", &out[..out.len().min(16)]);
    println!(
        "  {:.1} ms for {} decode steps ({:.1} ms/token)",
        elapsed.as_secs_f64() * 1e3,
        steps,
        elapsed.as_secs_f64() * 1e3 / steps.max(1) as f64
    );
    println!();
    println!("  {}{}", prompt, text);
    Ok(())
}

