fn olmo2_preflight(config: PathBuf, index: PathBuf, tp_world: usize) -> Result<()> {
    println!("mainarch olmo2-preflight: CPU-only OLMo 2 checkpoint contract gate\n");
    let r = mcore::olmo2::preflight_olmo2_checkpoint(config, index, tp_world)?;
    let checkpoint_bytes = r
        .indexed_bytes
        .map(|bytes| format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0)))
        .unwrap_or_else(|| "unknown".to_string());
    println!(
        "  olmo2 preflight ok: model_type={} layers={} heads={} kv_heads={} head_dim={}",
        r.model_type, r.num_hidden_layers, r.num_attention_heads, r.num_key_value_heads, r.head_dim
    );
    println!(
        "  attention: q_heads_per_kv={} ({}), qk_norm spans q={} k={} elements (whole projection)",
        r.q_heads_per_kv,
        if r.is_multi_head {
            "multi-head"
        } else {
            "grouped-query"
        },
        r.q_norm_elems,
        r.k_norm_elems
    );
    println!(
        "  shape: hidden={} intermediate={} vocab={} rope_theta={} tie_word_embeddings={}",
        r.hidden_size, r.intermediate_size, r.vocab_size, r.rope_theta, r.tie_word_embeddings
    );
    println!(
        "  tensors={} tp_tensors={} replicated={} lm_head_present={} tp_world={} checkpoint_bytes={}",
        r.tensor_count,
        r.tensor_parallel_tensors,
        r.replicated_tensors,
        r.lm_head_present,
        r.tp_world,
        checkpoint_bytes
    );
    println!(
        "  layer order: post-norm (residual-branch normalisation), no input_layernorm present"
    );
    Ok(())
}

