fn weights_qwen_layer_load(
    node: Option<u32>,
    source: PathBuf,
    layer: usize,
    iters: usize,
    tp_rank: usize,
    tp_world: usize,
    chunk_mb: usize,
    prefetch: bool,
    packed_projections: bool,
    gpu_contract_check: bool,
    gpu_qk_norm_rope_check: bool,
    expect_packed_fingerprint: Option<String>,
) -> Result<()> {
    println!(
        "mainarch weights-qwen-layer-load: one dense Qwen decoder layer to VRAM with source-byte checks (no ROCm)\n"
    );
    let node_id = first_gpu_or(node)?;
    let r = mcore::weights::bench_qwen_layer_rank_local_safetensors_loader(
        node_id,
        source,
        layer,
        iters,
        tp_rank,
        tp_world,
        chunk_mb,
        prefetch,
        packed_projections,
        gpu_contract_check,
        gpu_qk_norm_rope_check,
    )?;
    if let Some(expected) = expect_packed_fingerprint {
        let expected = parse_u64_literal(&expected)?;
        let Some(contract) = &r.packed_contract else {
            anyhow::bail!("--expect-packed-fingerprint requires --packed-projections");
        };
        if contract.fingerprint != expected {
            anyhow::bail!(
                "packed projection fingerprint mismatch: got 0x{:016x}, expected 0x{:016x}",
                contract.fingerprint,
                expected
            );
        }
        println!(
            "  packed projection fingerprint verified: 0x{:016x}",
            contract.fingerprint
        );
    }
    let layout = match r.layout {
        mcore::weights::QwenLayerWeightLayout::ExecutionOrder => "execution-order",
        mcore::weights::QwenLayerWeightLayout::PackedProjections => "packed-projections",
    };
    println!(
        "  qwen layer {}: selected {} required tensors ({:.1} MiB rank-local), layout {}",
        r.layer,
        r.tensor_count,
        r.layer_bytes as f64 / (1024.0 * 1024.0),
        layout
    );
    println!("  execution layout:");
    for route in &r.routes {
        println!(
            "    {:<58} dst {:>9} B  len {:>9} B  file {}..{}",
            route.name, route.dst_begin, route.byte_len, route.file_begin, route.file_end
        );
    }
    if !r.packed_groups.is_empty() {
        println!("  packed projection groups:");
        for group in &r.packed_groups {
            println!(
                "    {:<58} dst {:>9} B  len {:>9} B",
                group.name, group.dst_begin, group.byte_len
            );
            for component in &group.components {
                println!(
                    "      {:<56} group+{:>9} B  len {:>9} B",
                    component.name, component.group_offset, component.byte_len
                );
            }
        }
        println!("  packed projection signatures:");
        for signature in &r.packed_group_signatures {
            println!(
                "    {:<58} first {:>3}  last {:>3}",
                signature.name, signature.first_byte, signature.last_byte
            );
            for component in &signature.components {
                println!(
                    "      {:<56} first {:>3}  last {:>3}",
                    component.name, component.first_byte, component.last_byte
                );
            }
        }
        if let Some(contract) = &r.packed_contract {
            println!(
                "  packed projection contract: fingerprint 0x{:016x}, device 0x{:016x}",
                contract.fingerprint, contract.device_fingerprint
            );
            println!(
                "    qkv_proj     dst {:>9} B  len {:>9} B  q +{:>9}/{}  k +{:>9}/{}  v +{:>9}/{}",
                contract.qkv_dst_begin,
                contract.qkv_byte_len,
                contract.q_offset,
                contract.q_byte_len,
                contract.k_offset,
                contract.k_byte_len,
                contract.v_offset,
                contract.v_byte_len
            );
            println!(
                "    gate_up_proj dst {:>9} B  len {:>9} B  gate +{:>9}/{}  up +{:>9}/{}",
                contract.gate_up_dst_begin,
                contract.gate_up_byte_len,
                contract.gate_offset,
                contract.gate_byte_len,
                contract.up_offset,
                contract.up_byte_len
            );
        }
        if let Some(check) = &r.gpu_packed_contract_check {
            println!(
                "  packed projection GPU check: fingerprint 0x{:016x}, qkv_edges 0x{:012x}, gate_up_edges 0x{:08x}",
                check.fingerprint, check.qkv_edges, check.gate_up_edges
            );
        }
    }
    if let Some(check) = &r.gpu_qk_norm_rope_check {
        let q_delta = f32::from_bits((check.order_delta_bits & 0xffff_ffff) as u32);
        let k_delta = f32::from_bits((check.order_delta_bits >> 32) as u32);
        println!(
            "  qk-norm/RoPE GPU check: fingerprint 0x{:016x}, q_edges 0x{:010x}, k_edges 0x{:010x}, order_delta q={:.6e} k={:.6e}",
            check.fingerprint, check.q_edges, check.k_edges, q_delta, k_delta
        );
    }
    print_weight_load_result(&r.load, "qwen layer weights");
    Ok(())
}

fn parse_u64_literal(s: &str) -> Result<u64> {
    let trimmed = s.trim();
    let digits = trimmed
        .strip_prefix("0x")
        .or_else(|| trimmed.strip_prefix("0X"));
    match digits {
        Some(hex) => u64::from_str_radix(hex, 16)
            .map_err(|e| anyhow::anyhow!("invalid u64 hex literal {trimmed}: {e}")),
        None => trimmed
            .parse::<u64>()
            .map_err(|e| anyhow::anyhow!("invalid u64 literal {trimmed}: {e}")),
    }
}

