fn print_weight_load_result(r: &mcore::weights::WeightLoadBenchResult, label: &str) {
    let mode = match r.read_mode {
        mcore::weights::WeightLoadReadMode::Buffered => "buffered".to_string(),
        mcore::weights::WeightLoadReadMode::DirectAligned { alignment } => {
            format!("O_DIRECT aligned {alignment} B")
        }
    };
    println!(
        "  node {} tp {}/{}: {} logical {:.1} MiB, loaded {:.1} MiB, read {:.1} MiB ({:.2}x), {} iters, tensors {}, source ranges {}, read groups {}, read mode {}, upload mode {}",
        r.node_id,
        r.tp_rank,
        r.tp_world,
        label,
        r.tensor_bytes as f64 / (1024.0 * 1024.0),
        r.slice_bytes as f64 / (1024.0 * 1024.0),
        r.read_bytes as f64 / (1024.0 * 1024.0),
        r.read_amplification,
        r.iterations,
        r.tensor_count,
        r.source_range_count,
        r.range_count,
        mode,
        if r.overlap_staging {
            format!(
                "overlapped staging chunks {:.1} MiB",
                r.chunk_bytes as f64 / (1024.0 * 1024.0)
            )
        } else if r.stream_staging {
            format!(
                "streamed staging chunks {:.1} MiB",
                r.chunk_bytes as f64 / (1024.0 * 1024.0)
            )
        } else if r.reuse_upload {
            "reused queue/staging".to_string()
        } else {
            "one-shot queue/staging".to_string()
        }
    );
    println!(
        "  materialize: {:>9.1} us  {:>8.2} GiB/s",
        r.materialize_avg.as_secs_f64() * 1e6,
        r.materialize_gib_s
    );
    println!(
        "  staged SDMA: {:>9.1} us  {:>8.2} GiB/s",
        r.upload_avg.as_secs_f64() * 1e6,
        r.upload_gib_s
    );
    if r.prefetch_before_timing {
        println!(
            "  prefetch   : {:>9.1} us  {:>8.2} GiB/s ({:.1} MiB before timing)",
            r.prefetch_elapsed.as_secs_f64() * 1e6,
            r.prefetch_gib_s,
            r.prefetch_bytes as f64 / (1024.0 * 1024.0)
        );
    }
    println!(
        "  end-to-end : {:>9.1} us  {:>8.2} GiB/s",
        r.end_to_end_avg.as_secs_f64() * 1e6,
        r.end_to_end_gib_s
    );
    println!(
        "  readback samples: first={} last={}",
        r.first_byte, r.last_byte
    );
}

fn weights_load_bench(
    node: Option<u32>,
    mb: usize,
    iters: usize,
    tp_rank: usize,
    tp_world: usize,
    direct: bool,
    direct_alignment: u64,
    reuse_upload: bool,
    stream_staging: bool,
    overlap_staging: bool,
    qwen_set: bool,
    qwen_rank_shard: bool,
    coalesce_gap_kb: usize,
    chunk_mb: usize,
) -> Result<()> {
    println!(
        "mainarch weights-load-bench: SafeTensors TP slice read + raw SDMA upload (no ROCm)\n"
    );
    if qwen_set
        && coalesce_gap_kb != 0
        && std::env::var_os("MAINARCH_I_UNDERSTAND_HOST_COALESCE_CAN_WEDGE_KFD").is_none()
    {
        anyhow::bail!(
            "refusing hazardous host-side Qwen coalescing: --coalesce-gap-kb={} previously wedged KFD/AMDGPU in unkillable D-state; set MAINARCH_I_UNDERSTAND_HOST_COALESCE_CAN_WEDGE_KFD=1 only on an isolated disposable node",
            coalesce_gap_kb
        );
    }
    if qwen_set && qwen_rank_shard {
        anyhow::bail!("choose only one of --qwen-set or --qwen-rank-shard");
    }
    let node_id = first_gpu_or(node)?;
    let read_mode = if direct {
        mcore::weights::WeightLoadReadMode::DirectAligned {
            alignment: direct_alignment,
        }
    } else {
        mcore::weights::WeightLoadReadMode::Buffered
    };
    let r = if qwen_rank_shard {
        mcore::weights::bench_safetensors_qwen_rank_shard_loader(
            node_id, mb, iters, tp_rank, tp_world, chunk_mb,
        )?
    } else if qwen_set {
        mcore::weights::bench_safetensors_qwen_set_loader(
            node_id,
            mb,
            iters,
            tp_rank,
            tp_world,
            chunk_mb,
            coalesce_gap_kb,
        )?
    } else {
        mcore::weights::bench_safetensors_sdma_loader_with_options(
            node_id,
            mb,
            iters,
            tp_rank,
            tp_world,
            read_mode,
            reuse_upload,
            stream_staging || overlap_staging,
            chunk_mb,
            overlap_staging,
        )?
    };
    let mode = match r.read_mode {
        mcore::weights::WeightLoadReadMode::Buffered => "buffered".to_string(),
        mcore::weights::WeightLoadReadMode::DirectAligned { alignment } => {
            format!("O_DIRECT aligned {alignment} B")
        }
    };
    println!(
        "  node {} tp {}/{}: synthetic tensor {:.1} MiB, local slice {:.1} MiB, read {:.1} MiB ({:.2}x), {} iters, tensors {}, source ranges {}, read groups {}, read mode {}, upload mode {}",
        r.node_id,
        r.tp_rank,
        r.tp_world,
        r.tensor_bytes as f64 / (1024.0 * 1024.0),
        r.slice_bytes as f64 / (1024.0 * 1024.0),
        r.read_bytes as f64 / (1024.0 * 1024.0),
        r.read_amplification,
        r.iterations,
        r.tensor_count,
        r.source_range_count,
        r.range_count,
        mode,
        if r.overlap_staging {
            format!(
                "overlapped staging chunks {:.1} MiB",
                r.chunk_bytes as f64 / (1024.0 * 1024.0)
            )
        } else if r.stream_staging {
            format!(
                "streamed staging chunks {:.1} MiB",
                r.chunk_bytes as f64 / (1024.0 * 1024.0)
            )
        } else if r.reuse_upload {
            "reused queue/staging".to_string()
        } else {
            "one-shot queue/staging".to_string()
        }
    );
    println!(
        "  materialize: {:>9.1} us  {:>8.2} GiB/s",
        r.materialize_avg.as_secs_f64() * 1e6,
        r.materialize_gib_s
    );
    println!(
        "  staged SDMA: {:>9.1} us  {:>8.2} GiB/s",
        r.upload_avg.as_secs_f64() * 1e6,
        r.upload_gib_s
    );
    println!(
        "  end-to-end : {:>9.1} us  {:>8.2} GiB/s",
        r.end_to_end_avg.as_secs_f64() * 1e6,
        r.end_to_end_gib_s
    );
    println!(
        "  readback samples: first={} last={}",
        r.first_byte, r.last_byte
    );
    Ok(())
}

fn attn_decode(node: Option<u32>, d: u32, iters: usize) -> Result<()> {
    println!("mainarch attn-decode: FlashDecoding (memory-bound), no ROCm\n");
    let node_id = first_gpu_or(node)?;
    let mut dev = mcore::GpuDevice::open(node_id)?;
    // Establish the real achievable HBM read bandwidth in this environment.
    let vram_gbps = mcore::attn::bench_vram_read_on(&mut dev, 512 * 1024 * 1024, 30)?;
    println!("  raw VRAM streaming read: {vram_gbps:.1} GB/s (float4, full occupancy)\n");
    // Correctness on a modest KV length (FP16 KV, FP8-E4M3 KV, GQA FP8).
    mcore::attn::check_attn_decode_on(&mut dev, 8192, d)?;
    mcore::attn::check_attn_decode_fp8_on(&mut dev, 8192, d)?;
    mcore::attn::check_attn_decode_fp4_on(&mut dev, 8192, d)?;
    mcore::attn::check_fp4_dot_probe_on(&mut dev, 8192, d)?;
    let (fp4_dot_us, fp4_dot_gbps) =
        mcore::attn::bench_fp4_dot_probe_on(&mut dev, 1048576, d, iters)?;
    println!(
        "  fp4-dot-probe 1M: {} rows x D={} -> {:.1} us, {:.1} GB/s effective packed FP4+scale+out\n",
        1048576, d, fp4_dot_us, fp4_dot_gbps
    );
    mcore::attn::check_attn_decode_nvfp4_on(&mut dev, 8192, d)?;
    mcore::attn::check_attn_decode_gqa_on(&mut dev, 8192, d)?;
    mcore::attn::check_attn_decode_fp8_gqa_on(&mut dev, 8192, d)?;
    mcore::attn::check_attn_decode_fp8_gqa_paged_on(&mut dev, 8192, d)?;
    mcore::attn::check_attn_decode_fp4_gqa_on(&mut dev, 8192, d)?;
    mcore::attn::check_kv_append_paged_on(&mut dev, d)?;
    mcore::attn::check_attn_decode_paged_after_append_on(&mut dev, 8192, d)?;
    mcore::attn::check_attn_decode_paged_on(&mut dev, 8192, d)?;
    mcore::attn::check_attn_decode_fp4_gqa_paged_after_append_on(&mut dev, 8192, d)?;
    mcore::attn::check_attn_decode_fp4_gqa_paged_on(&mut dev, 8192, d)?;
    // KV-bandwidth sweep over context lengths (HBM peak ~8 TB/s). FP8 halves the
    // KV bytes moved, so the win shows up as ~2x lower time at equal context.
    println!(
        "\n  {:>10} {:>5}   {:>12}  {:>10}   {:>12}  {:>10}   {:>7}",
        "KV_len", "D", "fp16 us", "fp16 GB/s", "fp8 us", "fp8 GB/s", "speedup"
    );
    println!("  {}", "-".repeat(78));
    for &n in &[65536u32, 262144, 1048576] {
        let (g16, us16) = mcore::attn::bench_attn_decode_on(&mut dev, n, d, iters)?;
        let (g8, us8) = mcore::attn::bench_attn_decode_fp8_on(&mut dev, n, d, iters)?;
        let (_g4, us4) = mcore::attn::bench_attn_decode_fp4_on(&mut dev, n, d, iters)?;
        println!(
            "  {n:>10} {d:>5}   {us16:>12.1}  {g16:>10.1}   {us8:>12.1}  {g8:>10.1}   {:>6.2}x  | fp4 {us4:>8.1}us {:>5.2}x",
            us16 / us8,
            us16 / us4
        );
    }
    // GQA FP16: the decode-loop attention itself — G query heads share ONE KV
    // read (vs the per-head split reading the shared KV G times). Effective KV
    // bandwidth = KV bytes read once per group / group time, against the ~5800
    // GB/s float4 streaming ceiling measured above. This is the kernel the model
    // decode loop now uses; the per-head path is the "naive Gx" column.
    let gqa_g = 8.0;
    println!(
        "\n  GQA FP16 (decode-loop attention: {} query heads share one KV read):",
        gqa_g as u32
    );
    println!(
        "  {:>10}   {:>16}  {:>12}   {:>12}   {:>9}   {:>10}",
        "KV_len", "naive Gx fp16 us", "GQA grp us", "GQA us/head", "speedup", "KV GB/s"
    );
    println!("  {}", "-".repeat(86));
    for &n in &[65536u32, 262144, 1048576] {
        let (_g16, us16) = mcore::attn::bench_attn_decode_on(&mut dev, n, d, iters)?;
        let (grp, per_head) = mcore::attn::bench_attn_decode_gqa_on(&mut dev, n, d, iters)?;
        let naive = us16 * gqa_g;
        let kv_gbps = 2.0 * n as f64 * d as f64 * 2.0 / (grp * 1e-6) / 1e9;
        println!(
            "  {n:>10}   {naive:>16.1}  {grp:>12.1}   {per_head:>14.1}   {:>8.2}x   {kv_gbps:>10.1}",
            naive / grp
        );
    }
    // GQA: one KV read serves G query heads. Compare a G-head group decode (GQA,
    // KV read once) against the naive G× single-head FP8 cost (KV read G times).
    println!("\n  GQA FP8 (G query heads share one KV head: KV read once vs G times):");
    println!(
        "  {:>10}   {:>14}  {:>12}   {:>14}   {:>9}",
        "KV_len", "naive Gx fp8 us", "GQA grp us", "GQA us/head", "speedup"
    );
    println!("  {}", "-".repeat(70));
    for &n in &[65536u32, 262144, 1048576] {
        let (_g8, us8) = mcore::attn::bench_attn_decode_fp8_on(&mut dev, n, d, iters)?;
        let (grp, per_head) = mcore::attn::bench_attn_decode_fp8_gqa_on(&mut dev, n, d, iters)?;
        let naive = us8 * gqa_g;
        println!(
            "  {n:>10}   {naive:>14.1}  {grp:>12.1}   {per_head:>14.1}   {:>8.2}x",
            naive / grp
        );
    }
    // GQA + FP4: the headline 1M config (4x compression x G-head amortization).
    println!("\n  GQA + FP4 (G=8 heads share one 4-bit KV head):");
    println!(
        "  {:>10}   {:>12}   {:>14}   {:>16}",
        "KV_len", "grp us", "us/head", "vs naive Gx fp16"
    );
    println!("  {}", "-".repeat(60));
    for &n in &[65536u32, 262144, 1048576] {
        let (g16, us16) = mcore::attn::bench_attn_decode_on(&mut dev, n, d, iters)?;
        let _ = g16;
        let (grp, per_head) = mcore::attn::bench_attn_decode_fp4_gqa_on(&mut dev, n, d, iters)?;
        println!(
            "  {n:>10}   {grp:>12.1}   {per_head:>14.1}   {:>15.2}x",
            us16 * gqa_g / grp
        );
    }
    // The capstone: paged + GQA + FP4 (the real serving primitive) at scale.
    println!("\n  CAPSTONE paged+GQA+FP4 (the real Qwen 1M decode primitive):");
    println!("  {:>10}   {:>12}   {:>14}", "KV_len", "grp us", "us/head");
    println!("  {}", "-".repeat(42));
    for &n in &[65536u32, 262144, 1048576] {
        let (grp, per_head) =
            mcore::attn::bench_attn_decode_fp4_gqa_paged_on(&mut dev, n, d, iters)?;
        println!("  {n:>10}   {grp:>12.1}   {per_head:>14.1}");
    }
    Ok(())
}

