fn gpu_paged_mla_fp8_splitk_e2e_selftest(
    node: Option<u32>,
    iters: u32,
    tokens: u32,
    block_size: u32,
    split_pages: Option<u32>,
    max_stage1_token_rows: Option<u32>,
    heads: u32,
    output_dims: u32,
    output_dim_offset: u32,
    case_mode: String,
    plan_only: bool,
) -> Result<()> {
    println!(
        "mainarch gpu-paged-mla-fp8-splitk-e2e-selftest - guarded FP8/E4M3 MLA split-K stage1+stage2 paged decode microbench, no ROCm\n"
    );
    let node_id = match node {
        Some(n) => n,
        None if plan_only => 2,
        None => {
            let gpus = mcore::enumerate_gpus()?;
            gpus.first()
                .map(|g| g.node_id)
                .ok_or_else(|| anyhow::anyhow!("no GPU nodes under /sys/class/kfd"))?
        }
    };
    let valid_only = case_mode == "valid-only";
    let default_max_stage1_token_rows = if tokens <= 2_048 {
        2048
    } else if valid_only && tokens == 262_144 && heads < 16 {
        // MI355X MLA FP8 split-K valid-only, heads=4/8, 256K:
        // 65536-row chunks 17351-17655 us/case vs 4096-row 18751-18875.
        65536
    } else if valid_only && tokens < 262_144 && tokens > 131_072 && heads < 16 {
        // MI355X MLA FP8 split-K valid-only, heads=4/8, >128K stopgap:
        // Avoid the generic 4096-row fallback while persistent device-side
        // work scheduling is still a follow-up.
        // 192K: 65536-row cap 13164 us/case vs 4096-row fallback 14119.
        65536
    } else if valid_only && tokens == 131_072 && heads < 16 {
        // MI355X MLA FP8 split-K valid-only, heads=4/8, 128K:
        // 65536-row chunks 8722-8741 us/case vs 4096-row 9315-9394.
        65536
    } else if valid_only && tokens < 131_072 && tokens > 65_536 && heads < 16 {
        // MI355X MLA FP8 split-K valid-only, heads=4/8, >64K stopgap:
        // Keep non-exact long contexts off the generic 4096-row fallback while
        // persistent/internal SplitKV scheduling is still a follow-up.
        // 96K: 65536-row cap 6576 us/case vs 4096-row fallback 7014.
        65536
    } else if valid_only && tokens <= 65_536 && tokens >= 8_192 && heads < 16 {
        // MI355X MLA FP8 split-K valid-only, heads=4/8:
        // Full short-context chunks avoid the stage2 merge and win after the
        // heads8 split merge/bookkeeping work.
        // 8K: 8192-row chunks 565-566 us/case.
        // 12K: 12288-row chunk 841 us/case vs 8192-row chunks 892.
        // 16K: 16384-row chunk 1131 us/case vs 8192-row chunks 1177.
        // 24K: 24576-row chunk 1658 us/case vs 4096-row chunks 1797.
        // 32K: 32768-row chunk 2209 us/case vs 16384-row chunks 2258.
        // 48K: 49152-row chunk 3266 us/case vs 4096-row chunks 3523.
        // 64K: 65536-row chunk 4346 us/case vs 32768-row chunks 4407.
        tokens
    } else if tokens >= 16_384 {
        4096
    } else if tokens >= 12_288 {
        // MI355X 12K MLA FP8 split-K E2E, heads=16, iters=30:
        // 4096-row chunks 8390 us/case vs old 2048-row default 8578.
        4096
    } else if tokens >= 8_192 {
        // MI355X 8K MLA FP8 split-K E2E, heads=16, iters=50:
        // 4096-row chunks 5592-5597 us/case vs old 1024-row default 5982.
        4096
    } else {
        1024
    };
    let block_size_pages = block_size.max(1);
    let total_pages = tokens.saturating_add(block_size_pages - 1) / block_size_pages;
    let default_split_pages = (default_max_stage1_token_rows / block_size_pages)
        .max(1)
        .min(total_pages.max(1));
    let split_pages = split_pages.unwrap_or(default_split_pages);
    let max_stage1_token_rows = max_stage1_token_rows.unwrap_or(default_max_stage1_token_rows);
    mcore::gpu_paged_mla_fp8_splitk_e2e_selftest(
        node_id,
        iters,
        tokens,
        block_size,
        split_pages,
        max_stage1_token_rows,
        heads,
        output_dims,
        output_dim_offset,
        &case_mode,
        plan_only,
    )
}

fn gpu_paged_mla_fp8_splitk_full_latent_sweep_gate(
    node: Option<u32>,
    iters: u32,
    tokens: u32,
    block_size: u32,
    split_pages: Option<u32>,
    max_stage1_token_rows: Option<u32>,
    heads: u32,
    plan_only: bool,
) -> Result<()> {
    println!(
        "mainarch gpu-paged-mla-fp8-splitk-full-latent-sweep-gate - retained FP8/E4M3 MLA split-K sweep over all 512 latent output dims, no ROCm\n"
    );
    let node_id = match node {
        Some(n) => n,
        None if plan_only => 2,
        None => {
            let gpus = mcore::enumerate_gpus()?;
            gpus.first()
                .map(|g| g.node_id)
                .ok_or_else(|| anyhow::anyhow!("no GPU nodes under /sys/class/kfd"))?
        }
    };
    let total_pages = tokens.saturating_add(block_size.saturating_sub(1)) / block_size.max(1);
    let default_split_pages = total_pages.saturating_add(63) / 64;
    let split_pages = split_pages.unwrap_or(default_split_pages.max(1));
    let max_stage1_token_rows = max_stage1_token_rows.unwrap_or(tokens);
    mcore::gpu_paged_mla_fp8_splitk_full_latent_sweep_gate(
        node_id,
        iters,
        tokens,
        block_size,
        split_pages,
        max_stage1_token_rows,
        heads,
        plan_only,
    )
}

