fn gpu_allreduce_check(node: Option<u32>, n: u32, parts: u32) -> Result<()> {
    println!("mainarch gpu-allreduce-check: GPU reduce vs CPU oracle\n");
    let node_id = match node {
        Some(n) => n,
        None => mcore::enumerate_gpus()?
            .first()
            .map(|g| g.node_id)
            .ok_or_else(|| anyhow::anyhow!("no GPU nodes under /sys/class/kfd"))?,
    };
    let elapsed = mcore::gpu_check_allreduce(node_id, n, parts)?;
    let bytes = (n as usize) * (parts as usize) * 4;
    println!(
        "  PASS node {node_id}: reduced {parts} x {n} f32 ({:.1} MiB) bit-exact vs CPU in {:?}",
        bytes as f64 / (1024.0 * 1024.0),
        elapsed
    );
    Ok(())
}

fn gpu_multi_check(nodes: Option<String>, n: u32) -> Result<()> {
    println!("mainarch gpu-multi-check: multi-GPU all-reduce over XGMI vs CPU oracle\n");
    let nodes = parse_nodes(nodes)?;
    if nodes.is_empty() {
        return Err(anyhow::anyhow!("no GPU nodes available"));
    }
    println!("  ranks: {} on nodes {:?}", nodes.len(), nodes);
    let elapsed = mcore::multigpu::check(&nodes, n)?;
    let bytes = (n as usize) * 4;
    println!(
        "  PASS: {}-GPU all-reduce of {n} f32 ({:.2} MiB/rank) bit-exact vs CPU in {:?}",
        nodes.len(),
        bytes as f64 / (1024.0 * 1024.0),
        elapsed
    );
    Ok(())
}

fn gpu_allreduce_bench(
    nodes: Option<String>,
    min_bytes: usize,
    max_bytes: usize,
    iters: usize,
    warmup: usize,
) -> Result<()> {
    println!("mainarch gpu-allreduce-bench: multi-GPU all-reduce over XGMI (no ROCm)\n");
    let nodes = parse_nodes(nodes)?;
    if nodes.is_empty() {
        return Err(anyhow::anyhow!("no GPU nodes available"));
    }
    println!("  ranks: {} on nodes {:?}\n", nodes.len(), nodes);
    println!(
        "  {:>12}  {:>11}  {:>11}  {:>13}  {:>13}",
        "size(B)", "count(f32)", "time(us)", "algbw(GB/s)", "busbw(GB/s)"
    );
    println!("  {}", "-".repeat(70));
    let rows = mcore::multigpu::benchmark_sweep(&nodes, min_bytes, max_bytes, iters, warmup)?;
    for r in &rows {
        println!(
            "  {:>12}  {:>11}  {:>11.2}  {:>13.2}  {:>13.2}",
            r.bytes,
            r.count,
            r.time.as_secs_f64() * 1e6,
            r.algbw_gbps,
            r.busbw_gbps,
        );
    }
    Ok(())
}

