fn gpu_allreduce_tp8_decode_gate(nodes: Option<String>, iters: usize, warmup: usize) -> Result<()> {
    println!(
        "mainarch gpu-allreduce-tp8-decode-gate - TP8 resident peer-flag DDA all-reduce over decode-sized payloads (no ROCm)\n"
    );
    let nodes = parse_nodes(nodes)?;
    if nodes.len() != 8 {
        return Err(anyhow::anyhow!(
            "TP8 decode gate requires exactly 8 GPU ranks; got {} nodes {:?}",
            nodes.len(),
            nodes
        ));
    }
    const MIN_BYTES: usize = 8 * 1024;
    const MAX_BYTES: usize = 256 * 1024;
    println!("  ranks: {} on nodes {:?}", nodes.len(), nodes);
    println!("  mode : persistent-dda-flat-peer-flags");
    println!("  gate : decode-payloads 8KiB..256KiB, rank0 host trigger, device peer flags");
    println!("  rccl : all_reduce_perf -b 8192 -e 262144 -f 2 -g 1, 8 ranks, float sum\n");
    println!(
        "  {:>12}  {:>11}  {:>11}  {:>13}  {:>13}",
        "size(B)", "count(f32)", "time(us)", "algbw(GB/s)", "busbw(GB/s)"
    );
    println!("  {}", "-".repeat(70));
    let rows = mcore::multigpu::benchmark_persistent_dda_peer_flat_sweep(
        &nodes, MIN_BYTES, MAX_BYTES, iters, warmup,
    )?;
    for r in &rows {
        println!(
            "  {:>12}  {:>11}  {:>11.2}  {:>13.2}  {:>13.2}",
            r.bytes,
            r.count,
            r.time.as_secs_f64() * 1e6,
            r.algbw_gbps,
            r.busbw_gbps,
        );
    }
    let best = rows
        .iter()
        .map(|row| row.busbw_gbps)
        .fold(0.0_f64, f64::max);
    println!(
        "\n  tp8-decode-gate: status PASS, ranks {}, sizes {}..{} B, rows {}, best_busbw {:.2} GB/s, correctness bit_exact, rccl_compare_shape explicit",
        nodes.len(),
        MIN_BYTES,
        MAX_BYTES,
        rows.len(),
        best,
    );
    Ok(())
}

