fn gpu_fp8_packed_dot_bench(
    node: Option<u32>,
    count: usize,
    iters: usize,
    warmup: usize,
    group_size: usize,
) -> Result<()> {
    println!(
        "mainarch gpu-fp8-packed-dot-bench - consume OCP E4M3 activations with packed E8M0 group scales (no ROCm)\n"
    );
    let node_id = first_gpu_or(node)?;
    let mut dev = mcore::GpuDevice::open(node_id)?;
    let n = count.max(1);
    let group_size = group_size.max(1);
    let groups = n.div_ceil(group_size);
    let packed_words = groups.div_ceil(4);
    let num_wg = fp8_dot_wg();
    let mut q = dev.alloc_device(n)?;
    let mut scales_packed = dev.alloc_device(packed_words * 4)?;
    let mut scales_f32 = dev.alloc_device(groups * 4)?;
    let mut weight = dev.alloc_device(n * 4)?;
    let partial = dev.alloc_device(num_wg as usize * 4)?;
    let mut gbar = dev.alloc_device(64)?;
    let mut out = dev.alloc(4)?;
    let q_pattern = [0x30u8, 0x34, 0x38, 0x39, 0x3a, 0x3b, 0x40, 0x41];
    let mut expected = 0.0f64;
    unsafe {
        let qv = q.as_mut_slice_of::<u8>();
        let sp = scales_packed.as_mut_slice_of::<u32>();
        let sf = scales_f32.as_mut_slice_of::<f32>();
        let w = weight.as_mut_slice_of::<f32>();
        for v in sp.iter_mut() {
            *v = 0;
        }
        for group in 0..groups {
            let code = 122u8 + (group % 11) as u8;
            sf[group] = host_e8m0_to_f32(code);
            sp[group / 4] |= (code as u32) << ((group & 3) * 8);
        }
        for i in 0..n {
            let qb = q_pattern[(i + (i / group_size)) & (q_pattern.len() - 1)];
            let wt = 0.25f32 + ((i * 17 + 3) % 31) as f32 * 0.03125f32;
            qv[i] = qb;
            w[i] = wt;
            expected += host_e4m3_ocp_to_f32(qb) as f64 * sf[i / group_size] as f64 * wt as f64;
        }
    }

    let mut run = |packed: bool| -> Result<(std::time::Duration, f64, f64)> {
        let timeout = std::time::Duration::from_secs(5);
        for _ in 0..warmup {
            reset_fp8_dot_sync(&mut gbar, &mut out);
            if packed {
                dev.arm_fp8_packed_scale_dot(
                    q.va(),
                    scales_packed.va(),
                    weight.va(),
                    partial.va(),
                    gbar.va(),
                    out.va(),
                    n as u32,
                    group_size as u32,
                    num_wg,
                )?;
            } else {
                dev.arm_fp8_f32_scale_dot(
                    q.va(),
                    scales_f32.va(),
                    weight.va(),
                    partial.va(),
                    gbar.va(),
                    out.va(),
                    n as u32,
                    group_size as u32,
                    num_wg,
                )?;
            }
            dev.wait(timeout)?;
        }
        let mut total = std::time::Duration::ZERO;
        for _ in 0..iters.max(1) {
            reset_fp8_dot_sync(&mut gbar, &mut out);
            let start = std::time::Instant::now();
            if packed {
                dev.arm_fp8_packed_scale_dot(
                    q.va(),
                    scales_packed.va(),
                    weight.va(),
                    partial.va(),
                    gbar.va(),
                    out.va(),
                    n as u32,
                    group_size as u32,
                    num_wg,
                )?;
            } else {
                dev.arm_fp8_f32_scale_dot(
                    q.va(),
                    scales_f32.va(),
                    weight.va(),
                    partial.va(),
                    gbar.va(),
                    out.va(),
                    n as u32,
                    group_size as u32,
                    num_wg,
                )?;
            }
            dev.wait(timeout)?;
            total += start.elapsed();
        }
        let avg = total / iters.max(1) as u32;
        let got = unsafe { out.as_mut_slice_of::<f32>()[0] as f64 };
        let rel = (got - expected).abs() / expected.abs().max(1e-12);
        Ok((avg, got, rel))
    };

    let (packed_time, packed_got, packed_rel) = run(true)?;
    let (f32_time, f32_got, f32_rel) = run(false)?;
    if packed_rel > 5e-4 || f32_rel > 5e-4 {
        return Err(anyhow::anyhow!(
            "fp8 packed dot mismatch: packed_rel={packed_rel:.3e}, f32_rel={f32_rel:.3e}, expected={expected:.9e}, packed={packed_got:.9e}, f32={f32_got:.9e}"
        ));
    }
    println!("  node : {node_id}");
    println!("  count: {n}");
    println!("  group: {group_size}");
    println!("  wg   : {num_wg}");
    println!(
        "  {:>16}  {:>11}  {:>14}  {:>11}",
        "mode", "time(us)", "result", "max_rel"
    );
    println!("  {}", "-".repeat(62));
    println!(
        "  {:>16}  {:>11.2}  {:>14.6e}  {:>11.2e}",
        "packed-e8m0",
        packed_time.as_secs_f64() * 1e6,
        packed_got,
        packed_rel,
    );
    println!(
        "  {:>16}  {:>11.2}  {:>14.6e}  {:>11.2e}",
        "f32-scale",
        f32_time.as_secs_f64() * 1e6,
        f32_got,
        f32_rel,
    );
    Ok(())
}

fn fp8_dot_wg() -> u32 {
    std::env::var("MAINARCH_FP8_DOT_WG")
        .ok()
        .and_then(|v| v.parse::<u32>().ok())
        .filter(|&v| v > 0)
        .unwrap_or(32)
        .min(64)
}

fn reset_fp8_dot_sync(gbar: &mut mcore::DeviceBuffer, out: &mut mcore::DeviceBuffer) {
    unsafe {
        for v in gbar.as_mut_slice_of::<u32>().iter_mut() {
            *v = 0;
        }
        out.as_mut_slice_of::<f32>()[0] = 0.0;
    }
}

fn host_e8m0_to_f32(x: u8) -> f32 {
    2.0f32.powi(x as i32 - 127)
}

fn host_e4m3_ocp_to_f32(b: u8) -> f32 {
    let sign = (b & 0x80) != 0;
    let exp = (b >> 3) & 0x0f;
    let mant = b & 0x07;
    let v = if exp == 0 {
        mant as f32 * 0.001953125
    } else {
        (1.0 + mant as f32 * 0.125) * 2.0f32.powi(exp as i32 - 7)
    };
    if sign {
        -v
    } else {
        v
    }
}

fn sdma_selftest(node: Option<u32>, mb: usize) -> Result<()> {
    println!("mainarch sdma-selftest: SDMA copy engine via raw KFD (no ROCm)\n");
    let node_id = first_gpu_or(node)?;
    let dev = mcore::GpuDevice::open(node_id)?;
    let bytes = mb * 1024 * 1024;
    let n = bytes / 4;
    let mut src = dev.alloc_device(bytes)?;
    let mut dst = dev.alloc_device(bytes)?;
    unsafe {
        let s = src.as_mut_slice_of::<u32>();
        for (i, v) in s.iter_mut().enumerate().take(n) {
            *v = (i as u32).wrapping_mul(2654435761) ^ 0xa5a5_a5a5;
        }
        for v in dst.as_mut_slice_of::<u32>().iter_mut().take(n) {
            *v = 0;
        }
    }
    let mut sdma = mcore::SdmaQueue::new(dev.kfd(), node_id)?;
    let to = std::time::Duration::from_secs(10);
    for _ in 0..3 {
        sdma.copy(src.va(), dst.va(), bytes, to)?; // warmup
    }
    let iters = 20;
    let t = std::time::Instant::now();
    for _ in 0..iters {
        sdma.copy(src.va(), dst.va(), bytes, to)?;
    }
    let us = t.elapsed().as_secs_f64() * 1e6 / iters as f64;
    let s = unsafe { src.as_mut_slice_of::<u32>() };
    let d = unsafe { dst.as_mut_slice_of::<u32>() };
    let bad = (0..n).filter(|&i| s[i] != d[i]).count();
    if bad > 0 {
        return Err(anyhow::anyhow!(
            "SDMA local copy MISMATCH: {bad}/{n} dwords wrong (first few: dst[0]={:#x} src[0]={:#x})",
            d[0],
            s[0]
        ));
    }
    let gbps = bytes as f64 / (us / 1e6) / 1e9;
    println!("  SDMA local copy {mb} MiB on node {node_id}: bit-exact; {us:.1} µs, {gbps:.0} GB/s (read+write local HBM)");
    Ok(())
}

/// Validate the device-side coordination primitives: SDMA FENCE (the engine
/// writes a memory semaphore) and POLL_REGMEM (the engine stalls on a memory
/// semaphore until set). These let the SDMA engine self-sequence with a kernel
/// over memory, no host round-trips — the enabler for a device-side dual-path
/// all-reduce that realizes the 378 GB/s egress in the collective.
fn sdma_sem_selftest(node: Option<u32>) -> Result<()> {
    println!("mainarch sdma-sem-selftest: SDMA FENCE + POLL_REGMEM via raw KFD (no ROCm)\n");
    let node_id = first_gpu_or(node)?;
    let dev = mcore::GpuDevice::open(node_id)?;
    let bytes = 1 << 20; // 1 MiB copy payload
    let n = bytes / 4;
    let mut src = dev.alloc_device(bytes)?;
    let mut dst = dev.alloc_device(bytes)?;
    let mut sem = dev.alloc_device(4096)?; // semaphore page (host-visible VRAM)
    unsafe {
        let s = src.as_mut_slice_of::<u32>();
        for (i, v) in s.iter_mut().enumerate().take(n) {
            *v = (i as u32).wrapping_mul(2654435761) ^ 0x1234_5678;
        }
        for v in dst.as_mut_slice_of::<u32>().iter_mut().take(n) {
            *v = 0;
        }
        for v in sem.as_mut_slice_of::<u32>().iter_mut().take(2) {
            *v = 0;
        }
    }
    let sem_ptr = unsafe { sem.as_mut_slice_of::<u32>().as_mut_ptr() };
    let fence_va = sem.va(); // sem[0]: written by FENCE
    let release_va = sem.va() + 64; // sem[16]: polled by POLL_REGMEM, set by host
    let mut sdma = mcore::SdmaQueue::new(dev.kfd(), node_id)?;
    let to = std::time::Duration::from_secs(5);

    // --- Test 1: FENCE writes a memory semaphore ---
    sdma.push_fence(fence_va, 0xABCD_1234);
    sdma.commit();
    sdma.wait(to)?;
    let got = unsafe { std::ptr::read_volatile(sem_ptr) };
    if got != 0xABCD_1234 {
        return Err(anyhow::anyhow!(
            "FENCE failed: sem[0]={got:#x}, expected 0xABCD1234"
        ));
    }
    println!("  [1/2] FENCE: SDMA wrote sem[0]=0x{got:08x} ✓");

    // --- Test 2: POLL_REGMEM stalls the copy until the semaphore is set ---
    sdma.push_poll_eq(release_va, 1, 0xffff_ffff); // wait until sem[16]==1
    sdma.push_copy(src.va(), dst.va(), bytes);
    sdma.commit();
    // While the release semaphore is 0, the engine must be stalled: dst stays 0.
    let dst_ptr = unsafe { dst.as_mut_slice_of::<u32>() }.as_ptr();
    let mut leaked = false;
    for _ in 0..200_000 {
        if unsafe { std::ptr::read_volatile(dst_ptr) } != 0 {
            leaked = true;
            break;
        }
        std::hint::spin_loop();
    }
    if leaked {
        return Err(anyhow::anyhow!(
            "POLL_REGMEM did not stall: copy ran before the semaphore was set"
        ));
    }
    // Release: set sem[16]=1; the engine should now run the copy.
    unsafe {
        std::ptr::write_volatile((sem_ptr as *mut u8).add(64) as *mut u32, 1);
        std::sync::atomic::fence(std::sync::atomic::Ordering::Release);
    }
    sdma.wait(to)?;
    let d = unsafe { dst.as_mut_slice_of::<u32>() };
    let s = unsafe { src.as_mut_slice_of::<u32>() };
    let bad = (0..n).filter(|&i| s[i] != d[i]).count();
    if bad > 0 {
        return Err(anyhow::anyhow!(
            "post-release copy MISMATCH: {bad}/{n} dwords wrong"
        ));
    }
    println!("  [2/2] POLL_REGMEM: copy stalled until sem[16]=1, then ran bit-exact ✓");
    println!("\n  device-side SDMA coordination primitives validated.");
    Ok(())
}

fn sdma_p2p_bench(
    nodes: Option<String>,
    engines: usize,
    qpp: usize,
    general: usize,
    kfrac: usize,
    mb: usize,
) -> Result<()> {
    println!("mainarch sdma-p2p-bench: multi-engine SDMA over XGMI (no ROCm)\n");
    let qpp = qpp.max(1);
    let nodes = parse_nodes(nodes)?;
    if nodes.len() < 2 {
        return Err(anyhow::anyhow!("need >=2 GPU nodes for P2P"));
    }
    let a = nodes[0];
    // `engines` caps how many peers (links) to fan across; default = all peers.
    let peers: Vec<u32> = if engines >= nodes.len() - 1 || engines == 0 {
        nodes[1..].to_vec()
    } else {
        nodes[1..1 + engines].to_vec()
    };
    let np = peers.len();
    let kfd = std::sync::Arc::new(mcore::Kfd::open()?);
    let mut devs = vec![mcore::GpuDevice::open_shared(kfd.clone(), a)?];
    for &p in &peers {
        devs.push(mcore::GpuDevice::open_shared(kfd.clone(), p)?);
    }
    let per = (((mb * 1024 * 1024) / np) + 0xffff) & !0xffff; // per-peer slice, 64 KiB-aligned
    let total = per * np;
    let mut src = kfd.alloc_vram(a, total)?;
    unsafe {
        for (i, v) in src.as_mut_slice_of::<u32>().iter_mut().enumerate() {
            *v = (i as u32).wrapping_mul(2654435761) ^ 0x5a5a_5a5a;
        }
    }
    // One dst buffer per peer (on that peer), mapped into A; one XGMI queue per link.
    let mut dsts = Vec::with_capacity(np);
    let mut qs = Vec::new();
    let mut qstart = Vec::with_capacity(np);
    let mut qcount = Vec::with_capacity(np);
    for (pi, &p) in peers.iter().enumerate() {
        let mut d = kfd.alloc_vram(p, per)?;
        unsafe {
            for v in d.as_mut_slice_of::<u32>().iter_mut() {
                *v = 0;
            }
        }
        kfd.map_buffer_to_peer(&d, a)?;
        dsts.push(d);
        qstart.push(qs.len());
        for _ in 0..qpp {
            qs.push(mcore::SdmaQueue::new_xgmi(&kfd, a)?); // XGMI copy engines
        }
        if pi < general {
            qs.push(mcore::SdmaQueue::new(&kfd, a)?); // + a general copy engine
        }
        qcount.push(qs.len() - qstart[pi]);
    }
    let src_va = src.va();
    // Hybrid split: SDMA copies the first `sdma_bytes` of each peer slice; the CU
    // p2p_write kernel writes the remaining [sdma_bytes, per) — two independent
    // XGMI write paths (DMA engines + CU stores) firing simultaneously.
    let kfrac = kfrac.min(100);
    let sdma_bytes = if kfrac == 0 {
        per
    } else {
        ((per * (100 - kfrac) / 100) & !0xffff).min(per)
    };
    let kbytes = per - sdma_bytes;
    // Peer-buffer VA table on A (GPU-visible), for the kernel's dst lookup.
    let mut peer_tbl = kfd.alloc_vram(a, (np * 8).max(64))?;
    unsafe {
        let t = peer_tbl.as_mut_slice_of::<u64>();
        for (i, d) in dsts.iter().enumerate() {
            t[i] = d.va();
        }
    }
    let peer_tbl_va = peer_tbl.va();
    let per4 = (per / 16) as u32;
    let kstart4 = (sdma_bytes / 16) as u32;
    let kcount4 = (kbytes / 16) as u32;
    let kwg = (np as u32) * 32;
    let to = std::time::Duration::from_secs(10);
    let mut run = || -> Result<()> {
        // SDMA copies for the first `sdma_bytes` of each peer slice.
        for i in 0..np {
            if sdma_bytes == 0 {
                break;
            }
            let (sbase, dbase) = (src_va + (i * per) as u64, dsts[i].va());
            let k = qcount[i];
            let sub = (((sdma_bytes / k) + 0xffff) & !0xffff).max(0x10000);
            for j in 0..k {
                let o = j * sub;
                if o >= sdma_bytes {
                    break;
                }
                let n = sub.min(sdma_bytes - o);
                qs[qstart[i] + j].copy_async(sbase + o as u64, dbase + o as u64, n);
            }
        }
        // Concurrently, the CU-store kernel writes the remaining tail of each slice.
        if kcount4 > 0 {
            devs[0].arm_p2p_write(src_va, peer_tbl_va, np as u32, per4, kstart4, kcount4, kwg)?;
        }
        for q in qs.iter() {
            if sdma_bytes == 0 {
                break;
            }
            q.wait(to)?;
        }
        if kcount4 > 0 {
            devs[0].wait(to)?;
        }
        Ok(())
    };
    for _ in 0..3 {
        run()?;
    }
    let iters = 20;
    let t = std::time::Instant::now();
    for _ in 0..iters {
        run()?;
    }
    let us = t.elapsed().as_secs_f64() * 1e6 / iters as f64;
    let s = unsafe { src.as_mut_slice_of::<u32>() };
    let mut bad = 0usize;
    for (i, d) in dsts.iter_mut().enumerate() {
        let dd = unsafe { d.as_mut_slice_of::<u32>() };
        bad += (0..per / 4)
            .filter(|&k| dd[k] != s[i * per / 4 + k])
            .count();
    }
    if bad > 0 {
        return Err(anyhow::anyhow!("SDMA P2P MISMATCH: {bad} dwords wrong"));
    }
    let gbps = total as f64 / (us / 1e6) / 1e9;
    println!(
        "  SDMA P2P from node {a} to {np} peers ({} MiB total): bit-exact; {us:.1} µs, {gbps:.0} GB/s aggregate XGMI write/gpu",
        total / (1 << 20)
    );
    Ok(())
}

fn allreduce_probe(
    nodes: Option<String>,
    n: u32,
    iters: usize,
    target_gbps: Option<f64>,
) -> Result<()> {
    if matches!(target_gbps, Some(t) if t <= 0.0) {
        return Err(anyhow::anyhow!("--target-gbps must be positive"));
    }
    let nodes = parse_nodes(nodes)?;
    let mut ar = mcore::multigpu::AllReduce::new(&nodes, n)?;
    let (sc, lr, ag) = ar.probe_phases(iters)?;
    let bytes = n as usize * 4;
    let r = nodes.len() as f64;
    let xgmi = (r - 1.0) / r * bytes as f64; // per-GPU XGMI write bytes per push phase
    let bw = |d: std::time::Duration, b: f64| b / d.as_secs_f64() / 1e9;
    println!(
        "mainarch allreduce-probe: {} ranks, {} MiB/rank",
        nodes.len(),
        bytes / (1 << 20)
    );
    let sc_bw = bw(sc, xgmi);
    let ag_bw = bw(ag, xgmi);
    println!(
        "  scatter:      {:8.1} us   {:7.1} GB/s/gpu XGMI write",
        sc.as_secs_f64() * 1e6,
        sc_bw
    );
    println!(
        "  local-reduce: {:8.1} us   (local HBM)",
        lr.as_secs_f64() * 1e6
    );
    println!(
        "  all-gather:   {:8.1} us   {:7.1} GB/s/gpu XGMI write",
        ag.as_secs_f64() * 1e6,
        ag_bw
    );
    let total = sc + lr + ag;
    println!("  phase sum:    {:8.1} us", total.as_secs_f64() * 1e6);
    let (phase, phase_bw) = if sc_bw <= ag_bw {
        ("scatter/reduce", sc_bw)
    } else {
        ("all-gather", ag_bw)
    };
    println!("  bottleneck:   {phase} at {phase_bw:.1} GB/s/gpu XGMI write");
    if let Some(target) = target_gbps {
        println!(
            "  target:       {:.1} GB/s/gpu; bottleneck is {:.1}% of target (gap {:.1} GB/s/gpu)",
            target,
            phase_bw / target * 100.0,
            (target - phase_bw).max(0.0)
        );
    }
    Ok(())
}

fn probe() -> Result<()> {
    println!("mainarch probe: kernel ABI, no ROCm\n");

    match mcore::Kfd::open() {
        Ok(kfd) => match kfd.driver_version() {
            Ok((maj, min)) => println!("  /dev/kfd   : open OK, amdkfd driver v{maj}.{min}"),
            Err(e) => println!("  /dev/kfd   : open OK, but GET_VERSION failed: {e:#}"),
        },
        Err(e) => println!("  /dev/kfd   : UNAVAILABLE: {e:#}"),
    }

    let gpus = mcore::enumerate_gpus()?;
    println!("  topology   : {} GPU node(s)\n", gpus.len());
    if gpus.is_empty() {
        println!("  (no GPU nodes under /sys/class/kfd: device passed in? amdgpu loaded?)");
        return Ok(());
    }

    let topo = mcore::enumerate_topology()?;
    if !topo.links.is_empty() {
        println!("  top-links : {}", topo.links.len());
        for link in topo.links.iter().take(8) {
            println!(
                "    node {} -> {}  kind={}  max_bw={}MB/s  weight={}  flags={}",
                link.from_node,
                link.to_node,
                link.kind,
                link.max_bandwidth,
                link.weight,
                link.flags,
            );
        }
    }

    println!(
        "  {:<5} {:<9} {:<26} {:>6} {:>10}",
        "node", "arch", "name", "SIMDs", "VRAM(GiB)"
    );
    println!("  {}", "-".repeat(60));
    for g in &gpus {
        println!(
            "  {:<5} {:<9} {:<26} {:>6} {:>10.1}",
            g.node_id,
            g.gfx(),
            truncate(&g.name, 26),
            g.simd_count,
            g.vram_gib()
        );
    }
    Ok(())
}

fn rccl_all_reduce(
    min_bytes: usize,
    max_bytes: usize,
    iters: usize,
    ranks: usize,
    backend: Backend,
    nodes: Option<String>,
    target_busbw_gbps: Option<f64>,
) -> Result<()> {
    if matches!(target_busbw_gbps, Some(t) if t <= 0.0) {
        return Err(anyhow::anyhow!("--target-busbw-gbps must be positive"));
    }
    let (backend_name, rows, effective_ranks) = if matches!(backend, Backend::GpuXgmi) {
        run_gpu_xgmi_sweep("selected", nodes, min_bytes, max_bytes, ranks, iters)?
    } else {
        let (mut backend, effective_ranks) = build_backend(backend, ranks)?;
        let backend_name = backend.name().to_string();
        let rows = mcoll::all_reduce_sweep(
            backend.as_mut(),
            min_bytes,
            max_bytes,
            effective_ranks,
            iters,
        )?;
        (backend_name, rows, effective_ranks)
    };
    println!(
        "rccl-test all-reduce   backend={}   ranks={}   iters={}\n",
        backend_name, effective_ranks, iters
    );
    if let Some(target) = target_busbw_gbps {
        println!(
            "  {:>12} {:>11} {:>11} {:>13} {:>13} {:>9}  ok",
            "size(B)", "count(f32)", "time(us)", "algbw(GB/s)", "busbw(GB/s)", "target%"
        );
        println!("  {}", "-".repeat(94));
        for r in &rows {
            println!(
                "  {:>12} {:>11} {:>11.2} {:>13.2} {:>13.2} {:>8.1}%  {}",
                r.bytes,
                r.count,
                r.time_us,
                r.alg_bw_gbps,
                r.bus_bw_gbps,
                r.bus_bw_gbps / target * 100.0,
                if r.correct { "ok" } else { "FAIL" }
            );
        }
        if let Some(best) = rows
            .iter()
            .max_by(|a, b| a.bus_bw_gbps.total_cmp(&b.bus_bw_gbps))
        {
            println!(
                "\n  target busbw: {:.2} GB/s; best observed: {:.2} GB/s ({:.1}% of target, gap {:.2} GB/s)",
                target,
                best.bus_bw_gbps,
                best.bus_bw_gbps / target * 100.0,
                (target - best.bus_bw_gbps).max(0.0)
            );
        }
    } else {
        println!(
            "  {:>12} {:>11} {:>11} {:>13} {:>13}  ok",
            "size(B)", "count(f32)", "time(us)", "algbw(GB/s)", "busbw(GB/s)"
        );
        println!("  {}", "-".repeat(82));
        for r in &rows {
            println!(
                "  {:>12} {:>11} {:>11.2} {:>13.2} {:>13.2}  {}",
                r.bytes,
                r.count,
                r.time_us,
                r.alg_bw_gbps,
                r.bus_bw_gbps,
                if r.correct { "ok" } else { "FAIL" }
            );
        }
    }

    println!("\n  NOTE: CPU backend remains the correctness oracle.");
    let is_simulation_placeholder =
        backend_name.contains("mock") || backend_name.contains("parallel");
    let is_topology_backend = backend_name.contains("kfd-topology");
    if is_simulation_placeholder {
        println!(
            "  [WARNING] Simulation backend selected (cpu-mock/cpu-parallel): not a transport implementation."
        );
    } else if is_topology_backend {
        println!("  [WARNING] gpu-topology backend surfaces topology plan only; transport is placeholder.");
    } else if backend_name.contains("gpu-reference") {
        println!("  GPU backend here is a kernel-ABI-aware single-rank stepping stone.");
    } else if backend_name.contains("raw-kfd-xgmi") {
        println!("  gpu-xgmi backend is the real raw KFD/XGMI multi-GPU all-reduce path.");
    } else {
        println!("  CPU reference backend is a correctness oracle and computes in one rank.");
    }
    println!("  Real GPU/XGMI backends implement `Collective` behind this same harness.");
    Ok(())
}

fn rccl_all_reduce_compare(
    min_bytes: usize,
    max_bytes: usize,
    iters: usize,
    ranks: usize,
    lhs: Backend,
    rhs: Backend,
    nodes: Option<String>,
) -> Result<()> {
    let (lhs_name, lhs_rows, lhs_effective) = run_all_reduce_sweep(
        lhs,
        "lhs",
        nodes.clone(),
        min_bytes,
        max_bytes,
        ranks,
        iters,
    )?;
    let (rhs_name, rhs_rows, rhs_effective) =
        run_all_reduce_sweep(rhs, "rhs", nodes, min_bytes, max_bytes, ranks, iters)?;
    println!(
        "rccl-test compare all-reduce   lhs={}   rhs={}   requested_ranks={}   lhs_ranks={}   rhs_ranks={}   iters={}\n",
        lhs_name, rhs_name, ranks, lhs_effective, rhs_effective, iters
    );
    if lhs_effective != rhs_effective {
        println!(
            "  [WARNING] effective rank counts differ; busbw uses each backend's own rccl-tests all-reduce factor, so speedup is not an apples-to-apples transport comparison."
        );
    }
    println!(
        "  [metric] algbw=size/time; all-reduce busbw=algbw*2*(ranks-1)/ranks, matching rccl-tests/NCCL-tests convention.\n"
    );
    println!(
        "  {:>12} {:>13} {:>13} {:>12} {:>12}  ok-l  ok-r",
        "size(B)", "lhs_busbw", "rhs_busbw", "speedup", "delta%"
    );
    println!("  {}", "-".repeat(78));

    for (l, r) in lhs_rows.iter().zip(rhs_rows.iter()) {
        let (speedup, delta_pct) = if l.bus_bw_gbps > 0.0 {
            (
                (r.bus_bw_gbps / l.bus_bw_gbps),
                ((r.bus_bw_gbps - l.bus_bw_gbps) / l.bus_bw_gbps) * 100.0,
            )
        } else {
            (0.0, 0.0)
        };
        let ok = if l.correct && r.correct { "ok" } else { "FAIL" };
        println!(
            "  {:>12} {:>13.2} {:>13.2} {:>12.2} {:>12.2}  {:>4}  {:>4}",
            l.bytes, l.bus_bw_gbps, r.bus_bw_gbps, speedup, delta_pct, ok, ok
        );
    }

    let rhs_is_better = lhs_rows
        .iter()
        .filter_map(|l| {
            let r = rhs_rows.iter().find(|row| row.bytes == l.bytes)?;
            if l.bus_bw_gbps > 0.0 {
                Some(r.bus_bw_gbps / l.bus_bw_gbps)
            } else {
                None
            }
        })
        .any(|ratio| ratio >= 1.0);

    if rhs_is_better {
        println!("\n  STATUS: rhs is ahead at one or more sweep points.");
    } else {
        println!("\n  STATUS: rhs is behind at all sweep points.");
    }

    Ok(())
}

fn run_all_reduce_sweep(
    backend: Backend,
    side: &str,
    nodes: Option<String>,
    min_bytes: usize,
    max_bytes: usize,
    ranks: usize,
    iters: usize,
) -> Result<(String, Vec<mcoll::BenchRow>, usize)> {
    if matches!(backend, Backend::GpuXgmi) {
        return run_gpu_xgmi_sweep(side, nodes, min_bytes, max_bytes, ranks, iters);
    }
    let mut backend: Box<dyn mcoll::Collective> = match backend {
        Backend::Cpu => {
            println!("  [setup] {side} backend: CPU reference (single-rank)");
            Box::new(mcoll::CpuReference)
        }
        Backend::GpuTopology => {
            println!("  [setup] {side} backend: KFD topology placeholder");
            Box::new(mcoll::KfdTopologyBackend::new()?)
        }
        Backend::CpuMock => {
            println!(
                "  [setup] {side} backend: CPU multi-rank simulation (placeholder transport)."
            );
            Box::new(mcoll::CpuRankedMock::new(ranks)?)
        }
        Backend::CpuParallel => {
            println!(
                "  [setup] {side} backend: CPU parallel multi-rank simulation (threaded placeholder transport)."
            );
            Box::new(mcoll::CpuRankedParallel::new(ranks, None)?)
        }
        Backend::Gpu => {
            println!("  [setup] {side} backend: GPU reference (single-rank)");
            Box::new(mcoll::GpuSingleRank::new()?)
        }
        Backend::GpuXgmi => unreachable!("handled above"),
    };
    let effective_ranks = ranks.max(1).min(backend.ranks().max(1));
    if effective_ranks != ranks {
        println!(
            "  [setup] {side} requested ranks={ranks} but backend exposes {effective_ranks}; using {effective_ranks} for bus-bandwidth factor."
        );
    }
    let rows = mcoll::all_reduce_sweep(
        backend.as_mut(),
        min_bytes,
        max_bytes,
        effective_ranks,
        iters,
    )?;
    Ok((backend.name().to_string(), rows, effective_ranks))
}

fn run_gpu_xgmi_sweep(
    side: &str,
    nodes: Option<String>,
    min_bytes: usize,
    max_bytes: usize,
    ranks: usize,
    iters: usize,
) -> Result<(String, Vec<mcoll::BenchRow>, usize)> {
    let nodes = select_xgmi_nodes(nodes, ranks)?;
    let effective_ranks = nodes.len();
    println!(
        "  [setup] {side} backend: raw KFD/XGMI all-reduce on nodes {:?}",
        nodes
    );
    if effective_ranks != ranks {
        println!(
            "  [setup] {side} requested ranks={ranks} but gpu-xgmi exposes {effective_ranks}; using {effective_ranks} for bus-bandwidth factor."
        );
    }
    let sweep = mcore::multigpu::benchmark_serving_allreduce_sweep(
        mcore::multigpu::ServingAllReducePhase::Decode,
        &nodes,
        min_bytes,
        max_bytes,
        iters,
        1,
    );
    let sweep = sweep?;
    let policy = sweep.policy;
    if let Some(label) = policy.selected_policy_label() {
        println!("  [setup] {side} policy: {label}");
    }
    println!(
        "  [setup] {side} serving policy note: {}",
        policy.serving_note()
    );
    let rows = sweep
        .rows
        .into_iter()
        .map(|r| mcoll::BenchRow {
            bytes: r.bytes,
            count: r.count as usize,
            time_us: r.time.as_secs_f64() * 1e6,
            alg_bw_gbps: r.algbw_gbps,
            bus_bw_gbps: r.busbw_gbps,
            correct: true,
        })
        .collect();
    Ok((sweep.backend_name, rows, effective_ranks))
}

fn select_xgmi_nodes(nodes: Option<String>, requested_ranks: usize) -> Result<Vec<u32>> {
    let nodes = match nodes {
        Some(s) => parse_nodes(Some(s))?,
        None => {
            let mut all = parse_nodes(None)?;
            let want = requested_ranks.max(2).min(all.len());
            all.truncate(want);
            all
        }
    };
    if nodes.len() < 2 {
        return Err(anyhow::anyhow!(
            "gpu-xgmi backend needs at least 2 GPU nodes; got {:?}",
            nodes
        ));
    }
    Ok(nodes)
}

fn build_backend(
    backend: Backend,
    requested_ranks: usize,
) -> Result<(Box<dyn mcoll::Collective>, usize)> {
    let backend: Box<dyn mcoll::Collective> = match backend {
        Backend::Cpu => {
            println!("  selected backend: CPU reference (single-rank)");
            Box::new(mcoll::CpuReference)
        }
        Backend::GpuTopology => {
            let requested_ranks = requested_ranks.max(1);
            println!("  selected backend: KFD topology-aware placeholder - {requested_ranks} ranks (planned)");
            Box::new(mcoll::KfdTopologyBackend::new()?)
        }
        Backend::CpuMock => {
            let requested_ranks = requested_ranks.max(1);
            println!(
                "  selected backend: CPU multi-rank simulation (placeholder transport) - {requested_ranks} ranks"
            );
            Box::new(mcoll::CpuRankedMock::new(requested_ranks)?)
        }
        Backend::CpuParallel => {
            println!(
                "  selected backend: CPU parallel multi-rank simulation (threaded transport placeholder) - {requested_ranks} ranks"
            );
            Box::new(mcoll::CpuRankedParallel::new(requested_ranks, None)?)
        }
        Backend::Gpu => {
            println!("  selected backend: GPU reference (single-rank)");
            Box::new(mcoll::GpuSingleRank::new()?)
        }
        Backend::GpuXgmi => {
            return Err(anyhow::anyhow!(
                "gpu-xgmi backend requires rccl-test's nodes-aware sweep path"
            ));
        }
    };
    let effective_ranks = requested_ranks.max(1).min(backend.ranks().max(1));
    if effective_ranks != requested_ranks {
        println!(
            "  [setup] requested ranks={requested_ranks} but backend exposes {effective_ranks}; using {effective_ranks} for bus-bandwidth factor."
        );
    }
    Ok((backend, effective_ranks))
}

#[derive(Copy, Clone, Debug, ValueEnum)]
enum Backend {
    Cpu,
    GpuTopology,
    CpuMock,
    CpuParallel,
    Gpu,
    GpuXgmi,
}

fn truncate(s: &str, n: usize) -> String {
    if s.chars().count() <= n {
        s.to_string()
    } else {
        let cut: String = s.chars().take(n.saturating_sub(1)).collect();
        format!("{cut}…")
    }
}
